import type {CSSProperties, ReactElement} from 'react';
import {staticFile} from 'remotion';
import {
  type ElementComponentProps,
  narrowParams,
} from '../../../../rendering/shared/element_contracts';

// Shared helpers for the am-* motion elements. This lives outside any element
// root, so the element fingerprint covers only each element's own folder. A
// change here will not invalidate an element's registry hash by itself.
export {narrowParams};
export type {ElementComponentProps};

// Pixel grid. The composition is 1920x1080; one logical px is 6 screen px, so
// the logical space is 320x180. Every snapped position is a multiple of 6 px.
export const LOGICAL_W = 320;
export const LOGICAL_H = 180;
export const LOGICAL_PX = 6;
export const BLOCK_PX = 6;

// Pack-owned Pixel Modernism tokens shared by the motion elements.
export const COLOR = {
  paper: '#F7F4ED',
  panel: '#FFFEFA',
  ink: '#25241F',
  muted: '#615E55',
  rust: '#A94714',
  orange: '#ED6B23',
  rule: '#D5D0C5',
  charcoal: '#1F1F1F',
} as const;

// Families registered by remotion/src/fonts.ts (LOCAL_FONT_FACES).
export const FAMILY = {
  display: 'Gelasio',
  label: 'Departure Mono',
  body: 'Inter',
} as const;

export type ClipTiming = {hold?: number; from?: number; to?: number; speed?: number};

export const clamp = (value: number, min: number, max: number): number => Math.min(max, Math.max(min, value));

export const finiteNumber = (value: unknown, fallback: number): number =>
  typeof value === 'number' && Number.isFinite(value) ? value : fallback;

export const integerIn = (value: unknown, min: number, max: number, fallback: number): number =>
  clamp(Math.round(finiteNumber(value, fallback)), min, max);

export const oneOf = <T extends string>(value: unknown, allowed: readonly T[], fallback: T): T =>
  typeof value === 'string' && (allowed as readonly string[]).includes(value) ? (value as T) : fallback;

// Clip length in frames: `hold` (seconds) wins, otherwise (to - from) / speed.
export const clipFrames = (clip: ClipTiming, fps: number): number => {
  if (typeof clip.hold === 'number' && Number.isFinite(clip.hold)) {
    return Math.max(1, Math.round(clip.hold * fps));
  }
  const speed = typeof clip.speed === 'number' && clip.speed > 0 ? clip.speed : 1;
  const span = (clip.to ?? 0) - (clip.from ?? 0);
  return Math.max(1, Math.round((span / speed) * fps));
};

// Spans as [start_s, end_s] pairs in seconds, sorted by start. Malformed or
// empty spans are dropped. Shared by the presenter overlay and its plate.
export const spanList = (value: unknown): [number, number][] => {
  if (!Array.isArray(value)) return [];
  const spans: [number, number][] = [];
  for (const item of value) {
    if (!Array.isArray(item) || item.length < 2) continue;
    const start = finiteNumber(item[0], Number.NaN);
    const end = finiteNumber(item[1], Number.NaN);
    if (Number.isFinite(start) && Number.isFinite(end) && end > start) spans.push([start, end]);
  }
  return spans.sort((a, b) => a[0] - b[0]);
};

// Clip frames: non-negative finite numbers only.
export const frameList = (value: unknown): number[] =>
  Array.isArray(value)
    ? value.filter((n): n is number => typeof n === 'number' && Number.isFinite(n) && n >= 0)
    : [];

// Start frame of the step that contains `frame`. Stepped motion reads this.
export const stepStart = (frame: number, stepFrames: number): number =>
  Math.floor(frame / stepFrames) * stepFrames;

// Deterministic unit-interval hash of (seed, index). Pure integer math, so a
// seeded order renders the same on every run.
export const hashUnit = (seed: number, index: number): number => {
  let h = (Math.trunc(seed) ^ Math.imul(index + 1, 0x9e3779b1)) >>> 0;
  h = Math.imul(h ^ (h >>> 16), 0x85ebca6b) >>> 0;
  h = Math.imul(h ^ (h >>> 13), 0xc2b2ae35) >>> 0;
  h = (h ^ (h >>> 16)) >>> 0;
  return h / 4294967296;
};

export const easeOutCubic = (t: number): number => {
  const u = 1 - clamp(t, 0, 1);
  return 1 - u * u * u;
};

// Remotion-renderable file. Managed media arrives as an absolute loopback URL
// (run.py rewrites registry `file` values); static public files are relative.
export const renderableFile = (file: string | undefined): string | null => {
  if (!file) return null;
  const value = file.trim();
  if (!value) return null;
  if (/^(https?:|data:|blob:|\/)/.test(value)) return value;
  return staticFile(value);
};

// Element sources come from clip.asset (assetEntry) first, then a static URL in
// params.src. A registry key cannot be looked up from params (see SKILL.md).
export const elementSource = (
  assetEntry: {file?: string; url?: string} | undefined,
  src: string | undefined,
): string | null => renderableFile(assetEntry?.file ?? assetEntry?.url ?? src);

export const pixelImage: CSSProperties = {imageRendering: 'pixelated'};

// ---- Pixel-block wipe -----------------------------------------------------

export type WipeMode = 'cover' | 'reveal';
export type WipePattern = 'diagonal' | 'random' | 'scan';

// Order in [0, 1) for a block. Blocks switch when progress passes their order.
export const wipeOrder = (
  pattern: WipePattern,
  col: number,
  row: number,
  cols: number,
  rows: number,
  seed: number,
): number => {
  if (pattern === 'random') return hashUnit(seed, row * cols + col);
  if (pattern === 'scan') return col / cols;
  return (col + row) / (cols + rows - 1);
};

export type BlockWipePaint = {
  mode: WipeMode;
  /** 0..1. cover: painted once progress passes the order. reveal: cleared as it passes. */
  progress: number;
  color: string;
  pattern: WipePattern;
  seed: number;
};

export const paintBlockWipe = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  paint: BlockWipePaint,
): void => {
  const cols = Math.ceil(width / BLOCK_PX);
  const rows = Math.ceil(height / BLOCK_PX);
  const p = clamp(paint.progress, 0, 1);
  ctx.clearRect(0, 0, width, height);
  ctx.fillStyle = paint.color;
  for (let row = 0; row < rows; row += 1) {
    for (let col = 0; col < cols; col += 1) {
      const order = wipeOrder(paint.pattern, col, row, cols, rows, paint.seed);
      const painted = paint.mode === 'cover' ? order < p : order >= p;
      if (painted) {
        ctx.fillRect(col * BLOCK_PX, row * BLOCK_PX, BLOCK_PX, BLOCK_PX);
      }
    }
  }
};

// Full-frame block wipe layer. Drawn synchronously in the ref callback, so a
// frame is complete when React commits it (no delayRender needed).
export const BlockWipe = ({
  width,
  height,
  paint,
}: {
  width: number;
  height: number;
  paint: BlockWipePaint;
}): ReactElement => (
  <canvas
    ref={(node) => {
      if (!node) return;
      const ctx = node.getContext('2d');
      if (ctx) paintBlockWipe(ctx, width, height, paint);
    }}
    width={width}
    height={height}
    style={{position: 'absolute', left: 0, top: 0, width, height, pointerEvents: 'none'}}
  />
);

import {type CSSProperties, type ReactElement, useEffect, useLayoutEffect, useRef, useState} from 'react';
import {cancelRender, continueRender, delayRender} from 'remotion';

// Mosaic (pixelate) helpers shared by am-snap-plate and am-footage: the
// signature move between real footage and the pixel world. A picture is
// averaged into cells of `block` screen px (aligned to the canvas origin, so a
// 6 px block lands exactly on the 320x180 logical grid at 1920x1080) and drawn
// back up with nearest-neighbour sampling.
//
// Steps are hard: a mosaic ramp is a list of block sizes, each held for
// `stepFrames` frames. Nothing eases.

export type Rect = {x: number; y: number; w: number; h: number};
export type MosaicRamp = {frames?: number; from?: number; to?: number; steps?: number[]};

// Default ramp for "into the pixel world": the 6 px grid first (320x180), then
// 12, 24 and 48 px blocks.
export const DEFAULT_STEPS = [6, 12, 24, 48];

const finite = (value: unknown, fallback: number): number =>
  typeof value === 'number' && Number.isFinite(value) ? value : fallback;

const rampSteps = (ramp: MosaicRamp, edge: number): number[] => {
  if (Array.isArray(ramp.steps) && ramp.steps.length > 0) {
    return ramp.steps.map((s) => Math.max(1, Math.round(finite(s, 6))));
  }
  return DEFAULT_STEPS.filter((s) => s <= Math.max(6, edge));
};

/**
 * Block size (screen px) on a clip frame, or 0 for a clean picture.
 * mosaicIn: starts coarse (`from`, default 48) and resolves to clean over `frames`.
 * mosaicOut: ends coarse (`to`, default 48), starting `frames` before the clip ends.
 * The ramp's steps share the frames evenly (hard steps, no easing).
 */
export const mosaicBlockAt = (
  frame: number,
  total: number,
  mosaicIn: MosaicRamp | null | undefined,
  mosaicOut: MosaicRamp | null | undefined,
): number => {
  if (mosaicIn) {
    const frames = Math.max(1, Math.round(finite(mosaicIn.frames, 8)));
    if (frame < frames) {
      const steps = rampSteps(mosaicIn, finite(mosaicIn.from, 48)).slice().sort((a, b) => b - a);
      const k = Math.min(steps.length - 1, Math.floor((frame * steps.length) / frames));
      return steps[k];
    }
  }
  if (mosaicOut) {
    const frames = Math.max(1, Math.round(finite(mosaicOut.frames, 8)));
    const start = total - frames;
    if (frame >= start) {
      const steps = rampSteps(mosaicOut, finite(mosaicOut.to, 48)).slice().sort((a, b) => a - b);
      const k = Math.min(steps.length - 1, Math.floor(((frame - start) * steps.length) / frames));
      return steps[k];
    }
  }
  return 0;
};

let scratch: HTMLCanvasElement | null = null;
const scratchCanvas = (w: number, h: number): HTMLCanvasElement => {
  if (!scratch) scratch = document.createElement('canvas');
  if (scratch.width !== w) scratch.width = w;
  if (scratch.height !== h) scratch.height = h;
  return scratch;
};

/** Paint `source` into `rect` on a width x height canvas, as `block` px cells (0 = clean). */
export const paintMosaic = (
  ctx: CanvasRenderingContext2D,
  source: CanvasImageSource,
  rect: Rect,
  block: number,
  width: number,
  height: number,
  background?: string,
): void => {
  ctx.clearRect(0, 0, width, height);
  if (background) {
    ctx.fillStyle = background;
    ctx.fillRect(0, 0, width, height);
  }
  if (block <= 1) {
    ctx.imageSmoothingEnabled = true;
    ctx.drawImage(source, rect.x, rect.y, rect.w, rect.h);
    return;
  }
  const cols = Math.ceil(width / block);
  const rows = Math.ceil(height / block);
  const small = scratchCanvas(cols, rows);
  const sctx = small.getContext('2d');
  if (!sctx) return;
  sctx.clearRect(0, 0, cols, rows);
  if (background) {
    sctx.fillStyle = background;
    sctx.fillRect(0, 0, cols, rows);
  }
  sctx.imageSmoothingEnabled = true;
  sctx.imageSmoothingQuality = 'high';
  sctx.drawImage(source, rect.x / block, rect.y / block, rect.w / block, rect.h / block);
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(small, 0, 0, cols, rows, 0, 0, cols * block, rows * block);
};

const IMAGES = new Map<string, HTMLImageElement>();

/**
 * An image drawn into `rect` as a mosaic of `block` px cells. The first mount
 * of a url holds the frame (delayRender) until the image has decoded; later
 * frames paint synchronously from the cache.
 */
export const MosaicImage = ({
  url,
  rect,
  block,
  width,
  height,
  background,
  style,
}: {
  url: string;
  rect: Rect;
  block: number;
  width: number;
  height: number;
  background?: string;
  style?: CSSProperties;
}): ReactElement => {
  const ref = useRef<HTMLCanvasElement>(null);
  const [img, setImg] = useState<HTMLImageElement | null>(() => IMAGES.get(url) ?? null);
  const [handle] = useState<number | null>(() => (IMAGES.has(url) ? null : delayRender(`am mosaic ${url}`)));
  const released = useRef(false);

  useEffect(() => {
    if (img) return;
    const el = new Image();
    el.crossOrigin = 'anonymous';
    el.onload = () => {
      IMAGES.set(url, el);
      setImg(el);
    };
    el.onerror = () => cancelRender(new Error(`am mosaic: could not load ${url}`));
    el.src = url;
  }, [url, img]);

  useLayoutEffect(() => {
    const canvas = ref.current;
    if (!img || !canvas) return;
    const ctx = canvas.getContext('2d');
    if (ctx) paintMosaic(ctx, img, rect, block, width, height, background);
    if (handle !== null && !released.current) {
      released.current = true;
      continueRender(handle);
    }
  });

  return (
    <canvas
      ref={ref}
      width={width}
      height={height}
      style={{position: 'absolute', left: 0, top: 0, width, height, pointerEvents: 'none', ...style}}
    />
  );
};

import type {CSSProperties, ReactElement} from 'react';
import {Img, useCurrentFrame} from 'remotion';
import {
  COLOR,
  FAMILY,
  elementSource,
  finiteNumber,
  hashUnit,
  integerIn,
  narrowParams,
  type ElementComponentProps,
} from '../../_shared/am';

// am-burst: a pop-up burst for asides and celebration beats. Items stamp in on
// an arc, one after another, with a two-frame flicker. Each item throws a ring of
// 6 px squares that expands in three steps behind it. Confetti is optional and
// seeded. Positions snap to the 6 px grid; the bob is one logical px, on threes.

type BurstItem = {
  src?: string;
  glyph?: string;
  label?: string;
  angle?: number;
  distance?: number;
  at?: number;
  size?: number;
};
type Confetti = {at?: number; count?: number; seed?: number; spread?: number; life?: number; colors?: string[]};
type Params = {
  items?: BurstItem[];
  center?: {x?: number; y?: number};
  stepFrames?: number;
  x?: number;
  y?: number;
  width?: number;
  height?: number;
  seed?: number;
  bob?: number;
  ring?: boolean;
  color?: string;
  confetti?: Confetti | null;
};

const PIXEL = 6;
const DEFAULT_CONFETTI_COLORS = [COLOR.ink, COLOR.orange, COLOR.rust, COLOR.rule, '#FF7A2E'];
const MONO = `'${FAMILY.label}', monospace`;

const snap = (value: number): number => Math.round(value / PIXEL) * PIXEL;

// Squares on a pixel circle of `radius` cells, centred on the origin.
export const ringCells = (radius: number): [number, number][] => {
  const cells: [number, number][] = [];
  for (let j = -radius; j <= radius; j += 1) {
    for (let i = -radius; i <= radius; i += 1) {
      const d = Math.sqrt(i * i + j * j);
      if (Math.abs(d - radius) < 0.5) cells.push([i, j]);
    }
  }
  return cells;
};

// Ring step for an item `age` frames after it stamps: steps 1..3 on twos.
const ringStep = (age: number): number | null => {
  if (age < 0) return null;
  const step = Math.floor(age / 2) + 1;
  return step <= 3 ? step : null;
};

// Entrance: hidden for two frames, visible for two, then solid.
const entranceVisible = (age: number): boolean => age >= 0 && (age >= 4 || Math.floor(age / 2) % 2 === 1);

const ItemVisual = ({item, size, color}: {item: BurstItem; size: number; color: string}): ReactElement => {
  if (typeof item.src === 'string' && item.src.trim() !== '') {
    const url = elementSource(undefined, item.src);
    if (url) {
      return <Img src={url} style={{width: size, height: 'auto', imageRendering: 'pixelated', display: 'block'}} />;
    }
  }
  if (typeof item.glyph === 'string' && item.glyph !== '') {
    return (
      <div style={{fontFamily: MONO, fontSize: size, lineHeight: 1, color, whiteSpace: 'pre'}}>{item.glyph}</div>
    );
  }
  // Placeholder: an ink square with an orange pixel, so an empty item is still visible.
  return (
    <div style={{position: 'relative', width: size, height: size, background: color}}>
      <div style={{position: 'absolute', left: size / 2 - PIXEL / 2, top: size / 2 - PIXEL / 2, width: PIXEL, height: PIXEL, background: COLOR.orange}} />
    </div>
  );
};

export default function AmBurst(props: ElementComponentProps): ReactElement | null {
  const frame = useCurrentFrame();
  const params = narrowParams<Params>(props.params);
  const items = Array.isArray(params.items) ? params.items : [];
  const width = finiteNumber(params.width, 1920);
  const height = finiteNumber(params.height, 1080);
  const cx = snap(finiteNumber(params.center?.x, 960));
  const cy = snap(finiteNumber(params.center?.y, 540));
  const stepFrames = integerIn(params.stepFrames, 1, 30, 4);
  const seed = integerIn(params.seed, 0, 2 ** 30, 1);
  const bobPx = finiteNumber(params.bob, PIXEL);
  const ringOn = params.ring !== false;
  const color = typeof params.color === 'string' ? params.color : COLOR.ink;
  const conf = params.confetti ?? null;

  const placed = items.map((item, index) => {
    const size = snap(finiteNumber(item.size, 96));
    const angle = (finiteNumber(item.angle, -90) * Math.PI) / 180;
    const distance = finiteNumber(item.distance, 300);
    const at = finiteNumber(item.at, index * stepFrames);
    const ix = snap(cx + Math.cos(angle) * distance - size / 2);
    const iy = snap(cy + Math.sin(angle) * distance - size / 2);
    return {item, size, at, ix, iy, index};
  });

  const confetti: ReactElement[] = [];
  if (conf) {
    const at = finiteNumber(conf.at, 0);
    const count = integerIn(conf.count, 0, 400, 48);
    const spread = finiteNumber(conf.spread, 360);
    const life = integerIn(conf.life, 4, 240, 48);
    const palette = Array.isArray(conf.colors) && conf.colors.length > 0 ? conf.colors : DEFAULT_CONFETTI_COLORS;
    const cseed = integerIn(conf.seed, 0, 2 ** 30, seed);
    const t = frame - at;
    if (t >= 0 && t < life) {
      const steps = Math.floor(t / 2) * 2; // stepped on twos
      for (let i = 0; i < count; i += 1) {
        const a = hashUnit(cseed, i * 4) * Math.PI * 2;
        const r = (0.3 + 0.7 * hashUnit(cseed, i * 4 + 1)) * spread * 0.4;
        const speed = 2 + hashUnit(cseed, i * 4 + 2) * 6;
        const dx = Math.cos(a) * (r + speed * steps);
        const dy = Math.sin(a) * (r + speed * steps) + 0.04 * steps * steps;
        const colour = palette[Math.floor(hashUnit(cseed, i * 4 + 3) * palette.length)] ?? COLOR.ink;
        confetti.push(
          <div
            key={i}
            style={{position: 'absolute', left: snap(cx + dx), top: snap(cy + dy), width: PIXEL, height: PIXEL, background: colour}}
          />,
        );
      }
    }
  }

  return (
    <div style={{position: 'absolute', left: finiteNumber(params.x, 0), top: finiteNumber(params.y, 0), width, height, overflow: 'hidden'}}>
      {confetti}
      {placed.map(({item, size, at, ix, iy, index}) => {
        const age = frame - at;
        const visible = entranceVisible(age);
        const bob = age >= 4 && Math.floor((age - 4) / 3) % 2 === 1 ? -bobPx : 0;
        const step = ringOn ? ringStep(age) : null;
        const ringRadius = step ? step * 2 : 0;
        const ringX = ix + size / 2;
        const ringY = iy + size / 2;
        const labelOn = age >= 4 && typeof item.label === 'string' && item.label !== '';
        const itemStyle: CSSProperties = {
          position: 'absolute',
          left: ix,
          top: iy + Math.round(bob / PIXEL) * PIXEL,
          width: size,
          visibility: visible ? 'visible' : 'hidden',
        };
        return (
          <div key={index}>
            {step ? (
              ringCells(ringRadius).map(([i, j], k) => (
                <div
                  key={`${index}-${k}`}
                  style={{
                    position: 'absolute',
                    left: snap(ringX + i * PIXEL * 2) - PIXEL / 2,
                    top: snap(ringY + j * PIXEL * 2) - PIXEL / 2,
                    width: PIXEL,
                    height: PIXEL,
                    background: color,
                  }}
                />
              ))
            ) : null}
            <div style={itemStyle}>
              <ItemVisual item={item} size={size} color={color} />
              {labelOn ? (
                <div
                  style={{
                    position: 'absolute',
                    left: -size / 2,
                    width: size * 2,
                    top: size + 12,
                    textAlign: 'center',
                    fontFamily: MONO,
                    fontSize: 16,
                    lineHeight: 1,
                    letterSpacing: '0.12em',
                    textTransform: 'uppercase',
                    color,
                    whiteSpace: 'nowrap',
                  }}
                >
                  {item.label}
                </div>
              ) : null}
            </div>
          </div>
        );
      })}
    </div>
  );
}

