  </div>
);

const DividerRow = ({label, flip}: {label: string; flip: {top: string; bottom: string} | null}): ReactElement => (
  <div style={{display: 'flex', alignItems: 'center', gap: 12, padding: '12px 18px'}}>
    <div style={{flex: 1, height: 1, background: PALETTE.rule}} />
    {flip ? (
      <div style={{position: 'relative', height: 24, minWidth: 210, flexShrink: 0}}>
        <DayText text={flip.top} half="top" />
        <DayText text={flip.bottom} half="bottom" />
        <div style={{position: 'absolute', left: 0, right: 0, top: 11, height: 2, background: PALETTE.chat}} />
      </div>
    ) : (
      <div style={{fontFamily: MONO, fontSize: 14, lineHeight: '24px', color: PALETTE.muted, whiteSpace: 'nowrap'}}>
        {label}
      </div>
    )}
    <div style={{flex: 1, height: 1, background: PALETTE.rule}} />
  </div>
);

const TokenNode = ({
  token, shown, decor, frame,
}: {token: Token; shown: number; decor: Decor | undefined; frame: number}): ReactElement => {
  const visible = token.text.slice(0, shown);
  const hidden = token.text.slice(shown);
  let body: ReactElement;
  if (token.kind === 'mention') {
    body = shown > 0 ? (
      <span style={{background: PALETTE.mention, color: PALETTE.mentionText, borderRadius: 4, padding: '0 4px', fontWeight: 600}}>
        {visible}
      </span>
    ) : (
      <span />
    );
  } else if (token.kind === 'u') {
    body = (
      <span style={{textDecoration: 'underline', textDecorationThickness: 2, textUnderlineOffset: 4}}>{visible}</span>
    );
  } else {
    body = <span>{visible}</span>;
  }
  const hiddenNode = hidden.length > 0 ? <span style={{color: 'transparent'}}>{hidden}</span> : null;
  if (!decor) {
    return (
      <>
        {body}
        {hiddenNode}
      </>
    );
  }

  // Stacking: highlighter (0) sits behind the text (1); the marks, circle and
  // annotation draw over it (2 to 4).
  // Marker swipe: a bar the height of cap height plus about 3 px either side,
  // behind the glyphs. Both ends are ragged in 2 px steps, with a 1 px vertical
  // offset per end (the left end sits 1 px low, the right end 1 px high).
  const hl = decor.highlight;
  const highlight = hl && frame >= hl.at ? (
    <span
      key="hl"
      style={{
        position: 'absolute', left: -3, top: 2, height: 20, zIndex: 0,
        width: `calc((100% + 6px) * ${highlightProgress(frame, hl.at)})`,
        background: hexAlpha(hl.color, hl.alpha),
        clipPath: MARKER_ENDS,
      }}
    />
  ) : null;

  const marks: ReactElement[] = [];
  const u = decor.underline;
  if (u && frame >= u.at) {
    marks.push(
      <span
        key="u"
        style={{
          position: 'absolute', left: 0, bottom: -5, height: 3, zIndex: 2,
          width: `${underlineProgress(frame, u.at) * 100}%`, background: u.color,
        }}
      />,
    );
  }
  const s = decor.strike;
  if (s && frame >= s.at) {
    marks.push(
      <span key="s-rust" style={{position: 'absolute', left: 0, right: 0, top: 11, height: 3, zIndex: 2, background: PALETTE.rust}} />,
    );
  }
  if (s && frame >= s.at + 1) {
    marks.push(
      <span key="s-orange" style={{position: 'absolute', left: 3, right: -3, top: 13, height: 3, zIndex: 2, background: PALETTE.orange}} />,
    );
  }

  const c = decor.circle;
  if (c && frame >= c.at) {
    const prog = circleProgress(frame, c.at);
    marks.push(
      <svg
        key="circle"
        viewBox="0 0 100 100"
        preserveAspectRatio="none"
        style={{
          position: 'absolute', left: -18, top: -9, width: 'calc(100% + 36px)', height: 'calc(100% + 18px)',
          overflow: 'visible', pointerEvents: 'none', zIndex: 3,
        }}
      >
        <path
          d={c.d}
          pathLength={1}
          strokeDasharray={`${prog} 1`}
          fill="none"
          stroke={PALETTE.rust}
          strokeWidth={3}
          strokeLinecap="round"
          vectorEffect="non-scaling-stroke"
        />
      </svg>,
    );
  }

  const a = decor.annotation;
  if (a && frame >= a.at) {
    const grow = connectorProgress(frame, a.at);
    marks.push(
      <span
        key="ann-line"
        style={{position: 'absolute', left: 10, bottom: '100%', width: 2, height: 26 * grow, zIndex: 3, background: PALETTE.orange}}
      />,
    );
    if (grow >= 1) {
      marks.push(
        <span
          key="ann-dot"
          style={{position: 'absolute', left: 7, top: -3, width: 8, height: 8, borderRadius: 4, zIndex: 3, background: PALETTE.orange}}
        />,
      );
    }
    if (annotationShown(frame, a.at)) {
      marks.push(
        <span
          key="ann-card"
          style={{
            position: 'absolute', left: 0, bottom: 'calc(100% + 26px)', zIndex: 4, pointerEvents: 'none',
            fontFamily: MONO, fontSize: 15, lineHeight: '20px', color: INK, whiteSpace: 'nowrap',
            background: PANEL, border: `1px solid ${COLOR.rule}`, borderRadius: 4, padding: '6px 10px',
            boxShadow: '0 12px 30px rgba(31, 31, 31, 0.14)',
          }}
        >
          {a.text}
        </span>,
      );
    }
  }

  return (
    <span style={{position: 'relative', display: 'inline-block', isolation: 'isolate'}}>
      {highlight}
      <span style={{position: 'relative', zIndex: 1}}>
        {body}
        {hiddenNode}
      </span>
      {marks}
    </span>
  );
};

type LineProps = {
  tokens: Token[];
  visible: number[];
  decor: (ti: number) => Decor | undefined;
  frame: number;
  caretAt: number | null;
};

const Line = ({tokens, visible, decor, frame, caretAt}: LineProps): ReactElement => {
  const nodes: ReactElement[] = [];
  const caret = (key: string): ReactElement => (
    <span key={key} style={{display: 'inline-block', width: 2, height: 18, background: PALETTE.text, verticalAlign: 'middle'}} />
  );
  tokens.forEach((token, ti) => {
    if (caretAt === ti) nodes.push(caret(`caret-${ti}`));
    nodes.push(
      <TokenNode key={`t-${ti}`} token={token} shown={visible[ti] ?? token.text.length} decor={decor(ti)} frame={frame} />,
    );
  });
  if (caretAt === tokens.length) nodes.push(caret('caret-end'));
  return (
    <div style={{minHeight: LINE_H, lineHeight: `${LINE_H}px`, whiteSpace: 'pre-wrap', color: PALETTE.body, fontFamily: SANS, fontSize: 17}}>
      {nodes}
    </div>
  );
};

const seedOf = (key: string): number => Array.from(key).reduce((sum, ch) => sum + ch.charCodeAt(0), 0);

export default function AmDiscord(props: ElementComponentProps): ReactElement | null {
  const frame = useCurrentFrame();
  const p = narrowParams<Params>(props.params);

  const server = strOr(p.server, 'OSAI');
  const channel = strOr(p.channel, '# announcements');
  const channels = Array.isArray(p.channels) && p.channels.length > 0
    ? p.channels.filter((c): c is string => typeof c === 'string')
    : ['# announcements', '# general', '# testing'];
  const sidebarOn = p.sidebar !== false;
  const fitContent = p.fit === 'content';
  const minHeight = integerIn(p.minHeight, 180, 1080, 360);
  const messages = parseMessages(p.messages);
  const dividers = parseDividers(p.dateDividers).sort((a, b) => a.at - b.at);
  const reactions = parseReactions(p.reactions);
  const joins = parseJoins(p.joins);
  const underlines = parseMarks(p.underline);
  const strikes = parseStrikes(p.strike);
  const highlights = parseHighlights(p.highlight);
  const circles = listOf<TargetSpec>(p.circle, targetOf);
  const annotations = parseAnnotations(p.annotation);
  const cameras = parseCamera(p.camera).sort((a, b) => a.at - b.at);
  const jumpFrames = integerIn(p.jumpFrames, 1, 60, 12);
  const typeStep = integerIn(p.typeStepFrames, 1, 12, 2);
  const badge = strOr(p.badge, 'RECONSTRUCTION · REACTIONS & JOINS ILLUSTRATIVE');
  const win = parseFrame(p.frame);

  // Tokens per message, line and token. Built once per render.
  const tokenLines: Token[][][] = messages.map((m) => m.lines.map((line) => tokenize(line)));

  // Decorations address a token. The first match wins unless onMessage is given.
  const decorMap = new Map<string, Decor>();
  const put = (key: string, patch: Decor): void => {
    decorMap.set(key, {...decorMap.get(key), ...patch});
  };
  for (const u of underlines) {
    const key = findToken(tokenLines, u.word, u.onMessage);
    if (key) put(key, {underline: {at: u.at, color: u.color}});
  }
  for (const s of strikes) {
    const key = findToken(tokenLines, s.word, s.onMessage);
    if (key) put(key, {strike: {at: s.at}});
  }
  for (const h of highlights) {
    const key = findToken(tokenLines, h.word, h.onMessage);
    if (key) put(key, {highlight: {at: h.at, color: h.color, alpha: h.alpha}});
  }
  for (const c of circles) {
    const key = findToken(tokenLines, c.word, c.onMessage);
    if (key) put(key, {circle: {at: c.at, d: handCirclePath(seedOf(key))}});
  }
  for (const a of annotations) {
    const key = findToken(tokenLines, a.word, a.onMessage);
    if (key) put(key, {annotation: {at: a.at, text: a.text}});
  }

  // Reactions attach to a message: explicit onMessage, else the latest message posted by startAt.
  const reactionTarget = (r: ReactionSpec): number => {
    if (r.onMessage !== null && r.onMessage < messages.length) return r.onMessage;
    let best = 0;
    messages.forEach((m, i) => {
      if (m.appearAt <= r.startAt) best = i;
    });
    return best;
  };
  const reactsFor = (index: number): ReactionSpec[] =>
    reactions.filter((r) => reactionTarget(r) === index && frame >= r.startAt);

  // Chat stack: messages, joins and dividers in time order, newest at the bottom.
  type Item =
    | {kind: 'message'; at: number; index: number}
    | {kind: 'join'; at: number; index: number}
    | {kind: 'divider'; at: number; index: number};
  const rank = (item: Item): number => (item.kind === 'divider' ? 0 : item.kind === 'message' ? 1 : 2);
  const items: Item[] = [
    ...messages.map((m, index) => ({kind: 'message' as const, at: m.appearAt, index})),
    ...joins.map((j, index) => ({kind: 'join' as const, at: j.at, index})),
    ...dividers.map((d, index) => ({kind: 'divider' as const, at: d.at, index})),
  ].sort((a, b) => a.at - b.at || rank(a) - rank(b));
  const visibleItems = items.filter((item) => item.at <= frame);

  // Window height. Fit "content" hugs the visible stack; otherwise the frame height.
  const sidebarW = sidebarOn ? SIDEBAR_W : 0;
  const textWidth = win.width - BORDER * 2 - RAIL_W - sidebarW - MESSAGE_TEXT_INSET;
  const headroom = annotations.length > 0 ? ANNOTATION_HEADROOM : 0;
  const itemHeight = (item: Item): number => {
    if (item.kind === 'join') return JOIN_H;
    if (item.kind === 'divider') return DIVIDER_H;
    const lines = tokenLines[item.index];
    const text = lines.reduce((sum, tokens) => sum + wrapCount(tokens.map((t) => t.text).join(''), textWidth) * LINE_H, 0);
    return MESSAGE_PAD + LINE_H + text + (reactsFor(item.index).length > 0 ? REACTION_ROW_H : 0);
  };
  const stack = visibleItems.reduce((sum, item) => sum + itemHeight(item), 0);
  const winH = fitContent ? fitHeight(stack, headroom, minHeight, win.height) : win.height;
  const winLeft = (1920 - win.width) / 2;
  const winTop = (1080 - winH) / 2;

  // Camera: the whole window steps to zoom about its focus, then sits at the frame centre.
  const cam = cameraAt(cameras, frame);
  const camFx = cam && Number.isFinite(cam.fx) ? cam.fx : win.width / 2;
  const camFy = cam && Number.isFinite(cam.fy) ? cam.fy : winH / 2;
  const cameraStyle: CSSProperties = cameras.length > 0 && cam
    ? {
        transform: `translate(${960 - (winLeft + camFx)}px, ${540 - (winTop + camFy)}px) scale(${cam.zoom})`,
        transformOrigin: `${camFx}px ${camFy}px`,
      }
    : {};

  // Composer state: the post types into the message box before it lands.
  const comp = p.composer && typeof p.composer === 'object' ? p.composer : null;
  const compIndex = comp ? Math.round(finiteNumber(comp.message, 0)) : -1;
  const compMsg = comp && compIndex >= 0 && compIndex < messages.length ? messages[compIndex] : null;
  const compStart = comp ? Math.round(finiteNumber(comp.startAt, 0)) : 0;
  const compStep = comp ? integerIn(comp.typeStepFrames, 1, 12, 1) : 1;
  const composing = compMsg !== null && frame >= compStart && frame < compMsg.appearAt;
  const pressing = composing && compMsg !== null && frame >= compMsg.appearAt - 3;
  const compFull = compMsg ? compMsg.lines.join(' ').replace(/\{u:([^}]*)\}/g, '$1') : '';
  const composeText = composing ? compFull.slice(0, Math.min(compFull.length, Math.floor((frame - compStart) / compStep) + 1)) : '';
  const caretOn = Math.floor(frame / 8) % 2 === 0;
  const keyAt = compMsg ? compMsg.appearAt - 3 : -1;
  const keyAge = frame - keyAt;
  const keyShown = compMsg !== null && comp?.key !== null && keyAge >= 0 && keyAge < 14;
  const keyX = finiteNumber(comp?.key?.x, 1400);
  const keyY = finiteNumber(comp?.key?.y, 800);

  const renderDivider = (index: number): ReactElement | null => {
    const d = dividers[index];
    const from = index > 0 ? dividers[index - 1].label : d.label;
    const jump = d.jump !== null ? d.jump : index > 0;
    const state = dividerState(d.label, d.at, frame, from, jump, jumpFrames);
    if (state.phase === 'hidden') return null;
    if (state.phase === 'landed') return <DividerRow key={`d${index}`} label={state.text} flip={null} />;
    return <DividerRow key={`d${index}`} label="" flip={{top: state.top, bottom: state.bottom}} />;
  };

  const renderMessage = (index: number): ReactElement => {
    const m = messages[index];
    const age = frame - m.appearAt;
    const total = totalChars(m.lines);
    const shown = m.typeOn ? clamp(Math.floor(age / typeStep) + 1, 0, total) : total;
    const typing = m.typeOn && shown < total;
    // Caret sits at the first token that is not fully typed, on the line that holds it.
    let consumed = 0;
    let caretLine = -1;
    let caretToken = -1;
    if (typing) {
      for (let li = 0; li < tokenLines[index].length; li += 1) {
        const tokens = tokenLines[index][li];
        const lineChars = tokens.reduce((s, t) => s + t.text.length, 0);
        if (shown <= consumed + lineChars) {
          caretLine = li;
          let within = shown - consumed;
          caretToken = tokens.length;
          for (let ti = 0; ti < tokens.length; ti += 1) {
            if (within < tokens[ti].text.length) {
              caretToken = ti;
              break;
            }
            within -= tokens[ti].text.length;
          }
          break;
        }
        consumed += lineChars;
      }
    }
    // Per-line visible counts, derived from the global shown count.
    let left = shown;
    const lineVisible = tokenLines[index].map((tokens) => {
      const counts = revealed(tokens, left);
      left -= tokens.reduce((s, t) => s + t.text.length, 0);
      return counts;
    });
    const reacts = reactsFor(index);

    return (
      <div
        key={`m${index}`}
        style={{
          display: 'flex',
          gap: 12,
          padding: `${MESSAGE_PAD}px 18px 0`,
          transform: age === 0 ? 'translateY(6px)' : undefined,
        }}
      >
        <Avatar name={m.author} color={m.avatarColor} />
        <div style={{minWidth: 0, flex: 1}}>
          <div style={{display: 'flex', alignItems: 'center', gap: 10, lineHeight: `${LINE_H}px`, whiteSpace: 'nowrap'}}>
            <span style={{fontFamily: SANS, fontWeight: 700, fontSize: 16, color: PALETTE.text}}>{m.author}</span>
            {m.tag ? (
              <span
                style={{
                  fontFamily: SANS, fontWeight: 700, fontSize: 11, lineHeight: '18px', letterSpacing: '0.04em',
                  background: PALETTE.blurple, color: PALETTE.blurpleInk, borderRadius: 4, padding: '0 6px',
                }}
              >
                {m.tag}
              </span>
            ) : null}
            {m.time ? <span style={{fontFamily: MONO, fontSize: 13, color: PALETTE.muted}}>{m.time}</span> : null}
          </div>
          {m.lines.map((_, li) => (
            <Line
              key={li}
              tokens={tokenLines[index][li]}
              visible={lineVisible[li]}
              decor={(ti) => decorMap.get(`${index}:${li}:${ti}`)}
              frame={frame}
              caretAt={typing && caretLine === li ? caretToken : null}
            />
          ))}
          {reacts.length > 0 ? (
            <div style={{display: 'flex', flexWrap: 'wrap', gap: 6, paddingTop: 6}}>
              {reacts.map((r, ri) => {
                const count = reactionCount(r.countFrom, r.countTo, r.startAt, r.stepFrames, frame);
                const scale = stampScale(frame, r.startAt);
                return (
                  <div
                    key={ri}
                    style={{
                      display: 'flex', alignItems: 'center', gap: 6, height: 30, padding: '0 10px', borderRadius: 8,
                      background: r.mine ? 'rgba(88, 101, 242, 0.15)' : PALETTE.side,
                      border: `1px solid ${r.mine ? PALETTE.blurple : PALETTE.rule}`,
                      transform: `scale(${scale})`, transformOrigin: 'left center',
                      fontFamily: SANS, fontSize: 14, fontWeight: 600, color: PALETTE.text,
                    }}
                  >
                    <Emoji value={r.emoji} />
                    <span>{count}</span>
                  </div>
                );
              })}
            </div>
          ) : null}
        </div>
      </div>
    );
  };

  const renderJoin = (index: number): ReactElement => {
    const j = joins[index];
    const age = frame - j.at;
    return (
      <div
        key={`j${index}`}
        style={{
          display: 'flex', alignItems: 'center', gap: 12, padding: '12px 18px 0 18px',
          fontFamily: MONO, fontSize: 15, lineHeight: `${LINE_H}px`, color: PALETTE.muted,
          transform: age === 0 ? 'translateX(-6px)' : undefined,
        }}
      >
        <div style={{width: 42, display: 'flex', justifyContent: 'center', flexShrink: 0}}>
          <PixelArrow color={PALETTE.green} />
        </div>
        <span style={{color: PALETTE.text}}>{j.name}</span>
        <span>joined the server.</span>
        {j.time ? <span style={{fontSize: 13, marginLeft: 6}}>{j.time}</span> : null}
      </div>
    );
  };

  return (
    <div style={{position: 'absolute', inset: 0, pointerEvents: 'none', overflow: 'hidden'}}>
      <div
        style={{
          position: 'absolute',
          left: winLeft,
          top: winTop,
          width: win.width,
          height: winH,
          ...cameraStyle,
        }}
      >
        <div
          style={{
            position: 'absolute',
            inset: 0,
            borderRadius: win.radius,
            border: `${BORDER}px solid ${win.outline}`,
            boxShadow: `${win.shadow}px ${win.shadow}px 0 0 ${win.outline}`,
            background: PALETTE.chat,
            overflow: 'hidden',
            display: 'flex',
            boxSizing: 'border-box',
          }}
        >
          {/* Server rail */}
          <div style={{width: RAIL_W, background: PALETTE.rail, display: 'flex', flexDirection: 'column', alignItems: 'center', paddingTop: 12, gap: 12, flexShrink: 0}}>
            <div style={{width: 48, height: 48, clipPath: STEPPED, background: PALETTE.blurple, color: PALETTE.blurpleInk, fontFamily: SANS, fontWeight: 700, fontSize: 14, lineHeight: '48px', textAlign: 'center'}}>
              {server.slice(0, 2).toUpperCase()}
            </div>
            <div style={{width: 48, height: 48, clipPath: STEPPED, background: PALETTE.chat}} />
            <div style={{width: 48, height: 48, clipPath: STEPPED, background: PALETTE.chat}} />
          </div>

          {/* Channel sidebar (optional) */}
          {sidebarOn ? (
            <div style={{width: SIDEBAR_W, background: PALETTE.side, flexShrink: 0, display: 'flex', flexDirection: 'column'}}>
              <div style={{height: 48, lineHeight: '48px', padding: '0 18px', fontFamily: SANS, fontWeight: 700, fontSize: 16, color: PALETTE.text, borderBottom: `1px solid ${PALETTE.rail}`, whiteSpace: 'nowrap', overflow: 'hidden'}}>
                {server}
              </div>
              <div style={{padding: '18px 12px 0 12px'}}>
                <div style={{fontFamily: MONO, fontSize: 12, lineHeight: `${LINE_H}px`, color: PALETTE.muted, padding: '0 6px', letterSpacing: '0.08em', textTransform: 'uppercase'}}>
                  Text channels
                </div>
                {channels.map((name) => {
                  const active = name === channel;
                  return (
                    <div
                      key={name}
                      style={{
                        height: 36, lineHeight: '36px', padding: '0 10px', margin: '2px 0', borderRadius: 4,
                        background: active ? PALETTE.selected : 'transparent',
                        color: active ? PALETTE.text : PALETTE.muted,
                        fontFamily: SANS, fontWeight: 500, fontSize: 16, whiteSpace: 'nowrap', overflow: 'hidden',
                      }}
                    >
                      {name}
                    </div>
                  );
                })}
              </div>
            </div>
          ) : null}

          {/* Main */}
          <div style={{flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column'}}>
            <div style={{height: 48, lineHeight: '48px', padding: '0 18px', fontFamily: SANS, fontWeight: 700, fontSize: 16, color: PALETTE.text, borderBottom: `1px solid ${PALETTE.rail}`, flexShrink: 0, whiteSpace: 'nowrap'}}>
              {channel}
            </div>
            <div
              style={{
                flex: 1,
                minHeight: 0,
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'flex-end',
                overflow: 'hidden',
                paddingTop: headroom,
                paddingBottom: 12,
                ...(fitContent
                  ? {}
                  : {
                      WebkitMaskImage: 'linear-gradient(to bottom, transparent 0, #000 60px)',
                      maskImage: 'linear-gradient(to bottom, transparent 0, #000 60px)',
                    }),
              }}
            >
              {visibleItems.map((item) => {
                if (item.kind === 'message') return renderMessage(item.index);
                if (item.kind === 'join') return renderJoin(item.index);
                return renderDivider(item.index);
              })}
            </div>
            <div style={{padding: '12px 18px 18px', flexShrink: 0}}>
              <div
                style={{
                  height: 48, boxSizing: 'border-box', borderRadius: 8, background: PALETTE.input,
                  padding: '0 16px', lineHeight: '48px', fontFamily: SANS, fontSize: 15,
                  color: composing ? PALETTE.text : PALETTE.muted,
                  whiteSpace: 'nowrap', overflow: 'hidden',
                  display: 'flex', justifyContent: composing ? 'flex-start' : undefined,
                  outline: pressing ? `3px solid ${PALETTE.orange}` : 'none',
                  outlineOffset: -3,
                }}
              >
                {composing ? (
                  <>
                    <span style={{fontSize: 17}}>{composeText}</span>
                    {!pressing ? (
                      <span style={{display: 'inline-block', width: 3, height: 22, marginTop: 13, marginLeft: 1, background: caretOn ? PALETTE.text : 'transparent'}} />
                    ) : null}
                  </>
                ) : (
                  `Message ${channel}`
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      {keyShown ? (
        <div
          style={{
            position: 'absolute', left: keyX, top: keyY + (keyAge >= 1 && keyAge < 4 ? 8 : 0),
            transform: `scale(${keyAge === 0 ? 1.25 : 1})`, transformOrigin: 'center',
            fontFamily: MONO, fontSize: 44, lineHeight: '44px', letterSpacing: '0.12em', color: INK,
            background: PANEL, border: `4px solid ${INK}`, borderRadius: 10, padding: '22px 34px',
            boxShadow: `0 ${keyAge >= 1 && keyAge < 4 ? 2 : 10}px 0 0 ${INK}`,
          }}
        >
          ENTER <span style={{color: PALETTE.orange}}>⏎</span>
        </div>
      ) : null}

      {badge ? (
        <div
          style={{
            position: 'absolute',
            right: 104,
            bottom: 44,
            fontFamily: MONO,
            fontSize: 14,
            lineHeight: '20px',
            letterSpacing: '0.08em',
            whiteSpace: 'nowrap',
            color: INK,
            background: PANEL,
            border: `1px solid ${INK}`,
            padding: '6px 12px',
          }}
        >
          {badge}
        </div>
      ) : null}
    </div>
  );
}

// Pure am-discord logic (no React, no DOM). Markup, typing reveal, split-flap
// date schedule, reaction counts and decoration targets. Kept separate so the
// schedule can be checked without rendering.
import {clamp, hashUnit} from '../../_shared/am';

export type Token = {kind: 'text' | 'u' | 'mention'; text: string};

// `{u:word}` marks a word for underline. `@everyone` renders as a mention pill.
// Everything else is plain text, split at word and space boundaries so that
// underline and strike targets can address one word.
export const tokenize = (line: string): Token[] => {
  const out: Token[] = [];
  const pattern = /\{u:([^}]+)\}|(@everyone)/g;
  let last = 0;
  let match: RegExpExecArray | null = pattern.exec(line);
  while (match !== null) {
    if (match.index > last) out.push(...plainTokens(line.slice(last, match.index)));
    if (match[1] !== undefined) out.push({kind: 'u', text: match[1]});
    else out.push({kind: 'mention', text: match[2] ?? '@everyone'});
    last = match.index + match[0].length;
    match = pattern.exec(line);
  }
  if (last < line.length) out.push(...plainTokens(line.slice(last)));
  return out;
};

const plainTokens = (text: string): Token[] =>
  text.split(/(\s+)/).filter((part) => part.length > 0).map((part) => ({kind: 'text' as const, text: part}));

// The comparable form of a token: letters, digits and apostrophes, lower case.
export const wordKey = (text: string): string =>
  text.replace(/[^\p{L}\p{N}']/gu, '').toLowerCase();

// Characters visible after `chars` have been typed, split per token. Hidden
// characters stay in the layout (transparent), so typing never reflows the line.
export const revealed = (tokens: Token[], chars: number): number[] => {
  let left = chars;
  return tokens.map((token) => {
    const shown = clamp(left, 0, token.text.length);
    left -= token.text.length;
    return shown;
  });
};

export const totalChars = (lines: string[]): number =>
  lines.reduce((sum, line) => sum + tokenize(line).reduce((s, t) => s + t.text.length, 0), 0);

// ---- Split-flap date jump --------------------------------------------------

const DAY_MS = 86400000;
const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
];

// "26 October 2025" -> UTC midnight ms, or null if it is not that shape.
export const parseDayLabel = (label: string): number | null => {
  const m = /^(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})$/.exec(label.trim());
  if (!m) return null;
  const month = MONTHS.findIndex((name) => name.toLowerCase() === m[2].toLowerCase());
  if (month < 0) return null;
  return Date.UTC(Number(m[3]), month, Number(m[1]));
};

export const formatDayLabel = (ms: number): string => {
  const d = new Date(ms);
  return `${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
};

// Ease-out-quad day offsets for a jump of `total` days over `ticks` frames.
// Tick k (0-based) shows offset dayOffset(k). The last tick is the target.
export const dayOffset = (total: number, k: number, ticks: number): number => {
  const t = clamp((k + 1) / ticks, 0, 1);
  const eased = 1 - (1 - t) * (1 - t);
  return k >= ticks - 1 ? total : Math.round(total * eased);
};

export type DividerState =
  | {phase: 'hidden'}
  | {phase: 'landed'; text: string}
  | {phase: 'flip'; top: string; bottom: string; tick: number};

// State of one divider at clip frame `frame`. `from` is the previous divider's
// date (or the same date when this is the first). A non-jump divider lands at once.
export const dividerState = (
  label: string,
  at: number,
  frame: number,
  from: string,
  jump: boolean,
  ticks: number,
): DividerState => {
  if (frame < at) return {phase: 'hidden'};
  const to = parseDayLabel(label);
  const start = parseDayLabel(from);
  if (!jump || to === null || start === null || to === start || frame >= at + ticks) {
    return {phase: 'landed', text: label};
  }
  const total = Math.round((to - start) / DAY_MS);
  const k = frame - at;
  const topMs = start + dayOffset(total, k, ticks) * DAY_MS;
  const bottomMs = start + (k === 0 ? 0 : dayOffset(total, k - 1, ticks)) * DAY_MS;
  return {phase: 'flip', top: formatDayLabel(topMs), bottom: formatDayLabel(bottomMs), tick: k};
};

// ---- Decoration timing -----------------------------------------------------

// Underline draws in over 6 frames, one step per frame. Returns 0..1 in sixths.
export const underlineProgress = (frame: number, at: number): number =>
  clamp(frame - at + 1, 0, 6) / 6;

// ---- Reactions -------------------------------------------------------------

export const reactionCount = (
  countFrom: number,
  countTo: number,
  startAt: number,
  stepFrames: number,
  frame: number,
): number => {
  if (frame < startAt) return countFrom;
  const span = countTo - countFrom;
  const steps = Math.floor((frame - startAt) / Math.max(1, stepFrames));
  const magnitude = Math.min(Math.abs(span), steps);
  return countFrom + Math.sign(span) * magnitude;
};

// Stamp entrance: 0.6 -> 1.1 -> 1.0 over three frames, then held.
export const stampScale = (frame: number, startAt: number): number => {
  const k = frame - startAt;
  if (k < 0) return 0;
  if (k === 0) return 0.6;
  if (k === 1) return 1.1;
  return 1;
};

// ---- Camera (stepped push-ins) ---------------------------------------------

export type CameraStep = {at: number; zoom: number; fx: number; fy: number};

// The last camera step that has started by `frame`. Steps snap; nothing eases.
export const cameraAt = (steps: CameraStep[], frame: number): CameraStep | null => {
  let active: CameraStep | null = null;
  for (const step of steps) {
    if (step.at <= frame) active = step;
  }
  return active;
};

// ---- Highlighter, circle and annotation timing -----------------------------

// Vox-style swipe: the bar wipes across the word in 4 stepped frames.
export const highlightProgress = (frame: number, at: number): number => clamp(frame - at + 1, 0, 4) / 4;

// Hand-drawn circle: 6 stepped segments, one per frame.
export const circleProgress = (frame: number, at: number): number => clamp(frame - at + 1, 0, 6) / 6;

// Annotation: connector grows in 2 steps, the card lands on the frame after.
export const connectorProgress = (frame: number, at: number): number => clamp(frame - at + 1, 0, 2) / 2;
export const annotationShown = (frame: number, at: number): boolean => frame >= at + 2;

// A hand-drawn ellipse in a 0..100 box (container percent). About 1.15 turns,
// so the stroke overlaps itself, with a seeded radius wobble. Same seed, same stroke.
export const handCirclePath = (seed: number): string => {
  const steps = 72;
  const start = -1.95;
  const sweep = Math.PI * 2 * 1.15;
  const parts: string[] = [];
  for (let i = 0; i <= steps; i += 1) {
    const t = i / steps;
    const angle = start + sweep * t;
    const wobble = 1 + (hashUnit(seed, i) - 0.5) * 0.04;
    const drift = t > 0.85 ? 1 + (t - 0.85) * 0.18 : 1;
    const rx = 48 * wobble * drift;
    const ry = 42 * wobble;
    const x = 50 + rx * Math.cos(angle);
    const y = 50 + ry * Math.sin(angle);
    parts.push(`${i === 0 ? 'M' : 'L'} ${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return parts.join(' ');
};

// ---- Fit to content --------------------------------------------------------

// Window height that hugs the visible stack. 143 px is the window chrome (border,
// header, input bar and the chat padding); `headroom` is room above the stack
// for annotation cards. Clamped to [minHeight, maxHeight].
export const fitHeight = (stack: number, headroom: number, minHeight: number, maxHeight: number): number =>
  clamp(143 + headroom + stack, minHeight, maxHeight);

export const hexAlpha = (hex: string, alpha: number): string => {
  const n = Number.parseInt(hex.slice(1), 16);
  const r = (n >> 16) & 255;
  const g = (n >> 8) & 255;
  const b = n & 255;
  return `rgba(${r}, ${g}, ${b}, ${clamp(alpha, 0, 1)})`;
};

import type {ReactElement} from 'react';
import {AbsoluteFill, Img, useCurrentFrame} from 'remotion';
import {
  COLOR,
  LOGICAL_H,
  LOGICAL_W,
  clamp,
  easeOutCubic,
  elementSource,
  finiteNumber,
  narrowParams,
  pixelImage,
  type ElementComponentProps,
} from '../../_shared/am';

// am-droste: an endless zoom into a screen inside the plate. The plate's
// screen rect (logical px) holds the whole plate again, which holds it again,
// and so on. The camera zooms about the recursion's fixed point, so arriving at
// level n frames level n exactly as level 0 was framed: the loop never ends.
//
// Moves are stepped: each move jumps between levels on `stepFrames` steps with
// ease-out spacing (hard frames, no blending). `creep` adds a slow stepped
// drift between moves. Deeper levels can darken (depthTint) to read the depth.

type Move = {at?: number; to?: number; frames?: number};
type Params = {
  src?: string;
  /** The screen inside the plate that holds the next level, logical px. */
  screen?: {x: number; y: number; w: number; h: number};
  start?: number;
  moves?: Move[];
  creep?: number;
  stepFrames?: number;
  depthTint?: number;
  /** Paint the innermost screens this colour instead of recursing past maxLevel. */
  maxLevel?: number;
  background?: string;
};

const BASE = 6; // screen px per logical px at level 0, zoom 1

export default function AmDroste(props: ElementComponentProps): ReactElement | null {
  const frame = useCurrentFrame();
  const p = narrowParams<Params>(props.params);
  const url = elementSource(props.assetEntry, p.src);
  if (!url) return null;
  const fps = finiteNumber(props.fps, 30);
  const sc = p.screen ?? {x: 83, y: 38, w: 147, h: 75};
  const r = sc.w / LOGICAL_W;
  const offY = (sc.h - LOGICAL_H * r) / 2;
  const s = {x: sc.x, y: sc.y + offY};
  const fixed = {x: s.x / (1 - r), y: s.y / (1 - r)};
  const stepFrames = Math.max(1, Math.round(finiteNumber(p.stepFrames, 2)));
  const f = Math.floor(frame / stepFrames) * stepFrames;

  // Level (float) on this frame: stepped moves plus a stepped creep.
  let level = finiteNumber(p.start, 0);
  const moves = (Array.isArray(p.moves) ? p.moves : []).slice().sort((a, b) => finiteNumber(a.at, 0) - finiteNumber(b.at, 0));
  for (const m of moves) {
    const at = finiteNumber(m.at, 0);
    if (f < at) break;
    const to = finiteNumber(m.to, level + 1);
    const frames = Math.max(1, Math.round(finiteNumber(m.frames, 8)));
    const t = clamp((f - at) / frames, 0, 1);
    level = level + (to - level) * easeOutCubic(t);
  }
  level += finiteNumber(p.creep, 0) * (f / fps);
  const maxLevel = Math.round(finiteNumber(p.maxLevel, 99));
  const zoom = Math.pow(1 / r, level);
  const depthTint = clamp(finiteNumber(p.depthTint, 0), 0, 0.5);

  // Canvas px of level k's logical point q.
  const toCanvas = (k: number, qx: number, qy: number): {x: number; y: number} => {
    const rk = Math.pow(r, k);
    return {
      x: BASE * fixed.x + BASE * zoom * rk * (qx - fixed.x),
      y: BASE * fixed.y + BASE * zoom * rk * (qy - fixed.y),
    };
  };

  const first = Math.max(0, Math.floor(level) - 1);
  const last = Math.min(maxLevel, Math.floor(level) + 5);
  const layers: ReactElement[] = [];
  for (let k = first; k <= last; k += 1) {
    const rk = Math.pow(r, k);
    const tl = toCanvas(k, 0, 0);
    const w = LOGICAL_W * BASE * zoom * rk;
    const h = LOGICAL_H * BASE * zoom * rk;
    if (w < 8) break;
    const img = (
      <Img
        src={url}
        crossOrigin="anonymous"
        style={{position: 'absolute', left: 0, top: 0, width: Math.round(w), height: Math.round(h), maxWidth: 'none', maxHeight: 'none', ...pixelImage}}
      />
    );
    const tint = depthTint > 0 && k > 0 ? (
      <div style={{position: 'absolute', inset: 0, background: COLOR.charcoal, opacity: Math.min(0.7, depthTint * k)}} />
    ) : null;
    if (k === first && k === 0) {
      layers.push(
        <div key={k} style={{position: 'absolute', left: Math.round(tl.x), top: Math.round(tl.y), width: Math.round(w), height: Math.round(h)}}>
          {img}
        </div>,
      );
      continue;
    }
    // Clip to the screen of level k-1.
    const c0 = toCanvas(k - 1, sc.x, sc.y);
    const c1 = toCanvas(k - 1, sc.x + sc.w, sc.y + sc.h);
    const cx = Math.round(c0.x);
    const cy = Math.round(c0.y);
    layers.push(
      <div key={k} style={{position: 'absolute', left: cx, top: cy, width: Math.round(c1.x) - cx, height: Math.round(c1.y) - cy, overflow: 'hidden'}}>
        <div style={{position: 'absolute', left: Math.round(tl.x) - cx, top: Math.round(tl.y) - cy, width: Math.round(w), height: Math.round(h)}}>
          {img}
          {tint}
        </div>
      </div>,
    );
  }

  return <AbsoluteFill style={{overflow: 'hidden', background: p.background ?? COLOR.charcoal}}>{layers}</AbsoluteFill>;
}

import type {CSSProperties, ReactElement} from 'react';
import {useCurrentFrame} from 'remotion';
import {
  COLOR,
  FAMILY,
  finiteNumber,
  integerIn,
  narrowParams,
  oneOf,
  type ElementComponentProps,
} from '../../_shared/am';
import {
  FLAP_LABEL_STYLE,
  FlapStrip,
  flapChars,
  flapStripWidth,
  snapPx,
  type FlapValue,
} from './flap';

// am-flap: a split-flap readout for dates, numbers and short words. Each tile
// flips through the drum on two-frame steps; tiles start left to right.

type FlapParams = {
  values?: {text?: unknown; at?: unknown}[];
  tileW?: number;
  tileH?: number;
  gap?: number;
  color?: string;
  tileColor?: string;
  accentIndex?: number[];
  accentColor?: string;
  x?: number;
  y?: number;
  align?: 'left' | 'center' | 'right';
  label?: string;
  labelColor?: string;
  stagger?: number;
  stepFrames?: number;
};

const DEFAULTS = {
  tileW: 60,
  tileH: 84,
  gap: 6,
  color: COLOR.paper,
  tileColor: COLOR.ink,
  accentColor: COLOR.orange,
  x: 96,
  y: 96,
  align: 'left' as const,
  label: '',
  labelColor: COLOR.muted,
  stagger: 2,
  stepFrames: 2,
};

const DEFAULT_VALUES: FlapValue[] = [{text: '26.10.25', at: 0}];

const parseValues = (raw: FlapParams['values']): FlapValue[] => {
  if (!Array.isArray(raw)) return DEFAULT_VALUES;
  const parsed = raw
    .filter((item) => item && typeof item.text === 'string')
    .map((item) => ({text: String(item.text), at: finiteNumber(item.at, 0)}))
    .sort((a, b) => a.at - b.at);
  return parsed.length > 0 ? parsed : DEFAULT_VALUES;
};

export default function AmFlap(props: ElementComponentProps): ReactElement | null {
  const frame = useCurrentFrame();
  const params = narrowParams<FlapParams>(props.params);
  const values = parseValues(params.values);
  const tileW = snapPx(finiteNumber(params.tileW, DEFAULTS.tileW));
  const tileH = snapPx(finiteNumber(params.tileH, DEFAULTS.tileH));
  const gap = snapPx(finiteNumber(params.gap, DEFAULTS.gap));
  const stagger = integerIn(params.stagger, 0, 12, DEFAULTS.stagger);
  const stepFrames = integerIn(params.stepFrames, 1, 12, DEFAULTS.stepFrames);
  const width = Math.max(...values.map((value) => value.text.length), 1);
  const chars = flapChars(values, frame, {width, stagger, step: stepFrames});
  const stripW = flapStripWidth(width, tileW, gap);
  const align = oneOf(params.align, ['left', 'center', 'right'] as const, DEFAULTS.align);
  const anchorX = snapPx(finiteNumber(params.x, DEFAULTS.x));
  const anchorY = snapPx(finiteNumber(params.y, DEFAULTS.y));
  const left = align === 'right' ? anchorX - stripW : align === 'center' ? anchorX - Math.round(stripW / 2) : anchorX;
  const label = typeof params.label === 'string' ? params.label : '';
  const labelGap = label ? 18 : 0;
  const root: CSSProperties = {
    position: 'absolute',
    left,
    top: anchorY,
    width: stripW,
    fontFamily: `'${FAMILY.label}', monospace`,
  };
  return (
    <div style={root}>
      {label ? (
        <div
          style={{
            ...FLAP_LABEL_STYLE,
            color: typeof params.labelColor === 'string' ? params.labelColor : DEFAULTS.labelColor,
            marginBottom: labelGap,
            textAlign: align,
          }}
        >
          {label}
        </div>
      ) : null}
      <FlapStrip
        chars={chars}
        tileW={tileW}
        tileH={tileH}
        gap={gap}
        color={typeof params.color === 'string' ? params.color : DEFAULTS.color}
        tileColor={typeof params.tileColor === 'string' ? params.tileColor : DEFAULTS.tileColor}
        accentIndex={Array.isArray(params.accentIndex) ? params.accentIndex.filter((n) => Number.isInteger(n)) : []}
        accentColor={typeof params.accentColor === 'string' ? params.accentColor : DEFAULTS.accentColor}
      />
    </div>
  );
}

import type {CSSProperties, ReactElement} from 'react';
import {COLOR, FAMILY} from '../../_shared/am';

// Split-flap core. Pure functions drive every glyph from the frame number, so a
// frame is deterministic. am-churn imports this module for its date readout.

// Positions and sizes snap to the 6 px grid (one logical px of the 320x180 space).
export const snapPx = (value: number): number => Math.round(value / 6) * 6;

// Drum order. A glyph flips forward through this order until it reaches its
// target, so each step shows one intermediate glyph.
export const FLAP_CHARSET = " 0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ.,:-+/'&!?";
const DIGITS = '0123456789';

export type FlapValue = {text: string; at: number};

export const padFlapText = (text: string, width: number): string =>
  text.toUpperCase().padEnd(width, ' ').slice(0, width);

// Glyph shown at `elapsed` frames after one tile started flipping from `prev`
// to `next`. One drum step every `step` frames, so the flip holds on twos.
export const flapGlyph = (
  prev: string,
  next: string,
  elapsed: number,
  step: number,
  charset: string = FLAP_CHARSET,
): string => {
  if (prev === next) return next;
  if (elapsed < 0) return prev;
  // Digit-to-digit flips run round the digit ring only (at most nine steps),
  // so counters stay readable. Anything else runs the full drum forward.
  const ring = DIGITS.includes(prev) && DIGITS.includes(next) ? DIGITS : charset;
  const from = ring.indexOf(prev);
  const to = ring.indexOf(next);
  if (from < 0 || to < 0) return elapsed >= step ? next : prev;
  const n = ring.length;
  const steps = (to - from + n) % n;
  const k = Math.min(steps, Math.floor(elapsed / Math.max(1, step)));
  return ring[(from + k) % n] ?? next;
};

// Current glyph per tile for a keyframed list of targets. Tile i starts its
// flip at values[j].at + i * stagger, so the row flips left to right.
export const flapChars = (
  values: readonly FlapValue[],
  frame: number,
  options: {width: number; stagger: number; step: number; charset?: string},
): string[] => {
  const {width, stagger, step} = options;
  const charset = options.charset ?? FLAP_CHARSET;
  const targets = values.map((value) => padFlapText(value.text, width));
  const blank = ' '.repeat(width);
  const out: string[] = [];
  for (let i = 0; i < width; i += 1) {
    let current = -1;
    for (let j = 0; j < values.length; j += 1) {
      const start = values[j].at + i * stagger;
      if (start <= frame) current = j;
    }
    if (current < 0) {
      out.push(' ');
      continue;
    }
    const start = values[current].at + i * stagger;
    const prev = current > 0 ? targets[current - 1][i] : blank[i];
    out.push(flapGlyph(prev, targets[current][i], frame - start, step, charset));
  }
  return out;
};

// Tile geometry shared by the strip and by callers that align around it.
export const flapStripWidth = (count: number, tileW: number, gap: number): number =>
  count * tileW + Math.max(0, count - 1) * gap;

export type FlapStripProps = {
  chars: readonly string[];
  tileW: number;
  tileH: number;
  gap: number;
  color: string;
  tileColor: string;
  accentIndex: readonly number[];
  accentColor: string;
  splitColor?: string;
  fontSize?: number;
  style?: CSSProperties;
};

// One row of split-flap tiles. Each tile is a dark plate with a 1 px split line
// across its middle. Glyphs are Departure Mono, centred on the split.
export const FlapStrip = ({
  chars,
  tileW,
  tileH,
  gap,
  color,
  tileColor,
  accentIndex,
  accentColor,
  splitColor = '#0E0D0B',
  fontSize,
  style,
}: FlapStripProps): ReactElement => {
  const glyphSize = fontSize ?? Math.floor(tileH * 0.6);
  const accents = new Set(accentIndex);
  return (
    <div style={{display: 'flex', gap, ...style}}>
      {chars.map((char, index) => {
        const painted = accents.has(index) ? accentColor : color;
        return (
          <div
            key={index}
            style={{
              position: 'relative',
              width: tileW,
              height: tileH,
              flex: `0 0 ${tileW}px`,
              background: tileColor,
              overflow: 'hidden',
            }}
          >
            <div
              style={{
                position: 'absolute',
                left: 0,
                right: 0,
                top: Math.floor(tileH / 2),
                height: 1,
                background: splitColor,
              }}
            />
            <div
              style={{
                position: 'absolute',
                inset: 0,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontFamily: `'${FAMILY.label}', monospace`,
                fontSize: glyphSize,
                lineHeight: 1,
                color: painted,
                whiteSpace: 'pre',
              }}
            >
              {char === ' ' ? ' ' : char}
            </div>
          </div>
        );
      })}
    </div>
  );
};

export const FLAP_LABEL_STYLE: CSSProperties = {
  fontFamily: `'${FAMILY.label}', monospace`,
  fontSize: 18,
  letterSpacing: '0.12em',
  textTransform: 'uppercase',
  lineHeight: 1,
  whiteSpace: 'nowrap',
  color: COLOR.muted,
};

import type {CSSProperties, ReactElement} from 'react';
import {useRef} from 'react';
import {AbsoluteFill, Img, OffthreadVideo, useCurrentFrame, useVideoConfig} from 'remotion';
import {
  COLOR,
  FAMILY,
  clamp,
  clipFrames,
  elementSource,
  finiteNumber,
  narrowParams,
  type ElementComponentProps,
} from '../../_shared/am';
import {footageVolume} from './volume';
import {MosaicImage, mosaicBlockAt, paintMosaic, type MosaicRamp, type Rect} from '../../_shared/mosaic';

// am-footage: a REAL-FOOTAGE SLOT. It shows a filmed shot (video or still on
// clip.asset) cover-fitted to the frame, with an optional integer-free crop
// (zoom about a focus) and a slow push, and the pixelate transition (mosaicIn,
// mosaicOut) that carries real footage into the 320x180 pixel world and back.
//
// With no asset it draws the SLOT CARD instead: a deliberate, labelled frame
// that shows the shot spec (framing note, the declared face zone, the hand
// outline and palm mark), so the edit reads and the overlays can be placed
// before anything is filmed. Swapping the slot's media for the real take keeps
// every overlay landing, because overlays are placed against the declared zones.
//
// faceZone and handMark are declarations in canvas px (1920x1080). Lint reads
// them (no overlay may cover the face zone); the slot card draws them.
//
// inset places the picture in a framed rect on the `background` field instead of
// filling the frame: a real screenshot (the Discord post, a repo page, the app)
// shown as a document on the page. zoom, focus, push and the mosaic ramps work
// inside the rect; the label sits under it.

type Zone = {x: number; y: number; w: number; h: number};
type Inset = {x: number; y: number; w: number; h: number; radius?: number; shadow?: boolean | string; border?: string};
type Params = {
  src?: string;
  slot?: string;
  kind?: string;
  /** Small corner label. Default "PLACEHOLDER · REAL FOOTAGE · <slot>" when the media is a stand-in. */
  label?: string;
  /** True while the media is a stand-in (generated plate or slot card): shows the label. */
  placeholder?: boolean;
  /** Framing note shown on the slot card ("MEDIUM · chest up · face centre-left"). */
  spec?: string;
  /** Crop: zoom >= 1 about focus (fractions of the source, 0..1). */
  zoom?: number;
  focus?: {x: number; y: number};
  /** Slow push: zoom moves linearly to `to` over the clip (real footage may ease; pixels never do). */
  push?: {to: number} | null;
  mosaicIn?: MosaicRamp | null;
  mosaicOut?: MosaicRamp | null;
  faceZone?: Zone | null;
  handMark?: {x: number; y: number; size?: number} | null;
  /** Draw the face zone and hand mark over real media too (review aid). */
  guides?: boolean;
  /** Seconds into the media where this clip starts. */
  in?: number;
  volume?: number;
  /** Source pixel size when the registry has no resolution ("WxH"). */
  sourceSize?: string;
  background?: string;
  tint?: {color?: string; opacity?: number} | null;
  /** Framed rect (canvas px) for the picture on the background field. Omit to fill the frame. */
  inset?: Inset | null;
};

const SOFT_SHADOW = '0 28px 64px rgba(21, 19, 17, 0.18), 0 3px 8px rgba(21, 19, 17, 0.10)';

const insetOf = (value: unknown, width: number, height: number): (Required<Pick<Inset, 'x' | 'y' | 'w' | 'h' | 'radius'>> & {shadow: string; border: string | null}) | null => {
  if (!value || typeof value !== 'object') return null;
  const v = value as Inset;
  const w = Math.round(clamp(finiteNumber(v.w, 0), 0, width));
  const h = Math.round(clamp(finiteNumber(v.h, 0), 0, height));
  if (w < 2 || h < 2) return null;
  const shadow = v.shadow === false ? 'none' : typeof v.shadow === 'string' ? v.shadow : SOFT_SHADOW;
  return {
    x: Math.round(finiteNumber(v.x, (width - w) / 2)),
    y: Math.round(finiteNumber(v.y, (height - h) / 2)),
    w,
    h,
    radius: Math.max(0, finiteNumber(v.radius, 12)),
    shadow,
    border: typeof v.border === 'string' ? v.border : null,
  };
};

const MONO = `'${FAMILY.label}', monospace`;
const CARD_BG = '#1F1F1F';
const GUIDE = '#FFFEFA';

const parseSize = (value: unknown): {w: number; h: number} | null => {
  const m = /^(\d+)x(\d+)$/.exec(String(value ?? ''));
  return m ? {w: Number(m[1]), h: Number(m[2])} : null;
};

// Cover-fit the source into width x height, then zoom about the focus (source
// fractions). The view is clamped so the frame never shows past the source edge.
const coverRect = (
  src: {w: number; h: number},
  width: number,
  height: number,
  zoom: number,
  focus: {x: number; y: number},
): Rect => {
  const base = Math.max(width / src.w, height / src.h);
  const s = base * Math.max(1, zoom);
  const w = src.w * s;
  const h = src.h * s;
  const x = clamp(width / 2 - focus.x * w, width - w, 0);
  const y = clamp(height / 2 - focus.y * h, height - h, 0);
  return {x: Math.round(x), y: Math.round(y), w: Math.round(w), h: Math.round(h)};
};

const isVideo = (type: unknown, url: string): boolean =>
  (typeof type === 'string' && type.startsWith('video')) || /\.(mp4|mov|m4v|webm|mkv)(\?|$)/i.test(url);

// An open hand, palm up, drawn as a dashed storyboard outline. Unit: palm width.
// The palm centre is (0, 0); fingers point up and to the left, thumb out right.
const HandOutline = ({cx, cy, size}: {cx: number; cy: number; size: number}): ReactElement => {
  const u = size;
  const finger = (x: number, len: number, w: number, tilt: number, key: string): ReactElement => (
    <rect
      key={key}
      x={x - w / 2}
      y={-0.42 * u - len}
      width={w}
      height={len + 0.12 * u}
      rx={w / 2}
      transform={`rotate(${tilt} ${x} ${-0.42 * u})`}
    />
  );
  return (
    <g transform={`translate(${cx} ${cy})`} fill="none" stroke={GUIDE} strokeWidth={4} strokeDasharray="14 10" opacity={0.85}>
      <rect x={-0.5 * u} y={-0.5 * u} width={u} height={1.05 * u} rx={0.28 * u} />
      {finger(-0.36 * u, 0.62 * u, 0.2 * u, -8, 'f1')}
      {finger(-0.12 * u, 0.74 * u, 0.21 * u, -3, 'f2')}
      {finger(0.12 * u, 0.7 * u, 0.21 * u, 2, 'f3')}
      {finger(0.34 * u, 0.55 * u, 0.19 * u, 8, 'f4')}
      <rect x={0.42 * u} y={-0.05 * u} width={0.62 * u} height={0.22 * u} rx={0.11 * u} transform={`rotate(-28 ${0.42 * u} ${0.06 * u})`} />
      <rect x={-0.3 * u} y={0.55 * u} width={0.6 * u} height={0.5 * u} rx={0.1 * u} strokeDasharray="6 10" />
    </g>
  );
};

const Guides = ({face, hand}: {face: Zone | null; hand: Params['handMark'] | null}): ReactElement => (
  <svg width={1920} height={1080} style={{position: 'absolute', left: 0, top: 0, overflow: 'visible', pointerEvents: 'none'}}>
    {face ? (
      <g>
        <rect x={face.x} y={face.y} width={face.w} height={face.h} fill="none" stroke={GUIDE} strokeWidth={3} strokeDasharray="18 12" opacity={0.8} />
        <ellipse cx={face.x + face.w / 2} cy={face.y + face.h * 0.42} rx={face.w * 0.3} ry={face.h * 0.36} fill="none" stroke={GUIDE} strokeWidth={3} strokeDasharray="10 10" opacity={0.6} />
        <text x={face.x + 12} y={face.y + 34} fill={GUIDE} fontFamily={MONO} fontSize={24} letterSpacing="0.12em" opacity={0.9}>FACE ZONE · KEEP CLEAR</text>
      </g>
    ) : null}
    {hand ? (
      <g>
        <HandOutline cx={hand.x} cy={hand.y} size={finiteNumber(hand.size, 300)} />
        <line x1={hand.x - 36} y1={hand.y} x2={hand.x + 36} y2={hand.y} stroke={COLOR.orange} strokeWidth={4} />
        <line x1={hand.x} y1={hand.y - 36} x2={hand.x} y2={hand.y + 36} stroke={COLOR.orange} strokeWidth={4} />
        <text x={hand.x + 48} y={hand.y + 60} fill={GUIDE} fontFamily={MONO} fontSize={22} letterSpacing="0.12em">PALM MARK</text>
      </g>
    ) : null}
  </svg>
);

const labelStyle: CSSProperties = {
  position: 'absolute',
  left: 48,
  bottom: 36,
  fontFamily: MONO,
  fontSize: 16,
  lineHeight: '16px',
  letterSpacing: '0.1em',
  textTransform: 'uppercase',
  whiteSpace: 'nowrap',
  color: COLOR.ink,
  background: COLOR.panel,
  border: `1px solid ${COLOR.ink}`,
  padding: '6px 10px',
  opacity: 0.9,
};

export default function AmFootage(props: ElementComponentProps): ReactElement | null {
  const frame = useCurrentFrame();
  const {width, height, fps: compositionFps} = useVideoConfig();
  const p = narrowParams<Params>(props.params);
  const fps = finiteNumber(props.fps, compositionFps);
  const total = clipFrames(props.clip, fps);
  const url = elementSource(props.assetEntry, p.src);
  const slot = typeof p.slot === 'string' ? p.slot : '';
  const face = p.faceZone && typeof p.faceZone === 'object' ? p.faceZone : null;
  const hand = p.handMark && typeof p.handMark === 'object' ? p.handMark : null;
  const placeholder = p.placeholder === true || !url;
  const label = typeof p.label === 'string' ? p.label : `PLACEHOLDER · REAL FOOTAGE${slot ? ` · ${slot}` : ''}`;
  const background = p.background ?? CARD_BG;
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const block = mosaicBlockAt(frame, total, p.mosaicIn, p.mosaicOut);

  // ---- Slot card: no media yet.
  if (!url) {
    const spec = typeof p.spec === 'string' ? p.spec : '';
    const kind = typeof p.kind === 'string' ? p.kind.toUpperCase() : 'REAL FOOTAGE';
    const dots: ReactElement[] = [];
    for (let gx = 96; gx < 1920; gx += 96) {
      for (let gy = 96; gy < 1080; gy += 96) {
        dots.push(<div key={`${gx}-${gy}`} style={{position: 'absolute', left: gx - 3, top: gy - 3, width: 6, height: 6, background: '#34332F'}} />);
      }
    }
    return (
      <AbsoluteFill style={{background, overflow: 'hidden'}}>
        {dots}
        <Guides face={face} hand={hand} />
        <div style={{position: 'absolute', left: 96, top: 84, fontFamily: MONO, fontSize: 30, lineHeight: '36px', letterSpacing: '0.12em', color: GUIDE}}>
          <span style={{color: COLOR.orange}}>SLOT {slot || '—'}</span> · {kind} · TO FILM
        </div>
        {spec ? (
          <div style={{position: 'absolute', left: 96, top: 132, width: 1100, fontFamily: MONO, fontSize: 22, lineHeight: '30px', letterSpacing: '0.08em', color: '#B9B4A8', textTransform: 'uppercase'}}>
            {spec}
          </div>
        ) : null}
      </AbsoluteFill>
    );
  }

  // ---- Real media (or a stand-in still) on the slot.
  const inset = insetOf(p.inset, width, height);
  // The picture box: the inset rect, or the whole frame.
  const boxW = inset ? inset.w : width;
  const boxH = inset ? inset.h : height;
  const size = parseSize((props.assetEntry as {resolution?: string} | undefined)?.resolution) ?? parseSize(p.sourceSize) ?? {w: boxW, h: boxH};
  const zoom0 = Math.max(1, finiteNumber(p.zoom, 1));
  const zoomTo = p.push && typeof p.push === 'object' ? Math.max(1, finiteNumber(p.push.to, zoom0)) : zoom0;
  const zoom = zoom0 + (zoomTo - zoom0) * clamp(frame / Math.max(1, total - 1), 0, 1);
  const focus = {x: clamp(finiteNumber(p.focus?.x, 0.5), 0, 1), y: clamp(finiteNumber(p.focus?.y, 0.5), 0, 1)};
  const rect = coverRect(size, boxW, boxH, zoom, focus);
  const video = isVideo((props.assetEntry as {type?: string} | undefined)?.type, url);
  const trimBefore = Math.max(0, Math.round(finiteNumber(p.in, 0) * fps));
  const volume = footageVolume((props.clip as {volume?: unknown} | undefined)?.volume, p.volume);
  const tint = p.tint && typeof p.tint === 'object' ? p.tint : null;
  const mediaStyle: CSSProperties = {position: 'absolute', left: rect.x, top: rect.y, width: rect.w, height: rect.h, maxWidth: 'none', maxHeight: 'none'};

  let picture: ReactElement;
  if (video) {
    picture = (
      <>
        {/* no playbackRate: clip.speed is applied by the composition's time remap */}
        <OffthreadVideo
          src={url}
          trimBefore={trimBefore > 0 ? trimBefore : undefined}
          volume={volume}
          muted={volume <= 0}
          style={{...mediaStyle, opacity: block > 0 ? 0 : 1}}
          onVideoFrame={(source) => {
            const canvas = canvasRef.current;
            const ctx = canvas?.getContext('2d');
            if (ctx && block > 0) paintMosaic(ctx, source, rect, block, boxW, boxH, background);
          }}
        />
        {block > 0 ? (
          <canvas ref={canvasRef} width={boxW} height={boxH} style={{position: 'absolute', left: 0, top: 0, width: boxW, height: boxH}} />
        ) : null}
      </>
    );
  } else if (block > 0) {
    picture = <MosaicImage url={url} rect={rect} block={block} width={boxW} height={boxH} background={background} />;
  } else {
    picture = <Img src={url} crossOrigin="anonymous" style={mediaStyle} />;
  }

  const tintLayer = tint?.color ? (
    <AbsoluteFill style={{background: tint.color, opacity: clamp(finiteNumber(tint.opacity, 0.25), 0, 1)}} />
  ) : null;

  if (inset) {
    // The label hangs under the inset's left edge, or sits inside it when there is no room below.
    const below = inset.y + inset.h + 18 + 30 <= height;
    const insetLabel: CSSProperties = below
      ? {...labelStyle, left: inset.x, top: inset.y + inset.h + 18, bottom: undefined}
      : {...labelStyle, left: inset.x + 16, top: inset.y + inset.h - 46, bottom: undefined};
    const ring = inset.border ? `0 0 0 1px ${inset.border}` : null;
    return (
      <AbsoluteFill style={{background, overflow: 'hidden'}}>
        <div
          style={{
            position: 'absolute',
            left: inset.x,
            top: inset.y,
            width: inset.w,
            height: inset.h,
            overflow: 'hidden',
            borderRadius: inset.radius,
            boxShadow: [ring, inset.shadow === 'none' ? null : inset.shadow].filter(Boolean).join(', ') || 'none',
            background,
          }}
        >
          {picture}
          {tintLayer}
        </div>
        {p.guides ? <Guides face={face} hand={hand} /> : null}
        {placeholder && label ? <div style={insetLabel}>{label}</div> : null}
      </AbsoluteFill>
    );
  }

  return (
    <AbsoluteFill style={{background, overflow: 'hidden'}}>
      {picture}
      {tintLayer}
      {p.guides ? <Guides face={face} hand={hand} /> : null}
      {placeholder && label ? <div style={labelStyle}>{label}</div> : null}
    </AbsoluteFill>
  );
}

// Footage sound level. The clip-level `volume` (clip.volume, the field every
// clip uses) wins when it is a finite number >= 0; the legacy element param
// `volume` is read only when the clip has none. Zero when neither is set, so
// stand-in footage stays silent. The result is clamped to 0..1 because the
// <video> element cannot be louder than unity: gain above 1 is not supported
// on footage (use the audio track for louder sound).
export const footageVolume = (clipVolume: unknown, paramVolume: unknown): number => {
  const chosen =
    typeof clipVolume === 'number' && Number.isFinite(clipVolume) && clipVolume >= 0
      ? clipVolume
      : typeof paramVolume === 'number' && Number.isFinite(paramVolume)
        ? paramVolume
        : 0;
  return Math.min(1, Math.max(0, chosen));
};

import type {ReactElement} from 'react';
import {useCurrentFrame} from 'remotion';
import {COLOR, FAMILY, clamp, finiteNumber, narrowParams, type ElementComponentProps} from '../../_shared/am';

// am-orbit: a small pixel orbit HUD. The Earth steps round the Sun past twelve
// month ticks while a mono readout names the month. Drawn on the 6 px grid.

type Params = {
  x?: number;
  y?: number;
  /** Orbit radius in logical px. */
  radius?: number;
  /** Month index the Earth starts on (0 = January). */
  fromMonth?: number;
  fromYear?: number;
  /** Months travelled over `frames`. */
  months?: number;
  at?: number;
  frames?: number;
  stepFrames?: number;
  dark?: boolean;
  caption?: string;
};

const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
const PX = 6;

export default function AmOrbit(props: ElementComponentProps): ReactElement {
  const frame = useCurrentFrame();
  const p = narrowParams<Params>(props.params);
  const R = Math.round(clamp(finiteNumber(p.radius, 20), 8, 60));
  const size = 2 * R + 9;
  const x = finiteNumber(p.x, 1920 - 96 - size * PX);
  const y = finiteNumber(p.y, 96);
  const fromMonth = Math.round(finiteNumber(p.fromMonth, 9));
  const fromYear = Math.round(finiteNumber(p.fromYear, 2025));
  const months = finiteNumber(p.months, 12);
  const at = finiteNumber(p.at, 0);
  const frames = Math.max(1, Math.round(finiteNumber(p.frames, 60)));
  const stepFrames = Math.max(1, Math.round(finiteNumber(p.stepFrames, 2)));
  const f = Math.floor(Math.max(0, frame - at) / stepFrames) * stepFrames;
  const progress = clamp(f / frames, 0, 1);
  const monthPos = fromMonth + months * progress;
  const monthIndex = Math.floor(monthPos + 1e-6);
  const ink = p.dark ? COLOR.panel : COLOR.ink;
  const ring = p.dark ? '#5B5850' : '#C9C3B6';
  const c = R + 4;
  const angleOf = (m: number): number => ((m - 3) / 12) * Math.PI * 2; // April at the right, January at the top

  const cells: {x: number; y: number; color: string}[] = [];
  const put = (px: number, py: number, color: string): void => {
    cells.push({x: Math.round(px), y: Math.round(py), color});
  };
  // Orbit ring, dotted.
  const steps = Math.round(2 * Math.PI * R);
  for (let i = 0; i < steps; i += 2) {
    const a = (i / steps) * Math.PI * 2;
    put(c + Math.cos(a) * R, c + Math.sin(a) * R, ring);
  }
  // Month ticks.
  for (let m = 0; m < 12; m += 1) {
    const a = angleOf(m);
    const passed = m === ((monthIndex % 12) + 12) % 12;
    put(c + Math.cos(a) * (R + 2), c + Math.sin(a) * (R + 2), passed ? COLOR.orange : ink);
    put(c + Math.cos(a) * (R + 3), c + Math.sin(a) * (R + 3), passed ? COLOR.orange : ink);
  }
  // Sun.
  for (let dy = -3; dy <= 3; dy += 1) {
    for (let dx = -3; dx <= 3; dx += 1) {
      if (dx * dx + dy * dy <= 10) put(c + dx, c + dy, dx * dx + dy * dy <= 4 ? '#FFD27A' : COLOR.orange);
    }
  }
  // Trail and Earth.
  for (let k = 3; k >= 1; k -= 1) {
    const a = angleOf(monthPos - k * 0.18);
    put(c + Math.cos(a) * R, c + Math.sin(a) * R, p.dark ? '#3E5F7E' : '#9DB7CF');
  }
  const ea = angleOf(monthPos);
  const ex = c + Math.cos(ea) * R;
  const ey = c + Math.sin(ea) * R;
  for (let dy = -1; dy <= 1; dy += 1) {
    for (let dx = -1; dx <= 1; dx += 1) {
      if (Math.abs(dx) + Math.abs(dy) <= 1) put(ex + dx, ey + dy, dx === 0 && dy === 0 ? '#6AA651' : '#3F7FC1');
    }
  }
  const year = fromYear + Math.floor(monthIndex / 12);
  const label = `${MONTHS[((monthIndex % 12) + 12) % 12]} ${String(year).slice(2)}`;

  return (
    <div style={{position: 'absolute', left: x, top: y, width: size * PX, pointerEvents: 'none'}}>
      <div style={{position: 'relative', width: size * PX, height: size * PX}}>
        {cells.map((cell, i) => (
          <div key={i} style={{position: 'absolute', left: cell.x * PX, top: cell.y * PX, width: PX, height: PX, background: cell.color}} />
        ))}
      </div>
      <div style={{marginTop: 6, textAlign: 'center', fontFamily: `'${FAMILY.label}', monospace`, fontSize: 30, letterSpacing: '0.12em', color: ink}}>
        {label}
      </div>
      {p.caption ? (
        <div style={{textAlign: 'center', fontFamily: `'${FAMILY.label}', monospace`, fontSize: 18, letterSpacing: '0.12em', color: p.dark ? '#B9B4A8' : COLOR.muted}}>
          {p.caption}
        </div>
      ) : null}
    </div>
  );
}

import type {ReactElement} from 'react';
import {useCurrentFrame} from 'remotion';
import {COLOR, FAMILY, clamp, finiteNumber, narrowParams, type ElementComponentProps} from '../../_shared/am';

// am-orgchart: a recursive pixel org chart. One agent manages `branching`
// agents, each of which manages `branching` more, down `levels` rows. Rows stamp
// in level by level (left to right inside a level), the boxes shrink as the
// tree widens, and the deepest row is just dots. Optional row labels on the
// left and a rubber stamp on top. Drawn on a canvas on whole px, so edges stay
// hard; everything is a function of the frame.

type Stamp = {text?: string; at?: number; x?: number; y?: number; rotate?: number; size?: number};
type Params = {
  x?: number;
  y?: number;
  width?: number;
  height?: number;
  levels?: number;
  branching?: number;
  /** Clip frame each level starts appearing (one entry per level). */
  revealAt?: number[];
  /** Frames a level takes to fill in, left to right. */
  spread?: number;
  labels?: string[];
  stamp?: Stamp | null;
  background?: string | null;
};

const MONO = `'${FAMILY.label}', monospace`;
const INK = COLOR.ink;

// 8x8 bot head: antenna, head, two eyes.
const BOT = ['00011000', '00011000', '01111110', '11111111', '11011011', '11111111', '11100111', '01111110'];
const EYES = new Set(['4,2', '4,5']);

const drawBot = (ctx: CanvasRenderingContext2D, cx: number, cy: number, size: number, hot: boolean): void => {
  if (size < 12) {
    ctx.fillStyle = hot ? COLOR.orange : INK;
    const d = Math.max(4, Math.round(size));
    ctx.fillRect(Math.round(cx - d / 2), Math.round(cy - d / 2), d, d);
    return;
  }
  const cell = Math.max(1, Math.floor(size / 8));
  const ox = Math.round(cx - 4 * cell);
  const oy = Math.round(cy - 4 * cell);
  for (let r = 0; r < 8; r += 1) {
    for (let c = 0; c < 8; c += 1) {
      if (BOT[r][c] !== '1') continue;
      const eye = EYES.has(`${r},${c}`);
      ctx.fillStyle = eye ? (hot ? COLOR.orange : COLOR.panel) : INK;
      ctx.fillRect(ox + c * cell, oy + r * cell, cell, cell);
    }
  }
};

export default function AmOrgchart(props: ElementComponentProps): ReactElement {
  const frame = useCurrentFrame();
  const p = narrowParams<Params>(props.params);
  const x = finiteNumber(p.x, 420);
  const y = finiteNumber(p.y, 150);
  const width = finiteNumber(p.width, 1400);
  const height = finiteNumber(p.height, 760);
  const levels = Math.round(clamp(finiteNumber(p.levels, 5), 1, 7));
  const b = Math.round(clamp(finiteNumber(p.branching, 3), 2, 5));
  const spread = Math.max(1, Math.round(finiteNumber(p.spread, 8)));
  const reveal = Array.isArray(p.revealAt) ? p.revealAt : [];
  const revealOf = (k: number): number => finiteNumber(reveal[k], k * 12);
  const rowH = height / levels;
  const labels = Array.isArray(p.labels) ? p.labels : [];

  const paint = (ctx: CanvasRenderingContext2D): void => {
    ctx.clearRect(0, 0, 1920, 1080);
    // Box size per level: the widest row decides; the top rows stay readable.
    const sizeOf = (k: number): number => {
      const n = Math.pow(b, k);
      return Math.min(96, Math.max(4, Math.floor((width / n) * 0.62)), rowH * 0.55);
    };
    const posOf = (k: number, i: number): [number, number] => {
      const n = Math.pow(b, k);
      return [x + ((i + 0.5) * width) / n, y + (k + 0.5) * rowH];
    };
    const shownCount = (k: number): number => {
      const n = Math.pow(b, k);
      const t = frame - revealOf(k);
      if (t < 0) return 0;
      return Math.min(n, Math.floor(((t + 1) * n) / spread));
    };
    for (let k = 0; k < levels; k += 1) {
      const n = Math.pow(b, k);
      const shown = shownCount(k);
      const size = sizeOf(k);
      const line = Math.max(2, Math.round(6 / (k + 1)));
      ctx.fillStyle = INK;
      // Connectors from each shown box's parent.
      if (k > 0) {
        const psize = sizeOf(k - 1);
        for (let i = 0; i < shown; i += 1) {
          const [cx, cy] = posOf(k, i);
          const [px, py] = posOf(k - 1, Math.floor(i / b));
          const mid = Math.round((py + psize / 2 + cy - size / 2) / 2);
          ctx.fillRect(Math.round(px - line / 2), Math.round(py + psize / 2), line, Math.max(0, mid - Math.round(py + psize / 2)));
          ctx.fillRect(Math.round(Math.min(px, cx) - line / 2), mid, Math.round(Math.abs(cx - px)) + line, line);
          ctx.fillRect(Math.round(cx - line / 2), mid, line, Math.max(0, Math.round(cy - size / 2) - mid));
        }
      }
      for (let i = 0; i < shown; i += 1) {
        const [cx, cy] = posOf(k, i);
        const fresh = frame - revealOf(k) < spread + 2 && i >= shown - Math.max(1, Math.ceil(n / spread));
        if (size >= 24) {
          const pad = Math.round(size * 0.2);
          ctx.fillStyle = INK;
          ctx.fillRect(Math.round(cx - size / 2 - pad - 3), Math.round(cy - size / 2 - pad - 3), Math.round(size + 2 * pad + 6), Math.round(size + 2 * pad + 6));
          ctx.fillStyle = COLOR.panel;
          ctx.fillRect(Math.round(cx - size / 2 - pad), Math.round(cy - size / 2 - pad), Math.round(size + 2 * pad), Math.round(size + 2 * pad));
        }
        drawBot(ctx, cx, cy, size, fresh || k === 0);
      }
    }
  };

  const stamp = p.stamp && typeof p.stamp === 'object' && p.stamp.text ? p.stamp : null;
  let stampNode: ReactElement | null = null;
  if (stamp) {
    const age = frame - finiteNumber(stamp.at, 0);
    if (age >= 0) {
      const sc = age === 0 ? 1.6 : age === 1 ? 1.18 : 1;
      const jolt = age === 1 ? 6 : 0;
      stampNode = (
        <div
          style={{
            position: 'absolute',
            left: finiteNumber(stamp.x, 1040),
            top: finiteNumber(stamp.y, 420),
            transform: `translate(${jolt}px, ${-jolt}px) rotate(${finiteNumber(stamp.rotate, -6)}deg) scale(${sc})`,
            transformOrigin: '50% 50%',
            fontFamily: MONO,
            fontSize: finiteNumber(stamp.size, 96),
            lineHeight: 1,
            letterSpacing: '0.1em',
            color: COLOR.rust,
            border: `8px solid ${COLOR.rust}`,
            outline: `3px solid ${COLOR.rust}`,
            outlineOffset: 6,
            padding: '18px 28px 14px',
            whiteSpace: 'nowrap',
            background: 'rgba(247, 244, 237, 0.86)',
            boxShadow: '8px 8px 0 0 rgba(37, 36, 31, 0.9)',
          }}
        >
          {stamp.text}
        </div>
      );
    }
  }

  return (
    <div style={{position: 'absolute', inset: 0, pointerEvents: 'none', background: p.background ?? undefined}}>
      <canvas
        ref={(node) => {
          if (!node) return;
          const ctx = node.getContext('2d');
          if (ctx) paint(ctx);
        }}
        width={1920}
        height={1080}
        style={{position: 'absolute', left: 0, top: 0, width: 1920, height: 1080}}
      />
      {labels.map((text, k) =>
        typeof text === 'string' && k < levels && frame >= revealOf(k) ? (
          <div
            key={k}
            style={{
              position: 'absolute',
              left: 96,
              top: Math.round(y + (k + 0.5) * rowH - 16),
              width: Math.max(120, x - 130),
              fontFamily: MONO,
              fontSize: 26,
              lineHeight: '32px',
              letterSpacing: '0.1em',
              color: k === 0 ? COLOR.orange : COLOR.muted,
              textTransform: 'uppercase',
            }}
          >
            {text}
          </div>
        ) : null,
      )}
      {stampNode}
    </div>
  );
}

import type {ReactElement} from 'react';
import {AbsoluteFill, useCurrentFrame} from 'remotion';
import {COLOR, LOGICAL_PX, finiteNumber, integerIn, narrowParams, oneOf, type ElementComponentProps} from '../../_shared/am';
import {PIXEL_SHAPES, isBlinking, rectCells, shapeCells, type Cell, type PixelShape} from './shape-cells';

// am-pixel-shape: a procedural pixel mark on the sticker grid. No asset, no
// animation except blinkAt, which hides it for two frames as am-sprite does.
// Each cell is px_scale screen px; the shape's top-left sits at (x, y) logical
// px, the same placement as am-sprite. rect takes fill and outline colours
// (either optional; an absent colour is not drawn), and radius in cells.

type Params = {
  shape?: PixelShape;
  color?: string;
  px_scale?: number;
  x?: number;
  y?: number;
  w?: number;
  h?: number;
  stroke?: number;
  radius?: number;
  fill?: string;
  outline?: string;
  blinkAt?: number | number[];
};

export default function AmPixelShape(props: ElementComponentProps): ReactElement | null {
  const frame = useCurrentFrame();
  const params = narrowParams<Params>(props.params);
  const shape = oneOf<PixelShape>(params.shape, PIXEL_SHAPES, 'ring');
  const px = integerIn(params.px_scale, 1, 24, LOGICAL_PX);
  const w = integerIn(params.w, 1, 200, 24);
  const h = integerIn(params.h, 1, 200, 24);
  // stroke defaults to 1 cell for rect and 2 for the other shapes.
  const stroke = integerIn(params.stroke, 1, Math.min(w, h), shape === 'rect' ? 1 : 2);
  const radius = integerIn(params.radius, 0, 100, 0);
  const color = typeof params.color === 'string' && params.color !== '' ? params.color : COLOR.charcoal;
  const fill = typeof params.fill === 'string' && params.fill !== '' ? params.fill : undefined;
  const outline = typeof params.outline === 'string' && params.outline !== '' ? params.outline : undefined;
  const x = finiteNumber(params.x, 0);
  const y = finiteNumber(params.y, 0);
  if (isBlinking(frame, params.blinkAt)) {
    return null;
  }

  // One path per colour, one unit square per cell: hard edges, no anti-aliasing seams.
  const toPath = (cells: Cell[]): string => cells.map(([col, row]) => `M${col} ${row}h1v1h-1z`).join('');
  const paths: {d: string; fill: string}[] = [];
  if (shape === 'rect') {
    const rect = rectCells(w, h, stroke, radius);
    if (fill !== undefined) paths.push({d: toPath(rect.fill), fill});
    if (outline !== undefined) paths.push({d: toPath(rect.outline), fill: outline});
  } else {
    paths.push({d: toPath(shapeCells(shape, w, h, stroke)), fill: color});
  }

  return (
    <AbsoluteFill style={{overflow: 'hidden', pointerEvents: 'none'}}>
      <svg
        style={{position: 'absolute', left: x * LOGICAL_PX, top: y * LOGICAL_PX, overflow: 'visible'}}
        width={w * px}
        height={h * px}
        viewBox={`0 0 ${w} ${h}`}
        shapeRendering="crispEdges"
      >
        {paths.map((p, i) => (
          <path key={i} d={p.d} fill={p.fill} />
        ))}
      </svg>
    </AbsoluteFill>
  );
}

// am-pixel-shape geometry: which cells of a w x h grid are inked for a shape.
// Pure (no imports), so tests can run it directly under node. Cells are [col, row].

export type PixelShape = 'ring' | 'dot' | 'underline' | 'arrow' | 'rect';
export const PIXEL_SHAPES: readonly PixelShape[] = ['ring', 'dot', 'underline', 'arrow', 'rect'];

export type Cell = [number, number];

// rect: a filled w x h box with square or pixel-stepped rounded corners. Inside
// test is a cell-centre test against the corner circle (clamp-to-corner-centre),
// so every radius steps on the cell grid. `radius` is clamped to half the short side.
const inRoundedBox = (
  col: number,
  row: number,
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  radius: number,
): boolean => {
  if (col < x0 || row < y0 || col >= x1 || row >= y1) return false;
  if (radius <= 0) return true;
  const px = col + 0.5;
  const py = row + 0.5;
  const nx = Math.min(Math.max(px, x0 + radius), x1 - radius);
  const ny = Math.min(Math.max(py, y0 + radius), y1 - radius);
  const dx = px - nx;
  const dy = py - ny;
  return dx * dx + dy * dy <= radius * radius;
};

// rectCells: `fill` is the whole silhouette (draw it in the fill colour); `outline`
// is the border ring of `stroke` cells inside it (draw it on top in the outline
// colour). The inner corner radius is radius - stroke, as for a stroked rounded box.
export const rectCells = (
  w: number,
  h: number,
  stroke: number,
  radius: number,
): {fill: Cell[]; outline: Cell[]} => {
  const r = Math.max(0, Math.min(Math.floor(radius), Math.floor(Math.min(w, h) / 2)));
  const s = Math.max(1, Math.min(Math.floor(stroke), Math.floor(Math.min(w, h) / 2) || 1));
  const fill: Cell[] = [];
  const outline: Cell[] = [];
  for (let row = 0; row < h; row += 1) {
    for (let col = 0; col < w; col += 1) {
      if (!inRoundedBox(col, row, 0, 0, w, h, r)) continue;
      fill.push([col, row]);
      if (!inRoundedBox(col, row, s, s, w - s, h - s, Math.max(0, r - s))) outline.push([col, row]);
    }
  }
  return {fill, outline};
};

export const shapeCells = (shape: PixelShape, w: number, h: number, stroke: number, radius = 0): Cell[] => {
  const cells: [number, number][] = [];
  const cx = w / 2;
  const cy = h / 2;
  if (shape === 'rect') {
    return rectCells(w, h, stroke, radius).fill;
  }
  if (shape === 'dot' || shape === 'ring') {
    const rx = w / 2;
    const ry = h / 2;
    const irx = rx - stroke;
    const iry = ry - stroke;
    for (let row = 0; row < h; row += 1) {
      for (let col = 0; col < w; col += 1) {
        const dx = (col + 0.5 - cx) / rx;
        const dy = (row + 0.5 - cy) / ry;
        if (dx * dx + dy * dy > 1) continue;
        if (shape === 'ring' && irx > 0 && iry > 0) {
          const ix = (col + 0.5 - cx) / irx;
          const iy = (row + 0.5 - cy) / iry;
          if (ix * ix + iy * iy <= 1) continue;
        }
        cells.push([col, row]);
      }
    }
  } else if (shape === 'underline') {
    for (let row = Math.max(0, h - stroke); row < h; row += 1) {
      for (let col = 0; col < w; col += 1) cells.push([col, row]);
    }
  } else {
    // arrow: a shaft of `stroke` rows, then a head whose base is the full height
    // and whose tip is at the right edge.
    const head = Math.min(w - 1, Math.max(2, Math.round(h / 2)));
    for (let row = 0; row < h; row += 1) {
      const off = Math.abs(row + 0.5 - cy);
      if (off <= stroke / 2) {
        for (let col = 0; col < w - head; col += 1) cells.push([col, row]);
      }
    }
    for (let k = 0; k < head; k += 1) {
      const half = (h / 2) * (1 - k / head);
      const col = w - head + k;
      for (let row = 0; row < h; row += 1) {
        if (Math.abs(row + 0.5 - cy) <= half) cells.push([col, row]);
      }
    }
  }
  return cells;
};

// Blink rule, the same as am-sprite's blinkAt: the shape hides for two frames
// starting at each listed clip frame. A number or an array of numbers.
export const isBlinking = (frame: number, blinkAt: number | number[] | null | undefined): boolean => {
  const blinks: number[] = Array.isArray(blinkAt) ? blinkAt : typeof blinkAt === 'number' ? [blinkAt] : [];
  return blinks.some((at) => frame >= at && frame < at + 2);
};

import type {ReactElement} from 'react';
import {useCurrentFrame, useVideoConfig} from 'remotion';
import {
  BlockWipe,
  COLOR,
  finiteNumber,
  narrowParams,
  oneOf,
  type ElementComponentProps,
  type WipePattern,
} from '../../_shared/am';

// am-pixel-wipe: a full-frame 6 px block wipe. Progress advances once per
// frame over `frames`, then holds at its end state. Block order is set by
// pattern, and the random pattern is a pure hash of (seed, block index).

type Params = {
  mode?: 'cover' | 'reveal';
  frames?: number;
  color?: string;
  pattern?: WipePattern;
  seed?: number;
};

const MODES = ['cover', 'reveal'] as const;
const PATTERNS: readonly WipePattern[] = ['diagonal', 'random', 'scan'];

export default function AmPixelWipe(props: ElementComponentProps): ReactElement | null {
  const frame = useCurrentFrame();
  const {width, height} = useVideoConfig();
  const params = narrowParams<Params>(props.params);

  const mode = oneOf(params.mode, MODES, 'cover');
  const frames = Math.max(1, Math.round(finiteNumber(params.frames, 12)));
  const color = params.color ?? COLOR.charcoal;
  const pattern = oneOf<WipePattern>(params.pattern, PATTERNS, 'diagonal');
  const seed = Math.trunc(finiteNumber(params.seed, 1));

  return (
    <BlockWipe
      width={width}
      height={height}
      paint={{mode, progress: (frame + 1) / frames, color, pattern, seed}}
    />
  );
}

import type {CSSProperties, ReactElement} from 'react';
import {useCurrentFrame, useVideoConfig} from 'remotion';
import {
  type ElementComponentProps,
  narrowParams,
} from '../../../../../rendering/shared/element_contracts';
import {
  COLOR,
  FAMILY,
  LOGICAL_H,
  LOGICAL_W,
  clipFrames,
  finiteNumber,
  integerIn,
} from '../../_shared/am';
import {mosaicBlockAt, type MosaicRamp} from '../../_shared/mosaic';
import {
  type Anchor,
  type MouthState,
  type PresenterView,
  type Point,
  type Span,
  blinkClosedAt,
  mouthStateAt,
} from './presenter-core';
import {presenterAt} from './motion';

// am-presenter: the Remotion-animated stand-in for the speaker. It draws ONLY
// the pixel overlay (mouth, eyes, blinks, bob) plus crisp UI chrome (label,
// REC and timecode, crop marks, status chip). The plate is a separate
// am-snap-plate clip on the track below. It must use the SAME zoom, focus,
// punchAt, words, seed, blinkEvery, noBlink and bob, so presenterView() puts
// both layers on the same pixels.
//
// Overlay pixels are logical px (1 = 6 screen px at zoom 1). Each rect is an
// absolutely positioned div on the view grid, so edges never blur.

type ChipSpec = {text: string; swapTo?: string; swapAt?: number};

type Params = {
  zoom?: number;
  focus?: Point;
  mouth?: Anchor;
  skin?: string;
  lip?: string;
  inner?: string;
  edge?: string;
  words?: Span[];
  eyes?: Anchor[];
  blinkEvery?: number;
  noBlink?: Span[];
  seed?: number;
  bob?: number;
  punchAt?: number[];
  label?: string;
  timecodeStart?: string;
  chip?: ChipSpec | null;
  /** full: crop marks, REC and label (default). label: the label chip only. none: no chrome. */
  chrome?: 'full' | 'label' | 'none';
  /** Slow continuous push {to, frames, at?}; give the plate the same value. */
  push?: {to: number; frames: number; at?: number} | null;
  /** Same ramps as the plate's: the face overlay hides while the plate is a mosaic. */
  mosaicIn?: MosaicRamp | null;
  mosaicOut?: MosaicRamp | null;
};

// zoom, focus, words, blinks, seed, bob, punchAt and push are read by ./motion.
type Resolved = {
  mouth: Anchor;
  skin: string;
  lip: string;
  inner: string;
  edge: string;
  eyes: Anchor[];
  label: string;
  timecodeStart: string;
  chip: ChipSpec | null;
  chrome: 'full' | 'label' | 'none';
};

// Defaults match the synthetic preview plate (320x180). Replace mouth/eyes with
// the anchors measured on the real P-01 plate.
const DEFAULT_MOUTH: Anchor = {x: 151, y: 104, w: 19};
const DEFAULT_EYES: Anchor[] = [
  {x: 146, y: 85, w: 3},
  {x: 171, y: 85, w: 3},
];

const hexOr = (value: unknown, fallback: string): string =>
  typeof value === 'string' && /^#[0-9a-fA-F]{6}$/.test(value.trim()) ? value.trim() : fallback;

const anchorOr = (value: unknown, fallback: Anchor): Anchor => {
  if (!value || typeof value !== 'object') return fallback;
  const a = value as Record<string, unknown>;
  return {
    x: integerIn(a.x, 0, LOGICAL_W - 1, fallback.x),
    y: integerIn(a.y, 0, LOGICAL_H - 1, fallback.y),
    w: integerIn(a.w, 1, 40, fallback.w),
  };
};

const readParams = (raw: unknown): Resolved => {
  const p = narrowParams<Params>(raw);
  const chipRaw = p.chip && typeof p.chip === 'object' ? p.chip : null;
  return {
    mouth: anchorOr(p.mouth, DEFAULT_MOUTH),
    skin: hexOr(p.skin, '#EDB98E'),
    lip: hexOr(p.lip, '#2B1A14'),
    inner: hexOr(p.inner, '#7A3510'),
    edge: hexOr(p.edge, COLOR.ink),
    eyes: Array.isArray(p.eyes) ? p.eyes.map((e) => anchorOr(e, {x: 0, y: 0, w: 3})) : DEFAULT_EYES,
    label: typeof p.label === 'string' ? p.label : 'PLACEHOLDER · POM ON CAMERA · TAKE 03',
    timecodeStart: typeof p.timecodeStart === 'string' ? p.timecodeStart : '01:02:14:00',
    chrome: p.chrome === 'label' || p.chrome === 'none' ? p.chrome : 'full',
    chip: chipRaw && typeof chipRaw.text === 'string'
      ? {
          text: chipRaw.text,
          swapTo: typeof chipRaw.swapTo === 'string' ? chipRaw.swapTo : undefined,
          swapAt: typeof chipRaw.swapAt === 'number' ? chipRaw.swapAt : undefined,
        }
      : null,
  };
};

type Px = {x: number; y: number; w: number; h: number; color: string};

const pxStyle = (r: Px, v: PresenterView): CSSProperties => ({
  position: 'absolute',
  left: v.originX + r.x * v.scale,
  top: v.originY + r.y * v.scale,
  width: r.w * v.scale,
  height: r.h * v.scale,
  background: r.color,
});

// Mouth pixels. Closed draws nothing: the plate's own closed line shows.
// Half and open first erase the plate's line with skin, then draw the opening.
const mouthPixels = (state: MouthState, m: Anchor, skin: string, lip: string, inner: string): Px[] => {
  if (state === 'closed') return [];
  const erase: Px = {x: m.x - 1, y: m.y - 1, w: m.w + 2, h: 4, color: skin};
  if (state === 'half') {
    return [erase, {x: m.x + 2, y: m.y, w: m.w - 4, h: 1, color: lip}];
  }
  return [
    erase,
    {x: m.x + 2, y: m.y, w: m.w - 4, h: 2, color: lip},
    {x: m.x + 3, y: m.y + 1, w: m.w - 6, h: 1, color: inner},
  ];
};

// Blink: skin fill over the open eye, plus a lid line through its middle.
const blinkPixels = (eyes: Anchor[], skin: string, lip: string): Px[] =>
  eyes.flatMap((e) => [
    {x: e.x - 1, y: e.y - 1, w: e.w + 2, h: 4, color: skin},
    {x: e.x, y: e.y + 1, w: e.w, h: 1, color: lip},
  ]);

// ---- UI chrome (crisp, not pixelated) --------------------------------------

const PANEL = COLOR.panel;
const INK = COLOR.ink;
const REC_RED = '#E5382B';
const CROP_ARM = 40;
const CROP_INSET = 48;
const CROP_THICK = 2;

const CropMarks = (): ReactElement => {
  const corners: Array<[number, number, number, number]> = [
    [CROP_INSET, CROP_INSET, 1, 1],
    [1920 - CROP_INSET, CROP_INSET, -1, 1],
    [CROP_INSET, 1080 - CROP_INSET, 1, -1],
    [1920 - CROP_INSET, 1080 - CROP_INSET, -1, -1],
  ];
  return (
    <>
      {corners.map(([cx, cy, dx, dy]) => (
        <div key={`${cx}-${cy}`} style={{position: 'absolute', background: PANEL, pointerEvents: 'none'}}>
          <div
            style={{
              position: 'absolute',
              left: dx > 0 ? cx : cx - CROP_ARM,
              top: dy > 0 ? cy : cy - CROP_THICK,
              width: CROP_ARM,
              height: CROP_THICK,
              background: PANEL,
            }}
          />
          <div
            style={{
              position: 'absolute',
              left: dx > 0 ? cx : cx - CROP_THICK,
              top: dy > 0 ? cy : cy - CROP_ARM,
              width: CROP_THICK,
              height: CROP_ARM,
              background: PANEL,
            }}
          />
        </div>
      ))}
    </>
  );
};

const TC_RE = /^(\d{1,2}):(\d{2}):(\d{2}):(\d{2})$/;
const parseTimecode = (value: string, fps: number): number => {
  const m = TC_RE.exec(value.trim());
  if (!m) return 0;
  return ((Number(m[1]) * 60 + Number(m[2])) * 60 + Number(m[3])) * fps + Number(m[4]);
};
const formatTimecode = (frames: number, fps: number): string => {
  const f = frames % fps;
  const totalSeconds = Math.floor(frames / fps);
  const pad = (n: number): string => String(n).padStart(2, '0');
  return [
    pad(Math.floor(totalSeconds / 3600) % 100),
    pad(Math.floor(totalSeconds / 60) % 60),
    pad(totalSeconds % 60),
    pad(f),
  ].join(':');
};

const monoChip: CSSProperties = {
  position: 'absolute',
  fontFamily: `'${FAMILY.label}', monospace`,
  fontSize: 22,
  lineHeight: '22px',
  letterSpacing: '0.12em',
  textTransform: 'uppercase',
  whiteSpace: 'nowrap',
  color: INK,
  background: PANEL,
  border: `1px solid ${INK}`,
  padding: '10px 16px',
};

export default function AmPresenter(props: ElementComponentProps): ReactElement | null {
  const frame = useCurrentFrame();
  const config = useVideoConfig();
  const fps = finiteNumber(props.fps, config.fps);
  const p = readParams(props.params);

  // The view and timing live in ./motion so visualize charts the same maths.
  const {timing, view} = presenterAt(props.params, frame, fps);

  // While the plate under this overlay is a mosaic, the crisp face pixels would
  // float over blocks, so they hide for those frames.
  const raw = narrowParams<Params>(props.params);
  const mosaic = mosaicBlockAt(frame, clipFrames(props.clip, fps), raw.mosaicIn, raw.mosaicOut) > 6;
  const pixels: Px[] = mosaic
    ? []
    : [
        ...mouthPixels(mouthStateAt(timing, frame), p.mouth, p.skin, p.lip, p.inner),
        ...(blinkClosedAt(timing, frame) ? blinkPixels(p.eyes, p.skin, p.lip) : []),
      ];

  // A bob pushes the plate down one logical px, uncovering a strip at the top
  // edge (only when the view is already at the plate's top edge). Paint it.
  const bobStrip: CSSProperties | null = view.originY > 0
    ? {position: 'absolute', left: 0, top: 0, width: 1920, height: view.originY, background: p.edge}
    : null;

  const chip = p.chip;
  const chipText = chip && chip.swapAt !== undefined && frame >= chip.swapAt ? (chip.swapTo ?? chip.text) : chip?.text;
  const chipFlash = chip !== null && chip.swapAt !== undefined && frame >= chip.swapAt && frame < chip.swapAt + 2;
  const recOn = Math.floor(frame / Math.max(1, Math.round(fps / 2))) % 2 === 0;
  const timecode = formatTimecode(parseTimecode(p.timecodeStart, fps) + frame, fps);

  return (
    <div style={{position: 'absolute', inset: 0, overflow: 'hidden', pointerEvents: 'none'}}>
      {bobStrip ? <div style={bobStrip} /> : null}
      {pixels.map((r, i) => (
        <div key={i} style={pxStyle(r, view)} />
      ))}

      {p.chrome === 'full' ? <CropMarks /> : null}

      {p.chrome === 'full' ? (
        <div style={{position: 'absolute', left: 104, top: 40, display: 'flex', alignItems: 'center', gap: 14,
          fontFamily: `'${FAMILY.label}', monospace`, fontSize: 22, lineHeight: '22px', color: PANEL,
          textShadow: `2px 2px 0 ${INK}`, whiteSpace: 'nowrap'}}>
          <div style={{width: 12, height: 12, background: recOn ? REC_RED : 'transparent'}} />
          <span>REC</span>
          <span>{timecode}</span>
        </div>
      ) : null}

      {p.chrome === 'none' || !p.label ? null : p.chrome === 'label' ? (
        <div style={{...monoChip, left: 48, bottom: 36, fontSize: 16, lineHeight: '16px', padding: '6px 10px',
          letterSpacing: '0.1em', opacity: 0.9}}>{p.label}</div>
      ) : (
        <div style={{...monoChip, left: 104, bottom: 44}}>{p.label}</div>
      )}

      {chip && chipText !== undefined ? (
        <div
          style={{
            ...monoChip,
            right: 104,
            top: 40,
            background: chipFlash ? COLOR.orange : PANEL,
            color: chipFlash ? PANEL : INK,
          }}
        >
          {chipText}
        </div>
      ) : null}
    </div>
  );
}

// am-presenter's motion as data. The component draws with presenterAt(), and
// `timelines visualize` evaluates motionAt() on the frames it charts (curves,
// bounds, lip sync, lint), so the chart is this element's own maths, not a copy.
// Pure: no React, no DOM, no Math.random.
import {LOGICAL_H, LOGICAL_W, clamp, finiteNumber, integerIn, narrowParams} from '../../_shared/am';
import {
  type Point,
  type PresenterFrame,
  type PresenterTiming,
  type PresenterView,
  type Span,
  blinkClosedAt,
  mouthStateAt,
  presenterView,
} from './presenter-core';

type MotionParams = {
  zoom?: number;
  focus?: Point;
  words?: Span[];
  blinkEvery?: number;
  noBlink?: Span[];
  seed?: number;
  bob?: number;
  punchAt?: number[];
  push?: {to: number; frames: number; at?: number} | null;
};

export const spansOf = (value: unknown): Span[] => {
  if (!Array.isArray(value)) return [];
  const spans: Span[] = [];
  for (const item of value) {
    if (!Array.isArray(item) || item.length < 2) continue;
    const start = finiteNumber(item[0], Number.NaN);
    const end = finiteNumber(item[1], Number.NaN);
    if (Number.isFinite(start) && Number.isFinite(end) && end > start) spans.push([start, end]);
  }
  return spans.sort((a, b) => a[0] - b[0]);
};

// The params that move the presenter, read with the component's defaults.
export const readMotion = (raw: unknown, fps: number): {frame: PresenterFrame; timing: PresenterTiming} => {
  const p = narrowParams<MotionParams>(raw);
  const push = p.push && typeof p.push === 'object' ? p.push : null;
  return {
    frame: {
      zoom: integerIn(p.zoom, 1, 3, 1),
      focus: {
        x: clamp(finiteNumber(p.focus?.x, 160), 0, LOGICAL_W),
        y: clamp(finiteNumber(p.focus?.y, 90), 0, LOGICAL_H),
      },
      punchAt: Array.isArray(p.punchAt)
        ? p.punchAt.filter((n): n is number => typeof n === 'number' && Number.isFinite(n) && n >= 0)
        : [],
      push,
    },
    timing: {
      fps,
      words: spansOf(p.words),
      seed: Math.trunc(finiteNumber(p.seed, 7)),
      blinkEvery: finiteNumber(p.blinkEvery, 3.4),
      noBlink: spansOf(p.noBlink),
      bob: integerIn(p.bob, 0, 1, 0),
    },
  };
};

// The view (zoom, push, punch, focus, bob) and timing on one clip frame.
export const presenterAt = (raw: unknown, clipFrame: number, fps: number): {timing: PresenterTiming; view: PresenterView} => {
  const {frame, timing} = readMotion(raw, fps);
  return {timing, view: presenterView(frame, timing, clipFrame)};
};

const MOUTH_LEVEL = {closed: 0, half: 0.5, open: 1} as const;

// What visualize charts: zoom, view offset (screen px), mouth level and blinks.
export const motionAt = (raw: unknown, clipFrame: number, fps: number): Record<string, number> => {
  const {timing, view} = presenterAt(raw, clipFrame, fps);
  return {
    zoom: view.zoom,
    pan_x: -view.originX,
    pan_y: -view.originY,
    mouth: MOUTH_LEVEL[mouthStateAt(timing, clipFrame)],
    blink: blinkClosedAt(timing, clipFrame) ? 1 : 0,
    visible: 1,
  };
};

// Pure presenter math shared by am-presenter (the Remotion overlay) and by any
// plate that sits under a presenter (am-snap-plate). Both call presenterView()
// and presenterSchedule() with the SAME params, so the plate and the overlay
// stay registered at every zoom, focus, bob and punch. No Math.random, no
// React, no DOM: this file must stay importable from any element.
import {clamp, hashUnit, LOGICAL_H, LOGICAL_W} from '../../_shared/am';

const SCREEN_W = 1920;
const SCREEN_H = 1080;

// One logical px is 6 screen px at zoom 1. zoom 2 is 12 px, zoom 3 is 18 px.
export const BASE_SCALE = 6;
// A punch lifts zoom by one step, capped here so a zoom-3 punch stops at 4.
export const PUNCH_MAX_ZOOM = 4;
// Frames a punch holds (snap up on its first frame, snap back after the 6th).
export const PUNCH_FRAMES = 6;
// Gaps between words no longer than this hold the mouth state; longer gaps close it.
export const GAP_HOLD_S = 0.12;
// Blinks are 2 closed frames.
export const BLINK_FRAMES = 2;

export type Point = {x: number; y: number};
// Mouth and eye anchors: x,y is the top-left logical px of the feature, w its width.
export type Anchor = {x: number; y: number; w: number};
// [start_s, end_s] relative to the clip start, in seconds.
export type Span = [number, number];
export type MouthState = 'closed' | 'half' | 'open';

export type PresenterFrame = {
  zoom: number; // 1 | 2 | 3
  focus: Point; // logical px at the centre of the view (320x180 space)
  punchAt: number[]; // clip frames where zoom+1 snaps on for PUNCH_FRAMES
  // Slow continuous push: zoom moves linearly from `zoom` to `to` over `frames`,
  // starting at clip frame `at` (default 0). This is the camera push that a real
  // take gets; it replaces hard crop jumps. Scale is fractional while it runs.
  push?: {to: number; frames: number; at?: number} | null;
};

// Zoom on a clip frame, before any punch: the base zoom, or the push in progress.
export const pushedZoom = (params: PresenterFrame, clipFrame: number): number => {
  const base = clamp(params.zoom, 1, 3);
  const push = params.push;
  if (!push || !(push.frames > 0) || !Number.isFinite(push.to)) return Math.round(base);
  const t = clamp((clipFrame - (push.at ?? 0)) / push.frames, 0, 1);
  return Math.round(base) + (clamp(push.to, 1, 4) - Math.round(base)) * t;
};

export type PresenterTiming = {
  fps: number;
  words: Span[];
  seed: number;
  blinkEvery: number; // seconds; <= 0 disables blinks
  noBlink: Span[];
  bob: number; // 0 | 1 logical px nudge on stressed words
};

// Geometry is am-snap-plate's: the focus point lands on the frame centre, the
// focus is rounded to whole logical px after clamping, and the plate is drawn
// at (originX, originY) with scale screen px per logical px.
export type PresenterView = {
  zoom: number; // effective zoom for this frame (after a punch)
  scale: number; // screen px per logical px: 6 * zoom
  focusX: number; // integer logical focus actually used (clamped to the plate)
  focusY: number;
  originX: number; // screen px of logical x = 0
  originY: number; // screen px of logical y = 0 (a bob pushes it down by one logical px)
  punched: boolean;
};

const MOUTH_CYCLE: readonly MouthState[] = ['closed', 'half', 'open'];

const orderedWords = (t: PresenterTiming): {start: number; end: number}[] =>
  t.words
    .map(([s, e]) => {
      const start = Math.round(s * t.fps);
      return {start, end: Math.max(start + 1, Math.round(e * t.fps))};
    })
    .sort((a, b) => a.start - b.start);

// Mouth state for a clip frame. Inside a word: closed -> half -> open on a
// 3-frame cycle, offset per word by the seed. In a gap of at most GAP_HOLD_S the
// mouth holds the last in-word state; in a longer gap (or outside all words) it
// is closed. Pixel states only: nothing is interpolated.
export const mouthStateAt = (t: PresenterTiming, frame: number): MouthState => {
  const words = orderedWords(t);
  let index = -1;
  for (let i = 0; i < words.length; i += 1) {
    if (words[i].start <= frame) index = i;
    else break;
  }
  if (index < 0) return 'closed';
  const word = words[index];
  const offset = Math.floor(hashUnit(t.seed, index) * 3);
  if (frame < word.end) {
    return MOUTH_CYCLE[(frame - word.start + offset) % 3];
  }
  const next = words[index + 1];
  const gapFrames = next ? next.start - word.end : Number.POSITIVE_INFINITY;
  if (gapFrames / t.fps <= GAP_HOLD_S) {
    return MOUTH_CYCLE[(word.end - 1 - word.start + offset) % 3];
  }
  return 'closed';
};

// Blink start times (seconds) are blinkEvery * k, jittered +/-30% per blink by
// the seed. A blink whose start falls in a noBlink span is dropped.
const blinkStartSeconds = (t: PresenterTiming, k: number): number => {
  const jitter = (hashUnit(t.seed, 1000 + k) * 2 - 1) * 0.3 * t.blinkEvery;
  return (k + 1) * t.blinkEvery + jitter;
};

const blinkAllowed = (t: PresenterTiming, startS: number): boolean =>
  !t.noBlink.some(([s, e]) => startS >= s && startS < e);

// True on the BLINK_FRAMES closed frames of a blink.
export const blinkClosedAt = (t: PresenterTiming, frame: number): boolean => {
  if (!(t.blinkEvery > 0)) return false;
  const seconds = frame / t.fps;
  const near = Math.floor(seconds / t.blinkEvery);
  for (let k = Math.max(0, near - 1); k <= near + 1; k += 1) {
    const startS = blinkStartSeconds(t, k);
    if (!blinkAllowed(t, startS)) continue;
    const startF = Math.round(startS * t.fps);
    if (frame >= startF && frame < startF + BLINK_FRAMES) return true;
  }
  return false;
};

// Head bob: a 1 logical px nudge on the first frame of every 3rd word. The phase
// (which words are stressed) is seeded, so the same params always bob the same frames.
export const bobPxAt = (t: PresenterTiming, frame: number): number => {
  if (!(t.bob >= 1)) return 0;
  const words = orderedWords(t);
  const phase = Math.floor(hashUnit(t.seed, 77) * 3);
  for (let i = 0; i < words.length; i += 1) {
    if (words[i].start === frame && (i + phase) % 3 === 0) return 1;
  }
  return 0;
};

export const punchedAt = (punchAt: readonly number[], frame: number): boolean =>
  punchAt.some((p) => frame >= p && frame < p + PUNCH_FRAMES);

// The one view transform. The plate is drawn at (originX, originY) with size
// 320*scale by 180*scale; the overlay maps logical (x, y) to screen
// (originX + x*scale, originY + y*scale). A bob moves the plate down one
// logical px (originY += scale), so the plate and the overlay move together.
export const presenterView = (
  params: PresenterFrame,
  timing: PresenterTiming,
  clipFrame: number,
): PresenterView => {
  const base = pushedZoom(params, clipFrame);
  const punched = punchedAt(params.punchAt, clipFrame);
  const zoom = punched ? Math.min(base + 1, PUNCH_MAX_ZOOM) : base;
  const scale = BASE_SCALE * zoom;
  const viewW = SCREEN_W / scale;
  const viewH = SCREEN_H / scale;
  // A push keeps the focus exact (no rounding), so the frame glides instead of
  // snapping a logical px at a time; a held zoom stays on whole logical px.
  const pushing = base !== Math.round(base);
  const fx = clamp(params.focus.x, viewW / 2, LOGICAL_W - viewW / 2);
  const fy = clamp(params.focus.y, viewH / 2, LOGICAL_H - viewH / 2);
  const focusX = pushing ? fx : Math.round(fx);
  const focusY = pushing ? fy : Math.round(fy);
  const bob = bobPxAt(timing, clipFrame);
  return {
    zoom,
    scale,
    focusX,
    focusY,
    originX: Math.round(SCREEN_W / 2 - focusX * scale),
    originY: Math.round(SCREEN_H / 2 - focusY * scale + bob * scale),
    punched,
  };
};

import type {CSSProperties, ReactElement} from 'react';
import {useCurrentFrame, useVideoConfig} from 'remotion';
import {COLOR, FAMILY, clamp, finiteNumber, narrowParams, spanList, type ElementComponentProps} from '../../_shared/am';

// am-quote: a quotation as an editorial document, then overruled.
// The quote can reveal word by word on the VO's word onsets (`words`, the
// builder's @words helper), a strike sweeps through it word by word on single
// frames, and a rubber stamp slams on top. The attribution line can mark one
// word (for example the year) in orange when the stamp lands.

type Params = {
  text?: string;
  attribution?: string;
  x?: number;
  y?: number;
  width?: number;
  size?: number;
  /** [start_s, end_s] per quote word (clip-relative). Word i shows from its onset. */
  words?: [number, number][];
  /** Frame where the strike starts; it crosses one word per `strikeStep` frames. */
  strikeAt?: number;
  strikeStep?: number;
  stamp?: {text?: string; at?: number; x?: number; y?: number; rotate?: number; size?: number} | null;
  /** Orange marker on one attribution word from `at`. */
  mark?: {word?: string; at?: number} | null;
  card?: boolean;
};

const MONO = `'${FAMILY.label}', monospace`;

export default function AmQuote(props: ElementComponentProps): ReactElement | null {
  const frame = useCurrentFrame();
  const {fps: compFps} = useVideoConfig();
  const fps = finiteNumber(props.fps, compFps);
  const p = narrowParams<Params>(props.params);
  const text = typeof p.text === 'string' ? p.text : '';
  if (!text) return null;
  const x = finiteNumber(p.x, 192);
  const y = finiteNumber(p.y, 240);
  const width = finiteNumber(p.width, 1536);
  const size = finiteNumber(p.size, 88);
  const words = text.split(/\s+/).filter(Boolean);
  const spans = spanList(p.words);
  const onset = (i: number): number => (spans.length > 0 ? Math.round((spans[Math.min(i, spans.length - 1)][0]) * fps) : 0);
  const strikeAt = typeof p.strikeAt === 'number' ? p.strikeAt : null;
  const strikeStep = Math.max(1, Math.round(finiteNumber(p.strikeStep, 1)));
  const stamp = p.stamp && typeof p.stamp === 'object' && p.stamp.text ? p.stamp : null;
  const mark = p.mark && typeof p.mark === 'object' && p.mark.word ? p.mark : null;
  const attribution = typeof p.attribution === 'string' ? p.attribution : '';

  const wordStyle = (i: number): CSSProperties => ({
    position: 'relative',
    display: 'inline-block',
    marginRight: '0.24em',
    visibility: spans.length === 0 || i >= spans.length || frame >= onset(i) ? 'visible' : 'hidden',
  });

  const struck = (i: number): number => {
    if (strikeAt === null) return 0;
    const k = frame - (strikeAt + i * strikeStep);
    return k < 0 ? 0 : k === 0 ? 1 : 2; // 1: rust bar, 2: rust + orange offset bar
  };

  let stampNode: ReactElement | null = null;
  if (stamp) {
    const at = finiteNumber(stamp.at, 0);
    const age = frame - at;
    if (age >= 0) {
      const sc = age === 0 ? 1.6 : age === 1 ? 1.18 : 1;
      const jitter = age === 1 ? 6 : 0;
      const ssize = finiteNumber(stamp.size, 78);
      stampNode = (
        <div
          style={{
            position: 'absolute',
            left: finiteNumber(stamp.x, x + width * 0.42),
            top: finiteNumber(stamp.y, y + size * 1.6),
            transform: `translate(${jitter}px, ${-jitter}px) rotate(${finiteNumber(stamp.rotate, -4)}deg) scale(${sc})`,
            transformOrigin: '50% 50%',
            fontFamily: MONO,
            fontSize: ssize,
            lineHeight: 1,
            letterSpacing: '0.1em',
            color: COLOR.rust,
            border: `8px solid ${COLOR.rust}`,
            outline: `3px solid ${COLOR.rust}`,
            outlineOffset: 6,
            padding: '18px 28px 14px',
            whiteSpace: 'nowrap',
            background: 'rgba(247, 244, 237, 0.82)',
            boxShadow: `8px 8px 0 0 rgba(37, 36, 31, 0.9)`,
          }}
        >
          {stamp.text}
        </div>
      );
    }
  }

  const attrTokens = attribution.split(/(\s+)/);
  const markOn = mark !== null && frame >= finiteNumber(mark.at, 0);

  return (
    <div style={{position: 'absolute', inset: 0, pointerEvents: 'none'}}>
      <div style={{position: 'absolute', left: x, top: y, width}}>
        <div
          style={{
            fontFamily: FAMILY.display,
            fontSize: size,
            lineHeight: 1.08,
            letterSpacing: '-0.01em',
            color: COLOR.ink,
          }}
        >
          <span style={{position: 'absolute', left: -size * 0.55, top: -size * 0.12, color: COLOR.orange}}>“</span>
          {words.map((w, i) => {
            const s = struck(i);
            return (
              <span key={i} style={wordStyle(i)}>
                {w}
                {i === words.length - 1 ? <span style={{color: COLOR.orange}}>”</span> : null}
                {s > 0 ? (
                  <span style={{position: 'absolute', left: -size * 0.12, right: -size * 0.24, top: '52%', height: Math.round(size * 0.09), background: COLOR.rust}} />
                ) : null}
                {s > 1 ? (
                  <span style={{position: 'absolute', left: -size * 0.12, right: -size * 0.24, top: `calc(52% + ${Math.round(size * 0.09)}px)`, height: Math.round(size * 0.05), background: COLOR.orange}} />
                ) : null}
              </span>
            );
          })}
        </div>
        {attribution ? (
          <div style={{marginTop: size * 0.5, fontFamily: MONO, fontSize: clamp(size * 0.34, 22, 36), letterSpacing: '0.12em', textTransform: 'uppercase', color: COLOR.muted}}>
            —{' '}
            {attrTokens.map((t, i) =>
              markOn && mark && t === mark.word ? (
                <span key={i} style={{background: COLOR.orange, color: COLOR.panel, padding: '0 6px'}}>{t}</span>
              ) : (
                <span key={i}>{t}</span>
              ),
            )}
          </div>
        ) : null}
      </div>
      {stampNode}
    </div>
  );
}

import type {ReactElement} from 'react';
import {AbsoluteFill, useCurrentFrame} from 'remotion';
import {LOGICAL_H, LOGICAL_W, hashUnit, narrowParams, type ElementComponentProps} from '../../_shared/am';

// am-seasons: a window onto a street through the seasons, drawn on the
// 320x180 logical grid (no assets). A locked camera: the frame, the sill, the
// buildings and the tree stay put; the sky, the leaves, the weather, the plant
// on the sill and the pile of mugs change. Use it as the procedural stand-in
// for the S-00..S-04 window plates, or as a visualization in its own right.
// Weather particles step on twos and are seeded, so frames are repeatable.

type Season = 'autumn' | 'winter' | 'spring' | 'summer' | 'autumn2';
type Key = {at?: number; season?: string; growth?: number; mugs?: number};
type Params = {season?: string; growth?: number; mugs?: number; sequence?: Key[]; seed?: number; label?: boolean};

const SEASONS: readonly Season[] = ['autumn', 'winter', 'spring', 'summer', 'autumn2'];
const DEFAULT_GROWTH: Record<Season, number> = {autumn: 0, winter: 1, spring: 2, summer: 3, autumn2: 4};
const DEFAULT_MUGS: Record<Season, number> = {autumn: 1, winter: 1, spring: 2, summer: 3, autumn2: 6};

type Look = {sky: [string, string]; sun: [number, number, string] | null; leaves: string[]; build: string[]; street: string; wall: string; wallShade: string; lit: number};
const LOOK: Record<Season, Look> = {
  autumn: {sky: ['#F4C08F', '#F8DAB6'], sun: [252, 60, '#FFE6B0'], leaves: ['#ED6B23', '#A94714', '#F2A15A', '#C9541A'], build: ['#C79C80', '#B4836A', '#D6B39A', '#A87A62'], street: '#8B7E72', wall: '#6E5241', wallShade: '#5E4434', lit: 0.1},
  winter: {sky: ['#A9B4BF', '#C8CFD6'], sun: null, leaves: [], build: ['#A79A92', '#968A84', '#B7ACA4', '#8C807A'], street: '#E9ECEE', wall: '#5A4A40', wallShade: '#4C3D35', lit: 0.45},
  spring: {sky: ['#B9D6E4', '#E2EDF0'], sun: null, leaves: ['#F4C3CF', '#FADDE4', '#E9A9BA', '#9CC77A', '#B7D98F'], build: ['#D1AE95', '#BF957C', '#DFC2AA', '#B08872'], street: '#8E8A80', wall: '#6E5241', wallShade: '#5E4434', lit: 0},
  summer: {sky: ['#79B4DE', '#A7D1EC'], sun: [86, 24, '#FFF4C8'], leaves: ['#3D7838', '#559248', '#2E5C2B', '#6AA651'], build: ['#D9B79C', '#C59E84', '#E6CBB3', '#B79079'], street: '#9A9387', wall: '#7A5C48', wallShade: '#684C3A', lit: 0},
  autumn2: {sky: ['#F4C08F', '#F8DAB6'], sun: [252, 60, '#FFE6B0'], leaves: ['#ED6B23', '#A94714', '#F2A15A', '#C9541A'], build: ['#C79C80', '#B4836A', '#D6B39A', '#A87A62'], street: '#8B7E72', wall: '#6E5241', wallShade: '#5E4434', lit: 0.1},
};

const INK = '#25241F';
const CREAM = '#F4E9D7';
const CREAM2 = '#D9C9AE';
// Window opening (logical px).
const WX = 44;
const WY = 12;
const WW = 232;
const WH = 118;

const seasonOf = (v: unknown, fallback: Season): Season =>
  typeof v === 'string' && (SEASONS as readonly string[]).includes(v) ? (v as Season) : fallback;

const paint = (ctx: CanvasRenderingContext2D, season: Season, growth: number, mugs: number, frame: number, seed: number): void => {
  const L = LOOK[season];
  const R = (x: number, y: number, w: number, h: number, c: string): void => {
    ctx.fillStyle = c;
    ctx.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h));
  };
  const disc = (cx: number, cy: number, rx: number, ry: number, c: string): void => {
    for (let dy = -ry; dy <= ry; dy += 1) {
      const span = Math.round(rx * Math.sqrt(Math.max(0, 1 - (dy * dy) / (ry * ry + 0.01))));
      R(cx - span, cy + dy, span * 2 + 1, 1, c);
    }
  };
  const t = Math.floor(frame / 2) * 2;

  // Room wall.
  R(0, 0, LOGICAL_W, LOGICAL_H, L.wall);
  for (let y = 0; y < LOGICAL_H; y += 6) R(0, y, LOGICAL_W, 1, L.wallShade);

  // ---- Outside (clipped to the opening).
  ctx.save();
  ctx.beginPath();
  ctx.rect(WX, WY, WW, WH);
  ctx.clip();
  R(WX, WY, WW, 46, L.sky[0]);
  R(WX, WY + 46, WW, WH - 46, L.sky[1]);
  if (L.sun) disc(L.sun[0], L.sun[1], 7, 7, L.sun[2]);
  // Buildings (fixed silhouettes, colours by season).
  const blocks = [
    [44, 52, 48, 80],
    [92, 40, 40, 92],
    [132, 58, 30, 74],
    [226, 46, 54, 86],
  ];
  blocks.forEach(([bx, by, bw, bh], i) => {
    const c = L.build[i % L.build.length];
    R(bx, by, bw, bh, c);
    R(bx, by, bw, 2, INK);
    R(bx, by, 1, bh, INK);
    if (season === 'winter') R(bx, by - 2, bw, 3, '#F7F8F8');
    for (let wy = by + 7; wy < by + bh - 10; wy += 11) {
      for (let wx = bx + 5; wx < bx + bw - 6; wx += 9) {
        const on = hashUnit(seed + 11, wx * 31 + wy) < L.lit;
        R(wx, wy, 4, 6, on ? '#FFD98A' : '#5B4A42');
      }
    }
  });
  R(WX, 124, WW, 8, L.street);
  // Tree: trunk and branches.
  R(198, 70, 7, 62, '#4A3226');
  R(196, 120, 11, 12, '#4A3226');
  const branch = (x0: number, y0: number, x1: number, y1: number): void => {
    const n = Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0));
    for (let i = 0; i <= n; i += 1) {
      const x = x0 + ((x1 - x0) * i) / n;
      const y = y0 + ((y1 - y0) * i) / n;
      R(x, y, 2, 2, '#4A3226');
      if (season === 'winter' && i % 2 === 0) R(x, y - 1, 2, 1, '#F7F8F8');
    }
  };
  branch(200, 80, 172, 50);
  branch(203, 76, 232, 44);
  branch(201, 72, 196, 34);
  branch(186, 64, 166, 66);
  branch(218, 60, 240, 70);
  // Canopy: seeded blobs, density by season.
  const density = season === 'winter' ? 0 : season === 'autumn2' ? 0.55 : season === 'spring' ? 0.85 : 1;
  if (density > 0) {
    for (let i = 0; i < 46; i += 1) {
      if (hashUnit(seed, i) > density) continue;
      const a = hashUnit(seed + 1, i) * Math.PI * 2;
      const d = Math.sqrt(hashUnit(seed + 2, i));
      const cx = 202 + Math.cos(a) * d * 40;
      const cy = 50 + Math.sin(a) * d * 24;
      const c = L.leaves[Math.floor(hashUnit(seed + 3, i) * L.leaves.length)];
      disc(cx, cy, 6, 5, c);
    }
  }
  // Weather.
  if (season === 'winter') {
    for (let i = 0; i < 90; i += 1) {
      const x0 = WX + hashUnit(seed + 4, i) * WW;
      const speed = 0.5 + hashUnit(seed + 5, i) * 0.6;
      const y = WY + ((hashUnit(seed + 6, i) * WH + t * speed) % WH);
      const x = x0 + Math.round(Math.sin((t + i * 7) / 9) * 2);
      R(x, y, 1, 1, '#FFFFFF');
    }
  } else if (season === 'autumn' || season === 'autumn2') {
    for (let i = 0; i < 16; i += 1) {
      const x0 = 150 + hashUnit(seed + 4, i) * 110;
      const speed = 0.35 + hashUnit(seed + 5, i) * 0.4;
      const y = 50 + ((hashUnit(seed + 6, i) * 80 + t * speed) % 80);
      const x = x0 - ((t * speed * 0.6) % 40);
      R(x, y, 2, 1, L.leaves[i % L.leaves.length]);
    }
  } else if (season === 'spring') {
    for (let i = 0; i < 40; i += 1) {
      const x = WX + hashUnit(seed + 4, i) * WW;
      const y = WY + ((hashUnit(seed + 6, i) * WH + t * 2.5) % WH);
      R(x, y, 1, 3, '#9FB8C8');
    }
  }
  ctx.restore();

  // ---- Window frame, mullions, sill.
  R(WX - 6, WY - 6, WW + 12, 6, CREAM);
  R(WX - 6, WY + WH, WW + 12, 4, CREAM);
  R(WX - 6, WY - 6, 6, WH + 10, CREAM);
  R(WX + WW, WY - 6, 6, WH + 10, CREAM);
  R(WX + WW / 2 - 2, WY, 4, WH, CREAM);
  R(WX, WY + 56, WW, 3, CREAM);
  R(WX - 7, WY - 7, WW + 14, 1, INK);
  R(WX - 7, WY - 7, 1, WH + 12, INK);
  R(WX + WW + 6, WY - 7, 1, WH + 12, INK);
  // Sill.
  R(20, 134, 280, 6, CREAM);
  R(20, 140, 280, 5, CREAM2);
  R(20, 133, 280, 1, INK);
  R(20, 145, 280, 1, INK);
  R(0, 146, LOGICAL_W, LOGICAL_H - 146, L.wallShade);
  // Festive lights in winter.
  if (season === 'winter') {
    const colours = ['#ED6B23', '#FFD27A', '#E5382B', '#9CC77A'];
    for (let i = 0; i * 10 < WW + 8; i += 1) {
      const on = (Math.floor(t / 6) + i) % 3 !== 0;
      R(WX - 2 + i * 10, WY - 3 + (i % 2), 2, 2, on ? colours[i % colours.length] : '#5B4A42');
    }
  }
  // Plant on the sill: pot plus foliage that grows through the year.
  const g = Math.max(0, Math.min(4, growth));
  R(70, 122, 18, 12, '#A94714');
  R(70, 122, 18, 2, '#7E3410');
  R(69, 121, 20, 1, INK);
  const fw = 10 + g * 9;
  const fh = 6 + g * 8;
  for (let i = 0; i < 10 + g * 10; i += 1) {
    const cx = 79 + (hashUnit(seed + 8, i) - 0.5) * fw;
    const cy = 120 - hashUnit(seed + 9, i) * fh;
    disc(cx, cy, 2 + (i % 2), 2, i % 3 === 0 ? '#559248' : '#3D7838');
  }
  if (g >= 4) {
    for (let v = 0; v < 5; v += 1) {
      const vx = 64 + v * 7;
      for (let y = 134; y < 134 + 8 + v * 3; y += 2) R(vx + ((y >> 1) % 2), y, 2, 2, '#3D7838');
    }
  }
  // Mugs: a pile that grows through the year.
  for (let m = 0; m < Math.max(0, Math.min(8, mugs)); m += 1) {
    const col = m % 3;
    const row = Math.floor(m / 3);
    const mx = 232 + col * 11 + row * 5;
    const my = 124 - row * 10;
    R(mx, my, 8, 10, CREAM);
    R(mx, my, 8, 1, INK);
    R(mx, my, 1, 10, INK);
    R(mx + 7, my, 1, 10, INK);
    R(mx + 8, my + 3, 2, 4, INK);
    R(mx + 1, my + 3, 6, 2, m % 2 ? '#ED6B23' : '#A94714');
  }
};

export default function AmSeasons(props: ElementComponentProps): ReactElement {
  const frame = useCurrentFrame();
  const p = narrowParams<Params>(props.params);
  const seed = Math.trunc(typeof p.seed === 'number' ? p.seed : 5);
  let season = seasonOf(p.season, 'autumn');
  let growth = typeof p.growth === 'number' ? p.growth : DEFAULT_GROWTH[season];
  let mugs = typeof p.mugs === 'number' ? p.mugs : DEFAULT_MUGS[season];
  const seq = (Array.isArray(p.sequence) ? p.sequence : []).slice().sort((a, b) => (a.at ?? 0) - (b.at ?? 0));
  for (const k of seq) {
    if ((k.at ?? 0) > frame) break;
    season = seasonOf(k.season, season);
    growth = typeof k.growth === 'number' ? k.growth : DEFAULT_GROWTH[season];
    mugs = typeof k.mugs === 'number' ? k.mugs : DEFAULT_MUGS[season];
  }
  return (
    <AbsoluteFill>
      <canvas
        ref={(node) => {
          if (!node) return;
          const ctx = node.getContext('2d');
          if (ctx) paint(ctx, season, growth, mugs, frame, seed);
        }}
        width={LOGICAL_W}
        height={LOGICAL_H}
        style={{position: 'absolute', left: 0, top: 0, width: 1920, height: 1080, imageRendering: 'pixelated'}}
      />
    </AbsoluteFill>
  );
}

import type {ReactElement} from 'react';
import {AbsoluteFill, Img, useCurrentFrame, useVideoConfig} from 'remotion';
import {
  BlockWipe,
  COLOR,
  LOGICAL_H,
  LOGICAL_W,
  clamp,
  clipFrames,
  elementSource,
  finiteNumber,
  integerIn,
  narrowParams,
  oneOf,
  pixelImage,
  type ElementComponentProps,
  type WipePattern,
} from '../../_shared/am';
import {type Point, type Span} from '../am-presenter/presenter-core';
import {plateView} from './motion';
import {MosaicImage, mosaicBlockAt, type MosaicRamp} from '../../_shared/mosaic';

// am-snap-plate: a pixel snapshot shown through an integer-zoom viewport.
//
// The view is am-presenter's presenterView(), with the same params, so a plate
// under a presenter overlay stays registered through every punch and bob. The
// pan step is folded into the focus before the view is taken; everything else
// (zoom, punch, bob, clamping, rounding) is the shared transform.
//
// Geometry: one logical px is 6 screen px at zoom 1 (presenterView's BASE_SCALE)
// and the composition is 1920x1080. Focus and pan are integer logical px; the
// view stays on the 6 px grid. Pans change only on step boundaries (stepFrames).
//
// Base zoom is 1-3. presenterView caps the base at 3; zoom 4 is reached only by
// a punch (punchAt lifts zoom by one, to 4 at most), exactly as am-presenter does.

type Params = {
  /** Static URL or public path. Managed media goes in clip.asset instead. */
  src?: string;
  zoom?: 1 | 2 | 3;
  focus?: Point;
  pan?: {dx: number; dy: number};
  stepFrames?: 2 | 3;
  /** Clip frames where zoom lifts one step for 6 frames (presenter punch). */
  punchAt?: number[];
  /** Slow continuous push {to, frames, at?} (same as am-presenter). */
  push?: {to: number; frames: number; at?: number} | null;
  /** 0 | 1: nudge the view down one logical px on stressed words (presenter bob). */
  bob?: number;
  /** [start_s, end_s] word spans: the bob and the phase of stressed words follow them. */
  words?: Span[];
  /** Presenter seed. Drives the bob phase; also the random block-wipe order. */
  seed?: number;
  tint?: {color?: string; opacity?: number};
  enter?: 'cut' | 'blockWipe';
  /** Not `exit`: the timeline reads params.exit as an animation phase. */
  exitWipe?: 'cut' | 'blockWipe';
  enterFrames?: number;
  exitFrames?: number;
  pattern?: WipePattern;
  wipeColor?: string;
  background?: string;
  /**
   * Background-only plate: no asset needed. A brand token (paper, panel, ink, muted,
   * rust, orange, rule, charcoal) or any CSS colour. With no src and no clip.asset,
   * the plate is this flat field (plus tint and wipes).
   */
  fill?: string;
  /** Pixelate transition in: starts as coarse blocks and resolves (see _shared/mosaic). */
  mosaicIn?: MosaicRamp | null;
  /** Pixelate transition out: coarsens into blocks over the clip's last frames. */
  mosaicOut?: MosaicRamp | null;
};

const ENTER_EXIT = ['cut', 'blockWipe'] as const;
const PATTERNS: readonly WipePattern[] = ['diagonal', 'random', 'scan'];

// Brand tokens accepted by params.fill; anything else is used as a CSS colour.
const FILL_TOKENS: Record<string, string> = {
  paper: COLOR.paper,
  panel: COLOR.panel,
  ink: COLOR.ink,
  muted: COLOR.muted,
  rust: COLOR.rust,
  orange: COLOR.orange,
  rule: COLOR.rule,
  charcoal: COLOR.charcoal,
};

export default function AmSnapPlate(props: ElementComponentProps): ReactElement | null {
  const frame = useCurrentFrame();
  const {width, height, fps: compositionFps} = useVideoConfig();
  const params = narrowParams<Params>(props.params);
  const url = elementSource(props.assetEntry, params.src);
  const fill = typeof params.fill === 'string' && params.fill.trim() !== ''
    ? (FILL_TOKENS[params.fill.trim()] ?? params.fill.trim())
    : null;
  if (!url && !fill) {
    return null;
  }

  const fps = finiteNumber(props.fps, compositionFps);
  // The view (zoom, push, punch, pan, bob) lives in ./motion so visualize charts the same maths.
  const {timing, view} = plateView(props.params, frame, fps);

  const total = clipFrames(props.clip, fps);
  const enter = oneOf(params.enter, ENTER_EXIT, 'cut');
  const exitWipe = oneOf(params.exitWipe, ENTER_EXIT, 'cut');
  const enterFrames = integerIn(params.enterFrames, 1, 60, 6);
  const exitFrames = integerIn(params.exitFrames, 1, 60, 6);
  const pattern = oneOf<WipePattern>(params.pattern, PATTERNS, 'diagonal');
  const seed = timing.seed;
  const wipeColor = params.wipeColor ?? COLOR.charcoal;
  const background = params.background ?? fill ?? COLOR.paper;

  let wipe: ReactElement | null = null;
  const exitStart = total - exitFrames;
  if (enter === 'blockWipe' && frame < enterFrames) {
    wipe = (
      <BlockWipe
        width={width}
        height={height}
        paint={{mode: 'reveal', progress: (frame + 1) / enterFrames, color: wipeColor, pattern, seed}}
      />
    );
  } else if (exitWipe === 'blockWipe' && frame >= exitStart) {
    wipe = (
      <BlockWipe
        width={width}
        height={height}
        paint={{mode: 'cover', progress: (frame - exitStart + 1) / exitFrames, color: wipeColor, pattern, seed}}
      />
    );
  }

  const tint = params.tint;
  const tintOpacity = clamp(finiteNumber(tint?.opacity, 0.25), 0, 1);

  const block = mosaicBlockAt(frame, total, params.mosaicIn, params.mosaicOut);
  const rect = {x: view.originX, y: view.originY, w: LOGICAL_W * view.scale, h: LOGICAL_H * view.scale};

  return (
    <AbsoluteFill style={{overflow: 'hidden', backgroundColor: background}}>
      {!url ? null : block > 0 ? (
        <MosaicImage url={url} rect={rect} block={block} width={width} height={height} background={background} />
      ) : (
      <Img
        src={url}
        crossOrigin="anonymous"
        style={{
          position: 'absolute',
          left: view.originX,
          top: view.originY,
          width: LOGICAL_W * view.scale,
          height: LOGICAL_H * view.scale,
          maxWidth: 'none',
          maxHeight: 'none',
          display: 'block',
          ...pixelImage,
        }}
      />
      )}
      {tint?.color ? (
        <AbsoluteFill style={{backgroundColor: tint.color, opacity: tintOpacity, pointerEvents: 'none'}} />
      ) : null}
      {wipe}
    </AbsoluteFill>
  );
}

// am-snap-plate's motion as data. The component draws with plateView(), and
// `timelines visualize` evaluates motionAt() on the frames it charts (curves,
// bounds, lint), so the chart is this element's own maths, not a copy.
// Pure: no React, no DOM, no Math.random.
import {LOGICAL_H, LOGICAL_W, finiteNumber, frameList, integerIn, narrowParams, spanList} from '../../_shared/am';
import {
  type Point,
  type PresenterTiming,
  type PresenterView,
  presenterView,
} from '../am-presenter/presenter-core';

type MotionParams = {
  zoom?: number;
  focus?: Point;
  pan?: {dx: number; dy: number};
  stepFrames?: number;
  punchAt?: number[];
  push?: {to: number; frames: number; at?: number} | null;
  bob?: number;
  words?: unknown;
  seed?: number;
};

// The plate's view on a clip frame: am-presenter's presenterView() with the pan
// step folded into the focus first.
export const plateView = (raw: unknown, frame: number, fps: number): {timing: PresenterTiming; view: PresenterView} => {
  const params = narrowParams<MotionParams>(raw);
  const stepFrames = integerIn(params.stepFrames, 2, 3, 2);
  const steps = Math.floor(frame / stepFrames);
  const focusX0 = finiteNumber(params.focus?.x, LOGICAL_W / 2);
  const focusY0 = finiteNumber(params.focus?.y, LOGICAL_H / 2);
  const dx = finiteNumber(params.pan?.dx, 0);
  const dy = finiteNumber(params.pan?.dy, 0);

  const timing: PresenterTiming = {
    fps,
    words: spanList(params.words),
    seed: Math.trunc(finiteNumber(params.seed, 7)),
    blinkEvery: 0,
    noBlink: [],
    bob: integerIn(params.bob, 0, 1, 0),
  };
  const view = presenterView(
    {
      zoom: integerIn(params.zoom, 1, 3, 1),
      focus: {x: focusX0 + dx * steps, y: focusY0 + dy * steps},
      punchAt: frameList(params.punchAt),
      push: params.push && typeof params.push === 'object' ? params.push : null,
    },
    timing,
    frame,
  );
  return {timing, view};
};

// What visualize charts: zoom (base, push or punch) and the view offset in screen px.
export const motionAt = (raw: unknown, frame: number, fps: number): Record<string, number> => {
  const {view} = plateView(raw, frame, fps);
  return {zoom: view.zoom, pan_x: -view.originX, pan_y: -view.originY, visible: 1};
};

import type {CSSProperties, ReactElement} from 'react';
import {Img, useCurrentFrame} from 'remotion';
import {
  LOGICAL_PX,
  elementSource,
  finiteNumber,
  integerIn,
  narrowParams,
  oneOf,
  pixelImage,
  stepStart,
  type ElementComponentProps,
} from '../../_shared/am';

// am-sprite: a transparent pixel cutout on the logical grid.
//
// Each art px is `scale` screen px (6 means one art px per logical px). The
// sprite's top-left sits at (x, y) logical px, so positions are multiples of
// LOGICAL_PX screen px. The outer box is scaled from its top-left corner, and
// the flip is applied inside it, so the sprite stays anchored on its corner.
// Keyframes, flips and slide steps update only on step boundaries.

type Keyframe = {frame: number; x: number; y: number; flipX?: boolean};
type SpriteFrames = {frameWidth: number; frameHeight: number; count: number; fps: number; start?: number; sequence?: number[]};
type Shadow = {groundY?: number; w?: number; h?: number; color?: string; opacity?: number; dx?: number; fade?: number};
type Params = {
  src?: string;
  scale?: number;
  x?: number;
  y?: number;
  flipX?: boolean;
  keyframes?: Keyframe[];
  stepFrames?: 2 | 3;
  enter?: 'stamp' | 'slideIn' | 'cut';
  slideFrom?: 'left' | 'right' | 'top' | 'bottom';
  slideDistance?: number;
  frames?: SpriteFrames;
  blinkAt?: number | number[];
  blinkIndex?: number;
  /** Contact shadow on the ground line (logical px). It narrows as the sprite rises. */
  shadow?: Shadow | null;
  /** Draw the sprite as a flat ink silhouette until clip frame `until` (omit for the whole clip). */
  silhouette?: {until?: number} | boolean | null;
  /** Hard pixel outline in `color`, `px` art px wide; with `pulse` frames it blinks wide/narrow on steps. */
  outline?: {color?: string; px?: number; pulse?: number} | null;
};

const ENTERS = ['stamp', 'slideIn', 'cut'] as const;
const SIDES = ['left', 'right', 'top', 'bottom'] as const;
const SLIDE_STEPS = 4;

export default function AmSprite(props: ElementComponentProps): ReactElement | null {
  const frame = useCurrentFrame();
  const params = narrowParams<Params>(props.params);
  const url = elementSource(props.assetEntry, params.src);
  if (!url) {
    return null;
  }

  const fps = props.fps;
  const scale = integerIn(params.scale, 1, 24, 6);
  const stepFrames = integerIn(params.stepFrames, 2, 3, 2);
  const sf = stepStart(frame, stepFrames);

  // Active keyframe: the last one at or before this step. Keyframes apply
  // as held poses, so the sprite never interpolates between them.
  let x = finiteNumber(params.x, 0);
  let y = finiteNumber(params.y, 0);
  let flipX = params.flipX === true;
  const keyframes = [...(params.keyframes ?? [])].sort((a, b) => a.frame - b.frame);
  for (const key of keyframes) {
    if (key.frame <= sf) {
      x = finiteNumber(key.x, x);
      y = finiteNumber(key.y, y);
      flipX = key.flipX ?? flipX;
    }
  }

  let visible = true;
  let dx = 0;
  let dy = 0;
  const enter = oneOf(params.enter, ENTERS, 'cut');
  if (enter === 'stamp') {
    // 2-frame flicker (on, off) then land 1 px lower on frame 2.
    if (frame < 2) {
      visible = frame === 0;
      dy = -1;
    }
  } else if (enter === 'slideIn') {
    const side = oneOf(params.slideFrom, SIDES, 'left');
    const distance = Math.max(0, finiteNumber(params.slideDistance, 24));
    const k = Math.min(SLIDE_STEPS, Math.floor(frame / stepFrames));
    const remaining = Math.round((distance * (SLIDE_STEPS - k)) / SLIDE_STEPS);
    if (side === 'left') dx = -remaining;
    if (side === 'right') dx = remaining;
    if (side === 'top') dy = -remaining;
    if (side === 'bottom') dy = remaining;
  }

  const blinks: number[] = Array.isArray(params.blinkAt)
    ? params.blinkAt
    : params.blinkAt === undefined
      ? []
      : [params.blinkAt];
  const blinking = blinks.some((at) => frame >= at && frame < at + 2);

  const frames = params.frames;
  let index = 0;
  if (frames && frames.count >= 1 && frames.fps > 0) {
    const tick = Math.floor((frame * frames.fps) / fps);
    const seq = Array.isArray(frames.sequence) ? frames.sequence.filter((n) => Number.isFinite(n)) : [];
    index = seq.length > 0
      ? Math.round(seq[tick % seq.length])
      : Math.round(finiteNumber(frames.start, 0)) + (tick % Math.max(1, Math.round(frames.count)));
  }
  if (blinking) {
    if (frames && typeof params.blinkIndex === 'number') {
      index = params.blinkIndex;
    } else {
      visible = false;
    }
  }

  // Silhouette and outline are CSS filters on the art (inside the scale), so
  // offsets are art px and land on the pixel grid. drop-shadow with 0 blur is a
  // hard 1-art-px ring; four of them make an outline.
  const sil = params.silhouette;
  const silOn = sil === true || (typeof sil === 'object' && sil !== null && (sil.until === undefined || frame < sil.until));
  const ol = params.outline && typeof params.outline === 'object' ? params.outline : null;
  const filters: string[] = [];
  if (silOn) filters.push('brightness(0)');
  if (ol) {
    const pulse = Math.max(0, Math.round(finiteNumber(ol.pulse, 0)));
    const wide = pulse > 0 && Math.floor(frame / pulse) % 2 === 1;
    const w = Math.max(1, Math.round(finiteNumber(ol.px, 1))) + (wide ? 1 : 0);
    const c = typeof ol.color === 'string' ? ol.color : '#ED6B23';
    filters.push(`drop-shadow(${w}px 0 0 ${c})`, `drop-shadow(-${w}px 0 0 ${c})`, `drop-shadow(0 ${w}px 0 ${c})`, `drop-shadow(0 -${w}px 0 ${c})`);
  }
  const artFilter: CSSProperties = filters.length > 0 ? {filter: filters.join(' ')} : {};

  const outer: CSSProperties = {
    position: 'absolute',
    left: (x + dx) * LOGICAL_PX,
    top: (y + dy) * LOGICAL_PX,
    transform: `scale(${scale})`,
    transformOrigin: '0 0',
    lineHeight: 0,
    display: visible ? 'block' : 'none',
  };
  const flip: CSSProperties = {
    transform: flipX ? 'scaleX(-1)' : undefined,
    transformOrigin: 'center center',
  };

  // Sprite size in art px: the strip frame, else the registry resolution.
  const res = /^(\d+)x(\d+)$/.exec(String((props.assetEntry as {resolution?: string} | undefined)?.resolution ?? ''));
  const artW = frames ? Math.max(1, Math.round(frames.frameWidth)) : res ? Number(res[1]) : 0;
  const artH = frames ? Math.max(1, Math.round(frames.frameHeight)) : res ? Number(res[2]) : 0;
  const shadow = params.shadow && typeof params.shadow === 'object' ? params.shadow : null;
  let shadowNode: ReactElement | null = null;
  if (shadow && visible && artW > 0) {
    // Logical px: sprite width and its feet line.
    const spriteW = (artW * scale) / LOGICAL_PX;
    const feet = y + dy + (artH * scale) / LOGICAL_PX;
    const ground = finiteNumber(shadow.groundY, feet);
    const altitude = Math.max(0, ground - feet);
    const k = Math.max(0.35, 1 - altitude / Math.max(1, finiteNumber(shadow.fade, 40)));
    const w = Math.max(2, Math.round(finiteNumber(shadow.w, spriteW * 0.7) * k));
    const h = Math.max(1, Math.round(finiteNumber(shadow.h, 3)));
    const cx = x + dx + spriteW / 2 + finiteNumber(shadow.dx, 0);
    const rows: CSSProperties[] = [];
    for (let r = 0; r < h; r += 1) {
      const t = (r + 0.5) / h - 0.5;
      const rw = Math.max(1, Math.round(w * Math.sqrt(Math.max(0, 1 - 4 * t * t))));
      rows.push({
        position: 'absolute',
        left: Math.round(cx - rw / 2) * LOGICAL_PX,
        top: Math.round(ground - h / 2 + r) * LOGICAL_PX,
        width: rw * LOGICAL_PX,
        height: LOGICAL_PX,
        background: shadow.color ?? '#1F1F1F',
      });
    }
    shadowNode = (
      <div style={{position: 'absolute', inset: 0, opacity: Math.min(1, Math.max(0, finiteNumber(shadow.opacity, 0.35)))}}>
        {rows.map((st, i) => <div key={i} style={st} />)}
      </div>
    );
  }

  if (frames) {
    const fw = Math.max(1, Math.round(frames.frameWidth));
    const fh = Math.max(1, Math.round(frames.frameHeight));
    return (
      <>
      {shadowNode}
      <div style={outer}>
        <div style={{...flip, width: fw, height: fh}}>
          <div style={{position: 'relative', width: fw, height: fh, overflow: 'hidden'}}>
            <Img
              src={url}
              crossOrigin="anonymous"
              style={{position: 'absolute', left: -index * fw, top: 0, display: 'block', maxWidth: 'none', ...pixelImage, ...artFilter}}
            />
          </div>
        </div>
      </div>
      </>
    );
  }

  return (
    <>
      {shadowNode}
      <div style={outer}>
        <div style={flip}>
          <Img src={url} crossOrigin="anonymous" style={{display: 'block', maxWidth: 'none', ...pixelImage, ...artFilter}} />
        </div>
      </div>
    </>
  );
}

import type {CSSProperties, ReactElement} from 'react';
import {useCurrentFrame} from 'remotion';
import {COLOR, FAMILY, finiteNumber, narrowParams, type ElementComponentProps} from '../../_shared/am';

// am-terminal: a terminal window. Command lines type in on single frames after
// a prompt; output lines land whole; a progress line counts on two-frame
// steps. Use REAL commands and real output only (it is shown as evidence).
// Optional badge chips stamp in under the window (brand stamps, outside it).
// look 'brand' (default): the ruled pixel-modernist window. look 'real': a
// realistic macOS-style dark terminal (traffic lights, JetBrains Mono, soft
// shadow, no ink borders), for films where real screens must read as real.

type Progress = {from?: number; to?: number; frames?: number; etaFrom?: number; etaTo?: number};
type LineSpec = {at?: number; text?: string; kind?: string; typeStep?: number; charsPerFrame?: number; progress?: Progress};
type Badge = {at?: number; text?: string; color?: string; ink?: string};
type Params = {
  title?: string;
  x?: number;
  y?: number;
  width?: number;
  height?: number;
  fontSize?: number;
  lines?: LineSpec[];
  badges?: Badge[];
  prompt?: string;
  /** Hide the window chrome and draw only the text (for an overlay on a plate). */
  bare?: boolean;
  /** 'brand' (default, ruled pixel window) or 'real' (a realistic dark terminal). */
  look?: 'brand' | 'real';
};

const MONO = `'${FAMILY.label}', monospace`;
const BG = '#1A1917';
const TEXT = '#E9E4D8';
const DIM = '#8E897E';
const OK = '#8FCB72';
// look 'real': a realistic dark terminal.
const REAL = {
  bg: '#1E1E1E', bar: '#2B2B2B', barText: '#9D9D9D', text: '#E3E3E3', dim: '#8C8C8C', ok: '#7FD47F',
  prompt: '#7FD47F', progress: '#E5C07B', ring: 'rgba(255, 255, 255, 0.10)',
  shadow: '0 30px 70px rgba(0, 0, 0, 0.35), 0 3px 10px rgba(0, 0, 0, 0.25)',
  lights: ['#FF5F57', '#FEBC2E', '#28C840'],
};
const REAL_MONO = "'JetBrains Mono', monospace";
const REAL_UI = "Inter, -apple-system, sans-serif";

export default function AmTerminal(props: ElementComponentProps): ReactElement | null {
  const frame = useCurrentFrame();
  const p = narrowParams<Params>(props.params);
  const real = p.look === 'real';
  const ink = real ? {text: REAL.text, dim: REAL.dim, ok: REAL.ok, prompt: REAL.prompt, progress: REAL.progress, mono: REAL_MONO}
    : {text: TEXT, dim: DIM, ok: OK, prompt: COLOR.orange, progress: COLOR.orange, mono: MONO};
  const barH = real ? 44 : 54;
  const width = finiteNumber(p.width, 1440);
  const height = finiteNumber(p.height, 720);
  const x = finiteNumber(p.x, (1920 - width) / 2);
  const y = finiteNumber(p.y, 120);
  const fontSize = finiteNumber(p.fontSize, 40);
  const lineH = Math.round(fontSize * 1.4);
  const prompt = typeof p.prompt === 'string' ? p.prompt : '$ ';
  const lines = (Array.isArray(p.lines) ? p.lines : []).filter((l) => l && typeof l === 'object');
  const visible = lines.filter((l) => frame >= finiteNumber(l.at, 0));
  const caretOn = Math.floor(frame / 8) % 2 === 0;

  let typingIndex = -1;
  const rendered = visible.map((l, i) => {
    const at = finiteNumber(l.at, 0);
    const kind = typeof l.kind === 'string' ? l.kind : 'out';
    let text = typeof l.text === 'string' ? l.text : '';
    if (kind === 'cmd') {
      const step = Math.max(1, Math.round(finiteNumber(l.typeStep, 1)));
      const cpf = Math.max(1, Math.round(finiteNumber(l.charsPerFrame, 1)));
      const shown = Math.min(text.length, (Math.floor((frame - at) / step) + 1) * cpf);
      if (shown < text.length) typingIndex = i;
      text = text.slice(0, shown);
    }
    if (kind === 'progress' && l.progress) {
      const pr = l.progress;
      const frames = Math.max(1, Math.round(finiteNumber(pr.frames, 60)));
      const t = Math.min(1, Math.floor((frame - at) / 2) * 2 / frames);
      const n = Math.round(finiteNumber(pr.from, 0) + (finiteNumber(pr.to, 0) - finiteNumber(pr.from, 0)) * t);
      const eta = Math.max(0, Math.round(finiteNumber(pr.etaFrom, 0) + (finiteNumber(pr.etaTo, 0) - finiteNumber(pr.etaFrom, 0)) * t));
      text = text.replace('{n}', n.toLocaleString('en-US').replace(/,/g, '')).replace('{eta}', String(eta));
    }
    const color = kind === 'cmd' ? ink.text : kind === 'dim' ? ink.dim : kind === 'ok' ? ink.ok : kind === 'progress' ? ink.progress : ink.text;
    return {kind, text, color, key: i};
  });
  const idle = typingIndex < 0;
  // Top-anchored until the text overflows, then it scrolls (bottom-anchored).
  const charW = fontSize * 0.54;
  const perLine = Math.max(1, Math.floor((width - 56) / charW));
  const usedLines = rendered.reduce((n, r) => n + Math.max(1, Math.ceil((r.text.length + (r.kind === 'cmd' ? prompt.length : 0) + 1) / perLine)), 0) + (idle ? 1 : 0);
  const avail = height - (p.bare ? 0 : barH + 18) - 22;
  const overflow = usedLines * lineH > avail;

  const windowStyle: CSSProperties = p.bare
    ? {position: 'absolute', left: x, top: y, width, height}
    : real
    ? {position: 'absolute', left: x, top: y, width, height, boxSizing: 'border-box', background: REAL.bg, borderRadius: 12,
       boxShadow: `0 0 0 1px ${REAL.ring}, ${REAL.shadow}`, overflow: 'hidden'}
    : {
        position: 'absolute',
        left: x,
        top: y,
        width,
        height,
        boxSizing: 'border-box',
        background: BG,
        border: `3px solid ${COLOR.ink}`,
        borderRadius: 12,
        boxShadow: `12px 12px 0 0 ${COLOR.ink}`,
        overflow: 'hidden',
      };

  const badges = (Array.isArray(p.badges) ? p.badges : []).filter((b) => b && b.text && frame >= finiteNumber(b.at, 0));

  return (
    <div style={{position: 'absolute', inset: 0, pointerEvents: 'none'}}>
      <div style={windowStyle}>
        {p.bare ? null : real ? (
          <div style={{height: barH, position: 'relative', display: 'flex', alignItems: 'center', gap: 9, padding: '0 16px', background: REAL.bar,
                       borderBottom: '1px solid rgba(0, 0, 0, 0.45)'}}>
            {REAL.lights.map((c) => (
              <div key={c} style={{width: 14, height: 14, borderRadius: 7, background: c}} />
            ))}
            <div style={{position: 'absolute', left: 0, right: 0, textAlign: 'center', fontFamily: REAL_UI, fontSize: 17, color: REAL.barText, whiteSpace: 'nowrap'}}>
              {typeof p.title === 'string' ? p.title : 'zsh'}
            </div>
          </div>
        ) : (
          <div style={{height: 54, display: 'flex', alignItems: 'center', gap: 12, padding: '0 20px', background: '#E5E1DA', borderBottom: `3px solid ${COLOR.ink}`}}>
            {[COLOR.rust, COLOR.orange, '#C9C3B6'].map((c) => (
              <div key={c} style={{width: 18, height: 18, background: c, border: `2px solid ${COLOR.ink}`}} />
            ))}
            <div style={{marginLeft: 18, fontFamily: MONO, fontSize: 22, letterSpacing: '0.08em', color: COLOR.ink, whiteSpace: 'nowrap'}}>
              {typeof p.title === 'string' ? p.title : 'zsh'}
            </div>
          </div>
        )}
        <div
          style={{
            position: 'absolute',
            left: 28,
            right: 28,
            top: p.bare ? 0 : barH + 18,
            bottom: 22,
            display: 'flex',
            flexDirection: 'column',
            justifyContent: overflow ? 'flex-end' : 'flex-start',
            overflow: 'hidden',
            fontFamily: ink.mono,
            fontSize,
            lineHeight: `${lineH}px`,
            wordBreak: 'break-all',
            whiteSpace: 'pre-wrap',
          }}
        >
          {rendered.map((r, i) => (
            <div key={r.key} style={{color: r.color}}>
              {r.kind === 'cmd' ? <span style={{color: ink.prompt}}>{prompt}</span> : null}
              {r.text}
              {i === typingIndex ? <span style={{display: 'inline-block', width: fontSize * 0.6, height: fontSize, verticalAlign: 'text-bottom', background: ink.text}} /> : null}
            </div>
          ))}
          {idle ? (
            <div style={{color: ink.text}}>
              <span style={{color: ink.prompt}}>{prompt}</span>
              <span style={{display: 'inline-block', width: fontSize * 0.6, height: fontSize, verticalAlign: 'text-bottom', background: caretOn ? ink.text : 'transparent'}} />
            </div>
          ) : null}
        </div>
      </div>
      {badges.length > 0 ? (
        <div style={{position: 'absolute', left: x, top: y + height + 36, display: 'flex', gap: 18}}>
          {badges.map((b, i) => {
            const age = frame - finiteNumber(b.at, 0);
            const sc = age === 0 ? 1.25 : age === 1 ? 1.06 : 1;
            return (
              <div
                key={i}
                style={{
                  fontFamily: MONO,
                  fontSize: 34,
                  lineHeight: '34px',
                  letterSpacing: '0.12em',
                  padding: '14px 20px',
                  background: b.color ?? COLOR.orange,
                  color: b.ink ?? COLOR.panel,
                  border: `3px solid ${COLOR.ink}`,
                  boxShadow: `6px 6px 0 0 ${COLOR.ink}`,
                  transform: `scale(${sc})`,
                  transformOrigin: 'left center',
                  whiteSpace: 'nowrap',
                }}
              >
                {b.text}
              </div>
            );
          })}
        </div>
      ) : null}
    </div>
  );
}

import type {CSSProperties, ReactElement} from 'react';
import {useCurrentFrame} from 'remotion';
import {COLOR, FAMILY, finiteNumber, narrowParams, type ElementComponentProps} from '../../_shared/am';

// am-tweet: a RECONSTRUCTED post card with a visible slot for the real text.
// It never invents a real person's words and never draws a likeness: the
// avatar is a generic pixel silhouette, the body defaults to a slot marker, and
// a RECONSTRUCTION chip is always on the card. Fill body/date/link only with
// the verbatim post.

type Params = {
  name?: string;
  handle?: string;
  date?: string;
  body?: string;
  link?: string;
  badge?: string;
  note?: string;
  x?: number;
  y?: number;
  width?: number;
  enter?: 'stamp' | 'cut';
  /** Frame where a marker swipe runs across the body (optional). */
  highlightAt?: number;
};

const MONO = `'${FAMILY.label}', monospace`;
const SANS = `'${FAMILY.body}', sans-serif`;
const INK = COLOR.ink;

// 8x8 generic head-and-shoulders silhouette (1 = ink-muted pixel).
const SILHOUETTE = [
  '00011000',
  '00111100',
  '00111100',
  '00011000',
  '00111100',
  '01111110',
  '11111111',
  '11111111',
];
// 7x6 pixel icons for the action row.
const ICONS: Record<string, string[]> = {
  reply: ['0111110', '1000001', '1000001', '0111110', '0010000', '0100000'],
  repost: ['0011100', '0100010', '1110010', '0100111', '0100010', '0011100'],
  like: ['0110110', '1111111', '1111111', '0111110', '0011100', '0001000'],
};

const Bitmap = ({rows, cell, color}: {rows: string[]; cell: number; color: string}): ReactElement => (
  <div style={{position: 'relative', width: rows[0].length * cell, height: rows.length * cell, flexShrink: 0}}>
    {rows.flatMap((row, y) =>
      Array.from(row).map((ch, x) =>
        ch === '1' ? (
          <div key={`${x}-${y}`} style={{position: 'absolute', left: x * cell, top: y * cell, width: cell, height: cell, background: color}} />
        ) : null,
      ),
    )}
  </div>
);

export default function AmTweet(props: ElementComponentProps): ReactElement | null {
  const frame = useCurrentFrame();
  const p = narrowParams<Params>(props.params);
  const width = Math.max(600, finiteNumber(p.width, 1200));
  const x = finiteNumber(p.x, (1920 - width) / 2);
  const y = finiteNumber(p.y, 210);
  const name = typeof p.name === 'string' ? p.name : '[NAME]';
  const handle = typeof p.handle === 'string' ? p.handle : '@handle';
  const date = typeof p.date === 'string' ? p.date : '[DATE NEEDED]';
  const body = typeof p.body === 'string' && p.body ? p.body : '[REAL TWEET TEXT + LINK NEEDED]';
  const isSlot = !(typeof p.body === 'string' && p.body && !p.body.startsWith('['));
  const link = typeof p.link === 'string' ? p.link : '[LINK NEEDED]';
  const badge = typeof p.badge === 'string' ? p.badge : 'RECONSTRUCTION';
  const note = typeof p.note === 'string' ? p.note : 'SLOT · PASTE THE REAL POST VERBATIM';

  let scale = 1;
  let visible = true;
  if (p.enter !== 'cut') {
    if (frame === 0) scale = 1.12;
    else if (frame === 1) visible = false;
    else if (frame === 2) scale = 1.03;
  }
  if (!visible) return null;
  const caretOn = Math.floor(frame / 15) % 2 === 0;
  const hlAt = typeof p.highlightAt === 'number' ? p.highlightAt : null;
  const hl = hlAt === null ? 0 : Math.max(0, Math.min(4, frame - hlAt + 1)) / 4;

  const card: CSSProperties = {
    position: 'absolute',
    left: x,
    top: y,
    width,
    boxSizing: 'border-box',
    padding: '36px 42px 30px',
    background: COLOR.panel,
    border: `3px solid ${INK}`,
    borderRadius: 18,
    boxShadow: `12px 12px 0 0 ${INK}`,
    transform: `scale(${scale})`,
    transformOrigin: '50% 50%',
    color: INK,
  };

  return (
    <div style={{position: 'absolute', inset: 0, pointerEvents: 'none'}}>
      <div style={card}>
        <div style={{display: 'flex', alignItems: 'center', gap: 24}}>
          <div style={{width: 108, height: 108, borderRadius: 54, background: '#E5E1DA', border: `3px solid ${INK}`, display: 'flex', alignItems: 'flex-end', justifyContent: 'center', overflow: 'hidden', flexShrink: 0}}>
            <Bitmap rows={SILHOUETTE} cell={12} color="#8E897E" />
          </div>
          <div style={{minWidth: 0, flex: 1}}>
            <div style={{fontFamily: SANS, fontWeight: 700, fontSize: 44, lineHeight: '52px', whiteSpace: 'nowrap'}}>{name}</div>
            <div style={{fontFamily: SANS, fontSize: 32, lineHeight: '40px', color: COLOR.muted, whiteSpace: 'nowrap'}}>
              {handle} · <span style={{fontFamily: MONO, fontSize: 26}}>{date}</span>
            </div>
          </div>
          <div style={{alignSelf: 'flex-start', fontFamily: MONO, fontSize: 22, lineHeight: '22px', letterSpacing: '0.12em', background: COLOR.orange, color: COLOR.panel, padding: '10px 14px', whiteSpace: 'nowrap'}}>
            {badge}
          </div>
        </div>
        <div
          style={{
            position: 'relative',
            marginTop: 30,
            padding: isSlot ? '30px 30px' : '6px 0',
            border: isSlot ? `3px dashed ${COLOR.rust}` : 'none',
            fontFamily: isSlot ? MONO : SANS,
            fontSize: isSlot ? 46 : 46,
            lineHeight: 1.3,
            letterSpacing: isSlot ? '0.04em' : '0',
            color: isSlot ? COLOR.rust : INK,
          }}
        >
          {hl > 0 ? (
            <div style={{position: 'absolute', left: isSlot ? 24 : 0, top: isSlot ? 30 : 8, height: 58, width: `calc(${hl * 100}% - ${isSlot ? 48 : 0}px)`, background: 'rgba(237, 107, 35, 0.35)'}} />
          ) : null}
          <span style={{position: 'relative'}}>{body}</span>
          {isSlot ? <span style={{display: 'inline-block', width: 26, height: 46, marginLeft: 10, verticalAlign: 'middle', background: caretOn ? COLOR.rust : 'transparent'}} /> : null}
        </div>
        <div style={{marginTop: 22, fontFamily: MONO, fontSize: 24, letterSpacing: '0.06em', color: COLOR.muted}}>{link}</div>
        <div style={{marginTop: 24, paddingTop: 22, borderTop: `2px solid ${COLOR.rule}`, display: 'flex', gap: 120}}>
          {Object.keys(ICONS).map((k) => (
            <Bitmap key={k} rows={ICONS[k]} cell={6} color={COLOR.muted} />
          ))}
        </div>
      </div>
      {note ? (
        <div style={{position: 'absolute', left: x, top: y + 18, transform: 'translateY(-100%)', marginTop: -30, fontFamily: MONO, fontSize: 20, letterSpacing: '0.12em', color: INK, background: COLOR.panel, border: `1px solid ${INK}`, padding: '6px 10px', whiteSpace: 'nowrap'}}>
          {note}
        </div>
      ) : null}
    </div>
  );
}

import type {CSSProperties, ReactElement} from 'react';
import {AbsoluteFill, useCurrentFrame} from 'remotion';
import {
  COLOR,
  FAMILY,
  clamp,
  easeOutCubic,
  finiteNumber,
  narrowParams,
  oneOf,
  type ElementComponentProps,
} from '../../_shared/am';

// am-type: editorial type. Type may ease (masked slide-up uses ease-out
// cubic); the typewriter reveal and the underline step on frames.

type Params = {
  text?: string;
  italicWord?: string;
  /** Colour of the italic word (default rust #A94714; use orange on charcoal, where rust is too dark). */
  italicColor?: string;
  font?: 'display' | 'label';
  size?: number;
  color?: string;
  align?: 'left' | 'center' | 'right';
  x?: number;
  y?: number;
  width?: number;
  reveal?: 'slideUp' | 'type' | 'none';
  tracking?: number;
  lineHeight?: number;
  underlineWord?: string;
  underlineAt?: number;
};

const SLIDE_FRAMES = 8;
const TYPE_FRAMES_PER_CHAR = 2;
const UNDERLINE_FRAMES = 6;
const UNDERLINE_PX = 6;
const FONTS = ['display', 'label'] as const;
const REVEALS = ['slideUp', 'type', 'none'] as const;
const ALIGNS = ['left', 'center', 'right'] as const;

type Run = {text: string; italic: boolean; underline: boolean; space: boolean};

// Split into word and whitespace runs. The first word matching italicWord
// (and the first matching underlineWord) is styled. Punctuation is ignored
// on BOTH sides when matching, so "tomorrow." matches "tomorrow" and an
// italicWord of "year." still matches "year".
const buildRuns = (text: string, italicWordRaw: string, underlineWordRaw: string): Run[] => {
  const cleaned = (token: string): string => token.replace(/[^\p{L}\p{N}']/gu, '').toLowerCase();
  const italicWord = cleaned(italicWordRaw);
  const underlineWord = cleaned(underlineWordRaw);
  let italicUsed = false;
  let underlineUsed = false;
  return text.split(/(\s+)/).filter((part) => part.length > 0).map((part) => {
    if (/^\s+$/.test(part)) {
      return {text: part, italic: false, underline: false, space: true};
    }
    const key = cleaned(part);
    const italic = !italicUsed && italicWord !== '' && key === italicWord;
    if (italic) italicUsed = true;
    const underline = !underlineUsed && underlineWord !== '' && key === underlineWord;
    if (underline) underlineUsed = true;
    return {text: part, italic, underline, space: false};
  });
};

export default function AmType(props: ElementComponentProps): ReactElement | null {
  const frame = useCurrentFrame();
  const params = narrowParams<Params>(props.params);
  const text = typeof params.text === 'string' ? params.text : '';
  if (!text.trim()) {
    return null;
  }

  const font = oneOf(params.font, FONTS, 'display');
  const isLabel = font === 'label';
  const reveal = oneOf(params.reveal, REVEALS, 'slideUp');
  const align = oneOf(params.align, ALIGNS, 'left');
  const size = Math.max(1, finiteNumber(params.size, isLabel ? 28 : 96));
  const tracking = finiteNumber(params.tracking, isLabel ? 0.12 : -0.01);
  const lineHeight = Math.max(0.5, finiteNumber(params.lineHeight, isLabel ? 1.3 : 0.95));
  const color = params.color ?? COLOR.ink;
  const x = finiteNumber(params.x, 96);
  const y = finiteNumber(params.y, 96);
  const width = Math.max(1, finiteNumber(params.width, 1200));

  const italicWord = typeof params.italicWord === 'string' ? params.italicWord.trim() : '';
  const underlineWord = typeof params.underlineWord === 'string' ? params.underlineWord.trim() : '';
  const runs = buildRuns(text, italicWord, underlineWord);

  // Underline draw-in: 6 frames, eased, from underlineAt. Before it starts the
  // background size is 0 and nothing shows.
  const underlineStart = finiteNumber(params.underlineAt, 0);
  const underlineP = easeOutCubic((frame - underlineStart) / UNDERLINE_FRAMES);

  // Typewriter reveal: one character every 2 frames, first character on frame 0.
  const visibleChars = Math.floor(frame / TYPE_FRAMES_PER_CHAR) + 1;
  let charIndex = 0;

  const renderChars = (value: string, key: string): ReactElement[] => {
    const chars = Array.from(value);
    return chars.map((ch, i) => {
      const index = charIndex;
      charIndex += 1;
      const shown = reveal !== 'type' || index < visibleChars;
      return (
        <span key={`${key}-${i}`} style={{opacity: shown ? 1 : 0}}>
          {ch}
        </span>
      );
    });
  };

  const underlineFraction = clamp(underlineP, 0, 1);
  const body = runs.map((run, index) => {
    if (run.space) {
      return <span key={`s-${index}`}>{run.text}</span>;
    }
    // A run can be both the italic word and the underlined word, so the two
    // style sets are merged. The underline is an absolutely positioned bar
    // whose width steps with the eased progress. A background-size gradient on
    // an inline span did not paint in the Remotion renderer.
    const runStyle: CSSProperties = {};
    if (run.italic) {
      Object.assign(runStyle, {fontFamily: FAMILY.display, fontStyle: 'italic', color: params.italicColor ?? COLOR.rust, textTransform: 'none'});
    }
    if (run.underline) {
      runStyle.position = 'relative';
      runStyle.display = 'inline-block';
    }
    return (
      <span key={`w-${index}`} style={runStyle}>
        {renderChars(run.text, `w-${index}`)}
        {run.underline ? (
          <span
            aria-hidden
            style={{
              position: 'absolute',
              left: 0,
              bottom: '-0.1em',
              height: UNDERLINE_PX,
              width: `${underlineFraction * 100}%`,
              backgroundColor: COLOR.orange,
            }}
          />
        ) : null}
      </span>
    );
  });

  const slideProgress = easeOutCubic(frame / SLIDE_FRAMES);
  const slideTransform = reveal === 'slideUp' && frame < SLIDE_FRAMES
    ? `translateY(${(1 - slideProgress) * 100}%)`
    : undefined;

  // The mask gets padding so descenders and italic overhang are not clipped,
  // and the matching negative margin keeps the layout unchanged.
  const mask: CSSProperties = {
    position: 'absolute',
    left: x,
    top: y,
    width,
    // Clip only while the slide is moving. A permanent clip would also cut the
    // underline, which sits below the line box.
    overflow: reveal === 'slideUp' && frame < SLIDE_FRAMES ? 'hidden' : 'visible',
    paddingTop: '0.15em',
    paddingBottom: '0.25em',
    marginTop: '-0.15em',
    marginBottom: '-0.25em',
    boxSizing: 'border-box',
  };
  const line: CSSProperties = {
    color,
    fontFamily: isLabel ? FAMILY.label : FAMILY.display,
    fontSize: size,
    fontWeight: 400,
    lineHeight,
    letterSpacing: `${tracking}em`,
    textAlign: align,
    textTransform: isLabel ? 'uppercase' : 'none',
    whiteSpace: 'pre-wrap',
    transform: slideTransform,
  };

  return (
    <AbsoluteFill style={{pointerEvents: 'none'}}>
      <div style={mask}>
        <div style={line}>{body}</div>
      </div>
    </AbsoluteFill>
  );
}

import type {CSSProperties, ReactElement, ReactNode} from 'react';
import {useCurrentFrame} from 'remotion';
import {COLOR, FAMILY, finiteNumber, hashUnit, integerIn, narrowParams, type ElementComponentProps} from '../../_shared/am';

// am-ui-sketch: a small app window whose interface, behaviour and data layers
// swap while it is in use. Shapes only (no images). A change flickers the
// changed region in 6 px blocks for two frames and throws a few orange sparks.

type Layer = 'A' | 'B' | 'C';
type SketchState = {at: number; interface?: Layer; behaviour?: Layer; data?: Layer};
type Prompt = {text: string; at: number};
type Params = {
  width?: number;
  height?: number;
  title?: string;
  states?: SketchState[];
  prompt?: Prompt | null;
  allAt?: number | null;
  seed?: number;
  /** Group position in frame px. Default: centred in width x height. */
  x?: number;
  y?: number;
  /** Integer scale of the group, 1 or 2. Default: whichever is closest to 70% of the frame height. */
  scale?: 1 | 2;
  /** Pixel arrow cursor. Path points are window px (border included) at absolute frames. */
  cursor?: CursorSpec | null;
};

type Region = 'interface' | 'behaviour' | 'data';
type Values = Record<Region, Layer>;

const DEFAULT_STATES: SketchState[] = [
  {at: 0, interface: 'A', behaviour: 'A', data: 'A'},
  {at: 48, interface: 'B'},
  {at: 96, behaviour: 'B'},
  {at: 144, data: 'B'},
  {at: 204, interface: 'C'},
  {at: 240, behaviour: 'C'},
  {at: 288, data: 'C'},
];

const DEFAULT_PROMPT_TEXT = 'make the sidebar go right, the button a slider, and the table into cards';

// ---- Geometry (window-local px; the body sits 2 px in and 50 px down) -------
const W = 960;
const H = 636;
const BODY_X = 2;
const BODY_Y = 50;
const BODY_W = W - 4;
const BODY_H = H - 52;
const BLOCK = 6;
const SIDEBAR = 192;
const PAD = 24;
// The group is the window plus the prompt bar below it. At scale 1 it is 756 px,
// 70% of a 1080 px frame.
const BUBBLE_GAP = 24;
const BUBBLE_H = 96;
const GROUP_H = H + BUBBLE_GAP + BUBBLE_H;
const FRAME_H = 1080;
const snap6 = (value: number): number => Math.round(value / BLOCK) * BLOCK;

const INK = COLOR.ink;
const PANEL = COLOR.panel;
const SAND = '#E5E1DA';
const SIDE = '#EFEBE3';
const MUTED = COLOR.muted;
const ORANGE = COLOR.orange;
const MONO = `'${FAMILY.label}', monospace`;

type Box = {x: number; y: number; w: number; h: number};

// Layout of the main area for the interface layer.
const layout = (iface: Layer): {sidebar: 'left' | 'right' | null; main: Box; data: Box; behaviour: Box; control: Box; tabs: boolean} => {
  if (iface === 'A') {
    const main: Box = {x: SIDEBAR, y: 0, w: BODY_W - SIDEBAR, h: BODY_H};
    return {
      sidebar: 'left',
      main,
      data: {x: SIDEBAR + PAD, y: PAD, w: main.w - PAD * 2, h: 234},
      behaviour: {x: SIDEBAR + PAD, y: 288, w: main.w - PAD * 2, h: 132},
      control: {x: SIDEBAR + PAD, y: 450, w: main.w - PAD * 2, h: 96},
      tabs: false,
    };
  }
  if (iface === 'B') {
    const main: Box = {x: 0, y: 0, w: BODY_W - SIDEBAR, h: BODY_H};
    return {
      sidebar: 'right',
      main,
      data: {x: PAD, y: PAD, w: main.w - PAD * 2, h: 234},
      behaviour: {x: PAD, y: 288, w: main.w - PAD * 2, h: 132},
      control: {x: PAD, y: 450, w: main.w - PAD * 2, h: 96},
      tabs: false,
    };
  }
  const main: Box = {x: 0, y: 0, w: BODY_W, h: BODY_H};
  return {
    sidebar: null,
    main,
    data: {x: PAD, y: 72, w: main.w - PAD * 2, h: 234},
    behaviour: {x: PAD, y: 330, w: main.w - PAD * 2, h: 132},
    control: {x: PAD, y: 486, w: main.w - PAD * 2, h: 56},
    tabs: true,
  };
};

// Resolve the states into full values, carrying each layer forward.
const resolveStates = (states: SketchState[]): {at: number; values: Values}[] => {
  const sorted = [...states].sort((a, b) => a.at - b.at);
  let current: Values = {interface: 'A', behaviour: 'A', data: 'A'};
  return sorted.map((state) => {
    current = {
      interface: state.interface ?? current.interface,
      behaviour: state.behaviour ?? current.behaviour,
      data: state.data ?? current.data,
    };
    return {at: finiteNumber(state.at, 0), values: {...current}};
  });
};

// Value of a region at frame, plus when it last changed and from what.
const regionAt = (
  resolved: {at: number; values: Values}[],
  region: Region,
  frame: number,
): {value: Layer; changedAt: number | null; from: Layer | null} => {
  let value: Layer = resolved[0]?.values[region] ?? 'A';
  let changedAt: number | null = null;
  let from: Layer | null = null;
  for (let i = 0; i < resolved.length; i += 1) {
    const step = resolved[i];
    if (step.at > frame) break;
    if (i > 0 && resolved[i - 1].values[region] !== step.values[region]) {
      changedAt = step.at;
      from = resolved[i - 1].values[region];
    }
    value = step.values[region];
  }
  return {value, changedAt, from};
};

// ---- Primitives ------------------------------------------------------------

const Box = ({
  box,
  style,
  children,
}: {
  box: Box;
  style?: CSSProperties;
  children?: ReactNode;
}): ReactElement => (
  <div style={{position: 'absolute', left: box.x, top: box.y, width: box.w, height: box.h, ...style}}>{children}</div>
);

const Node = ({x, y, label, w = 120, h = 48}: {x: number; y: number; label: string; w?: number; h?: number}): ReactElement => (
  <div
    style={{
      position: 'absolute',
      left: x,
      top: y,
      width: w,
      height: h,
      boxSizing: 'border-box',
      border: `2px solid ${INK}`,
      background: PANEL,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      fontFamily: MONO,
      fontSize: 14,
      letterSpacing: '0.08em',
      color: INK,
    }}
  >
    {label}
  </div>
);

// Orthogonal pixel wire: 6 px thick segments through the given points.
const Wire = ({points}: {points: [number, number][]}): ReactElement => {
  const segs: ReactElement[] = [];
  for (let i = 0; i < points.length - 1; i += 1) {
    const [ax, ay] = points[i];
    const [bx, by] = points[i + 1];
    const left = Math.min(ax, bx);
    const top = Math.min(ay, by);
    const w = Math.max(BLOCK, Math.abs(bx - ax) + BLOCK);
    const h = Math.max(BLOCK, Math.abs(by - ay) + BLOCK);
    segs.push(
      <div key={i} style={{position: 'absolute', left: left - BLOCK / 2, top: top - BLOCK / 2, width: w, height: h, background: INK}} />,
    );
  }
  return <>{segs}</>;
};

// Layer 1: the interface (sidebar, control).
const SidebarBlock = ({side}: {side: 'left' | 'right'}): ReactElement => (
  <div
    style={{
      position: 'absolute',
      left: side === 'left' ? 0 : BODY_W - SIDEBAR,
      top: 0,
      width: SIDEBAR,
      height: BODY_H,
      background: SIDE,
      borderRight: side === 'left' ? `2px solid ${INK}` : 'none',
      borderLeft: side === 'right' ? `2px solid ${INK}` : 'none',
      boxSizing: 'border-box',
    }}
  >
    {[0, 1, 2, 3].map((i) => (
      <div key={i} style={{position: 'absolute', left: 24, top: 36 + i * 48, width: 12, height: 12, background: i === 0 ? ORANGE : INK}}>
        <div style={{position: 'absolute', left: 24, top: 0, width: 96 - i * 12, height: 12, background: INK}} />
      </div>
    ))}
    <div style={{position: 'absolute', left: 24, top: BODY_H - 72, width: 144, height: 12, background: INK}} />
  </div>
);

const TabStrip = ({labels}: {labels: string[]}): ReactElement => (
  <div style={{position: 'absolute', left: 0, top: 0, width: BODY_W, height: 48, background: SIDE, borderBottom: `2px solid ${INK}`, boxSizing: 'border-box'}}>
    {labels.map((label, i) => (
      <div
        key={label}
        style={{
          position: 'absolute',
          left: 24 + i * 144,
          top: 12,
