        />
        <div style={{position: 'absolute', left: 0, top: 66, fontFamily: MONO, fontSize: 14, color: MUTED}}>0</div>
        <div style={{position: 'absolute', right: 0, top: 66, fontFamily: MONO, fontSize: 14, color: MUTED}}>100</div>
      </Box>
