      <Wire points={[[144, 66], [192, 66]]} />
      <Wire points={[[312, 66], [360, 66]]} />
      <Wire points={[[480, 66], [528, 66]]} />
      <Wire points={[[420, 90], [420, 120], [252, 120], [252, 90]]} />
    </Box>
