{
  "schema_version": 3,
  "id": "chiptune",
  "name": "Chiptune",
  "version": "1.0.0",
  "status": "active",
  "domain": "media",
  "stability": "experimental",
  "support": "core",
  "visibility": "visible",
  "description": "Procedural NES-style music, MIDI played as chiptune, and retro sound effects. Tempo-locked cues with beat-grid JSON for cutting, and one-shot SFX. Pure numpy synthesis: no samples, no network, no models.",
  "keywords": [
    "chiptune",
    "8-bit",
    "nes",
    "music",
    "soundtrack",
    "sfx",
    "sound-effects",
    "procedural-audio",
    "retro"
  ],
  "capabilities": [
    "compose",
    "midi",
    "sfx"
  ],
  "permissions": [
    {
      "id": "project_files",
      "reason": "Writes the rendered music WAV, beat JSON, sfx WAV and sfx batch archives as managed outputs."
    }
  ],
  "documentation": {
    "kind": "skill",
    "path": "docs/SKILL.md"
  },
  "agent": {
    "purpose": "Use to make original retro music beds with exact duration and beat grid, to play a MIDI file (e.g. a Basic Pitch transcription) as an NES chiptune that lines up with its recording, or retro sound effects (stamp, flip, blip, whoosh, chime, error, coin, typewriter_tick, wipe, thud).",
    "do_not_use_for": "Speech or voiceover (use generation.generate_speech), AI-generated audio (use generation.generate_audio or fal foley), or sampled or licensed music.",
    "normal_entrypoints": [
      "chiptune.compose",
      "chiptune.midi",
      "chiptune.sfx"
    ]
  },
  "dependencies": {
    "python_requirements": [
      "numpy"
    ]
  },
  "actions": {
    "compose": {
      "name": "Chiptune Compose",
      "version": "1.0.0",
      "short_description": "Compose a tempo-locked NES-style music cue with bar-snapped sections, a beat grid, and VO ducking.",
      "description": "Generates an original stereo 48 kHz cue from numpy alone: two pulse channels (12.5, 25 and 50 percent duty), a triangle bass and a noise drum channel. Sections of {start_s, end_s, energy, mood} snap to bar lines. Energy sets density (drums, arpeggio rate, octave); mood sets the chord progression and timbre. A seeded motif returns with variation. Outputs music.wav and beats.json (beats, downbeats, bars, per-section levels).",
      "keywords": [
        "chiptune",
        "music",
        "nes",
        "8-bit",
        "soundtrack",
        "bgm",
        "procedural-audio",
        "beat-grid"
      ],
      "invocation": {
        "kind": "command",
        "command": {
          "argv": [
            "{python_exec}",
            "-m",
            "astrid.packs.chiptune.actions.compose.run",
            "--duration-s",
            "{duration_s}",
            "--bpm",
            "{bpm}",
            "--key",
            "{key}",
            "--seed",
            "{seed}",
            "--duck-db",
            "{duck_db}",
            "--master-db",
            "{master_db}",
            "--style",
            "{style}",
            "--out",
            "{out}"
          ],
          "input_args": [
            {
              "input": "sections",
              "flag": "--sections",
              "optional": false
            },
            {
              "input": "hits",
              "flag": "--hits",
              "optional": true
            },
            {
              "input": "duck",
              "flag": "--duck",
              "optional": true
            },
            {
              "input": "vo_mask",
              "flag": "--vo-mask",
              "optional": true
            },
            {
              "input": "mutes",
              "flag": "--mutes",
              "optional": true
            }
          ]
        }
      },
      "inputs": [
        {
          "name": "duration_s",
          "type": "number",
          "required": true,
          "description": "Exact cue length in seconds. The WAV holds round(duration_s * 48000) frames."
        },
        {
          "name": "bpm",
          "type": "integer",
          "required": false,
          "default": 132,
          "description": "Tempo. Every event is locked to this grid."
        },
        {
          "name": "key",
          "type": "string",
          "required": false,
          "default": "A minor",
          "description": "Tonic and mode, for example \"A minor\", \"C major\" or \"F# minor\"."
        },
        {
          "name": "seed",
          "type": "integer",
          "required": false,
          "default": 1,
          "description": "Seed for the motif and drum noise. The same inputs and seed give identical bytes."
        },
        {
          "name": "sections",
          "type": "json",
          "required": true,
          "description": "Array of {start_s, end_s, energy 0..1, mood: bright|tense|wistful|triumphant|silent, cadence_bars 0..8}. Edges are exact; each section starts its own bar grid."
        },
        {
          "name": "hits",
          "type": "json",
          "required": false,
          "description": "JSON array of accent times in seconds (stabs on the chord sounding at that moment), or {t, kind} objects where kind is stab, thud or blip (a two-note blip)."
        },
        {
          "name": "duck",
          "type": "json",
          "required": false,
          "description": "JSON array of {start_s, end_s, gain_db} dips for explicit ducking."
        },
        {
          "name": "vo_mask",
          "type": "json",
          "required": false,
          "description": "JSON array of [start_s, end_s] speech spans. The bed dips by duck_db (120 ms in, 300 ms out); a gap of 0.6 s or more brings it back to full."
        },
        {
          "name": "mutes",
          "type": "json",
          "required": false,
          "description": "JSON array of [start_s, end_s] hard-mute windows. The bed is gone for the window (exact silence, not a duck); use it for dead air and joke holds."
        },
        {
          "name": "duck_db",
          "type": "number",
          "required": false,
          "default": -10,
          "description": "Gain in dB applied under vo_mask spans and as the default for duck items."
        },
        {
          "name": "master_db",
          "type": "number",
          "required": false,
          "default": -16,
          "description": "RMS target in dBFS (a simple LUFS-like proxy). The peak ceiling of -1.05 dBFS wins if they conflict."
        },
        {
          "name": "style",
          "type": "string",
          "required": false,
          "default": "nes",
          "description": "Synthesis style. Only nes is available."
        }
      ],
      "outputs": [
        {
          "name": "music",
          "type": "file",
          "path_template": "{out}/music.wav",
          "artifact_type": "audio",
          "description": "48 kHz stereo 16-bit WAV with slight stereo spread between the pulse channels."
        },
        {
          "name": "beats",
          "type": "file",
          "path_template": "{out}/beats.json",
          "description": "JSON {bpm, beats, downbeats, bars (4-bar phrase starts), sections[]} for snapping cuts."
        }
      ],
      "cache": {
        "mode": "none"
      },
      "isolation": {
        "mode": "subprocess",
        "network": false
      },
      "metadata": {
        "runtime_entrypoint": "main",
        "runtime_file": "actions/compose/run.py",
        "runtime_module": "astrid.packs.chiptune.actions.compose.run",
        "output_result_manifest": true
      },
      "resources": [
        {
          "kind": "implementation",
          "path": "actions/compose/run.py"
        },
        {
          "kind": "implementation",
          "path": "actions/_synth.py"
        },
        {
          "kind": "documentation",
          "path": "actions/compose/STAGE.md"
        }
      ]
    },
    "midi": {
      "name": "Chiptune MIDI",
      "version": "1.0.0",
      "short_description": "Play a MIDI file as an NES-style chiptune: melody on pulse 1, arpeggiated chords on pulse 2, bass on the triangle.",
      "description": "Renders a Standard MIDI File (format 0 or 1, tempo map applied, drums skipped) with the chiptune pack's NES synth. The highest note sounding goes to pulse 1 (25 percent duty, delayed vibrato), the inner chord notes are arpeggiated on pulse 2 (12.5 percent duty, 20 Hz steps) and the lowest note under middle C goes to the triangle. Velocity becomes a 4-bit volume. Note times are the file's own, so a transcription's cue lines up with its recording.",
      "keywords": [
        "chiptune",
        "midi",
        "nes",
        "8-bit",
        "cover",
        "transcription",
        "arrangement"
      ],
      "invocation": {
        "kind": "command",
        "command": {
          "argv": [
            "{python_exec}",
            "-m",
            "astrid.packs.chiptune.actions.midi.run",
            "--midi",
            "{midi}",
            "--start-s",
            "{start_s}",
            "--transpose",
            "{transpose}",
            "--master-db",
            "{master_db}",
            "--out",
            "{out}"
          ],
          "input_args": [
            {
              "input": "duration_s",
              "flag": "--duration-s",
              "optional": true
            }
          ]
        }
      },
      "inputs": [
        {
          "name": "midi",
          "type": "file",
          "required": true,
          "description": "A Standard MIDI File (.mid) as a media handle or path."
        },
        {
          "name": "duration_s",
          "type": "number",
          "required": false,
          "description": "Cue length in seconds from start_s (default: to the last note's end plus 1 s)."
        },
        {
          "name": "start_s",
          "type": "number",
          "required": false,
          "default": 0,
          "description": "Where in the MIDI the cue starts (seconds)."
        },
        {
          "name": "transpose",
          "type": "integer",
          "required": false,
          "default": 0,
          "description": "Semitones, -24..24."
        },
        {
          "name": "master_db",
          "type": "number",
          "required": false,
          "default": -16,
          "description": "RMS target in dBFS; the -1.05 dBFS peak ceiling wins if they conflict."
        }
      ],
      "outputs": [
        {
          "name": "music",
          "type": "file",
          "path_template": "{out}/music.wav",
          "artifact_type": "audio",
          "description": "48 kHz stereo 16-bit WAV."
        },
        {
          "name": "voices",
          "type": "file",
          "path_template": "{out}/voices.json",
          "description": "JSON {midi: summary, voices: {pulse1, pulse2, triangle: {spans, seconds}}, start_s, duration_s}."
        }
      ],
      "cache": {
        "mode": "none"
      },
      "isolation": {
        "mode": "subprocess",
        "network": false
      },
      "metadata": {
        "runtime_entrypoint": "main",
        "runtime_file": "actions/midi/run.py",
        "runtime_module": "astrid.packs.chiptune.actions.midi.run",
        "output_result_manifest": true
      },
      "resources": [
        {
          "kind": "implementation",
          "path": "actions/midi/run.py"
        },
        {
          "kind": "implementation",
          "path": "actions/_midi.py"
        },
        {
          "kind": "implementation",
          "path": "actions/_synth.py"
        },
        {
          "kind": "documentation",
          "path": "actions/midi/STAGE.md"
        }
      ]
    },
    "sfx": {
      "name": "Chiptune SFX",
      "version": "1.0.0",
      "short_description": "Render a retro one-shot sound effect (WAV plus JSON), or a batch of kinds as one zip.",
      "description": "Synthesises a mono 48 kHz 16-bit one-shot from numpy alone: stamp, flip, blip, whoosh, chime, error, coin, typewriter_tick, wipe and thud. The same kind, variant and pitch give identical bytes. Duration is exact (round(duration_s * 48000) samples) and every one-shot starts and ends on a 10 ms ramp. Pass kinds (comma list) to render a batch into one zip of WAVs and JSON sidecars.",
      "keywords": [
        "chiptune",
        "sfx",
        "sound-effects",
        "8-bit",
        "retro",
        "ui-sound",
        "procedural-audio",
        "one-shot"
      ],
      "invocation": {
        "kind": "command",
        "command": {
          "argv": [
            "{python_exec}",
            "-m",
            "astrid.packs.chiptune.actions.sfx.run",
            "--kind",
            "{kind}",
            "--variant",
            "{variant}",
            "--pitch",
            "{pitch}",
            "--out",
            "{out}"
          ],
          "input_args": [
            {
              "input": "kinds",
              "flag": "--kinds",
              "optional": true
            },
            {
              "input": "duration_s",
              "flag": "--duration-s",
              "optional": true
            }
          ]
        }
      },
      "inputs": [
        {
          "name": "kind",
          "type": "string",
          "required": false,
          "default": "blip",
          "description": "One of stamp, flip, blip, whoosh, chime, error, coin, typewriter_tick, wipe, thud. Ignored in batch mode."
        },
        {
          "name": "kinds",
          "type": "string",
          "required": false,
          "description": "Batch mode: comma-separated kinds, for example stamp,flip,coin. Returns one zip (sfx_batch)."
        },
        {
          "name": "variant",
          "type": "integer",
          "required": false,
          "default": 1,
          "description": "Variant seed. Different variants give slightly different takes of the same kind."
        },
        {
          "name": "pitch",
          "type": "number",
          "required": false,
          "default": 0,
          "description": "Pitch shift in semitones relative to A4."
        },
        {
          "name": "duration_s",
          "type": "number",
          "required": false,
          "description": "Exact length in seconds (0.01 to 10). Default is per kind, 0.03 to 1.4 s."
        }
      ],
      "outputs": [
        {
          "name": "sfx",
          "type": "file",
          "path_template": "{out}/sfx.wav",
          "description": "Mono 48 kHz 16-bit one-shot peak-normalised to -3.1 dBFS (single mode). Not a declared media port, so batch mode can run without it."
        },
        {
          "name": "sfx_meta",
          "type": "file",
          "path_template": "{out}/sfx.json",
          "description": "JSON with kind, variant, pitch, exact duration, peak and RMS (sidecar in batch mode too)."
        },
        {
          "name": "sfx_batch",
          "type": "file",
          "path_template": "{out}/sfx-batch.zip",
          "description": "Batch mode only. Zip of NN-kind-vN.wav files with JSON sidecars."
        }
      ],
      "cache": {
        "mode": "none"
      },
      "isolation": {
        "mode": "subprocess",
        "network": false
      },
      "metadata": {
        "runtime_entrypoint": "main",
        "runtime_file": "actions/sfx/run.py",
        "runtime_module": "astrid.packs.chiptune.actions.sfx.run",
        "output_result_manifest": true
      },
      "resources": [
        {
          "kind": "implementation",
          "path": "actions/sfx/run.py"
        },
        {
          "kind": "implementation",
          "path": "actions/_synth.py"
        },
        {
          "kind": "documentation",
          "path": "actions/sfx/STAGE.md"
        }
      ]
    }
  }
}

