import {ManagedVideo as Video} from '../../../../../rendering/shared/managed-media';
import {useMemo, type ReactElement} from 'react';
import {Sequence, useCurrentFrame} from 'remotion';

import {type ElementComponentProps, narrowParams} from '../../../../../rendering/shared/element_contracts';
import {ReadinessImage} from '../../../../shared/readiness-image';
import {sourceSegmentsAtFps, transformAt, validateKeyframes} from './motion';

type Params = {keyframes?: unknown; sourceSegments?: unknown; fit?: 'contain' | 'cover' | 'fill'};

/** One managed media source and one timeline clip; motion and source time remain independently editable. */
export default function AnimatedMediaTransform({clip, params: raw, assetEntry, fps}: ElementComponentProps): ReactElement | null {
  const frame = useCurrentFrame();
  const params = narrowParams<Params>(raw);
  const keys = useMemo(() => validateKeyframes(params.keyframes), [params.keyframes]);
  const durationInFrames = Math.max(1, Math.round((clip.hold ?? 1) * fps));
  const entry = assetEntry as {src?: string; file?: string; url?: string; type?: string} | undefined;
  // Browser uses its resolved media URL; worker staging supplies a renderable file.
  const src = entry?.src || entry?.file || entry?.url;
  const isImage = entry?.type?.startsWith('image');
  const segments = useMemo(() => isImage ? [] : sourceSegmentsAtFps(
    params.sourceSegments ?? [{at: 0, sourceStart: clip.from ?? 0, speed: clip.speed ?? 1}], fps, durationInFrames,
  ), [isImage, params.sourceSegments, clip.from, clip.speed, fps, durationInFrames]);
  if (!src) throw new Error('animated-media-transform requires a resolved managed asset');
  const rect = transformAt(keys, frame / fps);
  const style = {display: 'block', width: '100%', height: '100%', objectFit: params.fit ?? 'contain'} as const;
  const volume = typeof clip.volume === 'number' ? Math.max(0, clip.volume) : 1;
  // Keep source sections mounted ahead of their boundary. Remotion freezes a
  // premounted section on its first frame and hides its wrapper, allowing Video
  // to prepare the decoder before it becomes visible. Only one section is active.
  return <div data-animated-media-transform="true" style={{position: 'absolute', left: rect.x, top: rect.y,
    width: rect.width, height: rect.height, opacity: rect.opacity, overflow: 'hidden'}}>
    {isImage ? <ReadinessImage src={src} mediaId={clip.id} style={style} /> : segments.map((segment) => <Sequence key={segment.fromFrame} from={segment.fromFrame}
      durationInFrames={segment.durationInFrames} premountFor={Math.ceil(fps * 2)} postmountFor={Math.ceil(fps / 2)}>
      <Video src={src} trimBefore={Math.round(segment.sourceStart * fps)} playbackRate={segment.speed}
        muted={volume === 0} volume={volume} style={style} />
    </Sequence>)}
  </div>;
}

/** Clip-local seconds; dimensions and position use the authored canvas pixels. */
export type TransformKeyframe = {at: number; x: number; y: number; width: number; height: number; opacity: number};
export type SourceSegment = {at: number; sourceStart: number; speed: number};
export type FrameSourceSegment = SourceSegment & {fromFrame: number; durationInFrames: number};
const finite = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v);

export function validateKeyframes(value: unknown): TransformKeyframe[] {
  if (!Array.isArray(value) || value.length === 0) throw new Error('animated-media-transform needs keyframes');
  let previous = -1;
  return value.map((row: TransformKeyframe) => {
    if (!row || !['at', 'x', 'y', 'width', 'height', 'opacity'].every((key) => finite(row[key as keyof TransformKeyframe]))
      || row.at < 0 || row.at <= previous || row.width <= 0 || row.height <= 0 || row.opacity < 0 || row.opacity > 1) {
      throw new Error('Transform keyframes must be finite, ordered, positive-size rectangles with opacity 0–1');
    }
    previous = row.at;
    return {...row};
  });
}

/** Linear interpolation between editable samples; clamp outside the key range. */
export function transformAt(keys: readonly TransformKeyframe[], seconds: number): TransformKeyframe {
  const right = keys.findIndex((key) => key.at > seconds);
  if (right === 0) return keys[0]!;
  if (right < 0) return keys[keys.length - 1]!;
  const a = keys[right - 1]!; const b = keys[right]!;
  const p = (seconds - a.at) / (b.at - a.at);
  return {at: seconds, x: a.x + (b.x - a.x) * p, y: a.y + (b.y - a.y) * p,
    width: a.width + (b.width - a.width) * p, height: a.height + (b.height - a.height) * p,
    opacity: a.opacity + (b.opacity - a.opacity) * p};
}

/** Shared rounded boundaries partition the clip: no overlapping media elements or gap frames. */
export function sourceSegmentsAtFps(value: unknown, fps: number, durationInFrames: number): FrameSourceSegment[] {
  if (!finite(fps) || fps <= 0 || !Number.isInteger(durationInFrames) || durationInFrames < 1
    || !Array.isArray(value) || value.length === 0) throw new Error('Invalid source playback timing');
  let previous = -1;
  const segments = value.map((row: SourceSegment) => {
    if (!row || !finite(row.at) || !finite(row.sourceStart) || !finite(row.speed)
      || row.at < 0 || row.sourceStart < 0 || row.speed <= 0) throw new Error('Invalid source playback segment');
    const fromFrame = Math.round(row.at * fps);
    if (fromFrame <= previous || fromFrame >= durationInFrames) throw new Error('Source segment boundaries must occupy distinct increasing frames');
    previous = fromFrame;
    return {...row, fromFrame};
  });
  if (segments[0]!.fromFrame !== 0) throw new Error('Source playback must start at clip frame zero');
  return segments.map((segment, index) => ({...segment,
    durationInFrames: (segments[index + 1]?.fromFrame ?? durationInFrames) - segment.fromFrame}));
}

export function sourceSegmentAt(segments: readonly FrameSourceSegment[], frame: number): FrameSourceSegment | undefined {
  return segments.find((segment) => frame >= segment.fromFrame && frame < segment.fromFrame + segment.durationInFrames);
}

import {ManagedImg as Img, ManagedOffthreadVideo as OffthreadVideo} from '../../../../../rendering/shared/managed-media';
import type {ReactElement} from 'react';
import {interpolate, staticFile, useCurrentFrame, useVideoConfig} from 'remotion';
import {
  type ElementComponentProps,
  narrowParams,
} from '../../../../../rendering/shared/element_contracts';

// Codex-transform insert (shot 16): three reference cards above beam into
// a timeline row; targets flash, glow amber, and swap into new images.
// Duration-relative phases; transparent-safe fx-track overlay.
type Params = {
  __astridAssets?: Record<string, string>;
};

const AMBER = '#ffa02e';
const REFS = ['card0', 'card1', 'card2'];
const ROW = ['card3', 'card4', 'card5', 'card6'];
const SWAPPED = ['card4', 'card5', 'card6', 'card7'];
const TARGETS = [0, 1, 2, 3];

const rowX = (i: number): number => -330 + i * 220;
const ROW_Y = 120;

export default function EndCodexTransform(
  props: ElementComponentProps,
): ReactElement | null {
  const frame = useCurrentFrame();
  const {durationInFrames} = useVideoConfig();
  const params = narrowParams<Params>(props.params);
  const staged = params.__astridAssets ?? {};
  const url = (key: string): string => {
    const p = staged[key];
    return p ? staticFile(p) : staticFile(`astrid-effects/end-codex-transform/${key}`);
  };

  const D = Math.max(1, durationInFrames);
  const refsOn = (i: number): number =>
    interpolate(frame, [(i / 3) * 0.15 * D, ((i / 3) * 0.15 + 0.08) * D], [0, 1], {
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    });
  const beams = interpolate(frame, [0.2 * D, 0.35 * D], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const zoom = interpolate(frame, [0.88 * D, D], [1, 0.94], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  return (
    <div style={{position: 'absolute', inset: 0, overflow: 'hidden'}}>
      <OffthreadVideo
        src={url('plate')}
        muted
        style={{position: 'absolute', inset: 0, width: '100%', height: '100%'}}
      />
      <div
        style={{
          position: 'absolute',
          left: 960,
          top: 520,
          transform: `translate(-50%, -50%) scale(${zoom})`,
        }}
      >
        <div
          style={{
            position: 'absolute',
            left: -410,
            top: -260,
            width: 820,
            height: 200,
            border: '3px solid #3a2408',
            opacity: refsOn(0),
          }}
        >
          <div
            style={{
              position: 'absolute',
              left: 12,
              top: -34,
              color: AMBER,
              fontSize: 24,
              fontFamily: 'monospace',
              letterSpacing: 6,
              opacity: refsOn(0),
            }}
          >
            REFERENCE IMAGES
          </div>
        </div>
        {REFS.map((key, i) => {
          const on = refsOn(i);
          if (on <= 0) return null;
          const x = -260 + i * 260;
          return (
            <div key={key}>
              <Img
                src={url(key)}
                style={{
                  position: 'absolute',
                  left: x - 110,
                  top: -220,
                  width: 220 * on,
                  height: 124 * on,
                  border: '2px solid #3a2408',
                  opacity: on,
                }}
              />
              <div
                style={{
                  position: 'absolute',
                  left: x - 2,
                  top: -90,
                  width: 4,
                  height: 220 * beams,
                  backgroundColor: AMBER,
                  boxShadow: `0 0 16px ${AMBER}`,
                  opacity: beams,
                }}
              />
            </div>
          );
        })}
        <div
          style={{
            position: 'absolute',
            left: -450,
            top: ROW_Y + 130,
            width: 900,
            height: 5,
            backgroundColor: AMBER,
            boxShadow: `0 0 20px ${AMBER}`,
            opacity: beams,
          }}
        />
        {ROW.map((key, i) => {
          const plugged = [-260, 0, 260].some((bx) => Math.abs(rowX(i) - bx) < 120)
            ? beams
            : 0;
          return (
            <div key={key}>
              <Img
                src={url(key)}
                style={{
                  position: 'absolute',
                  left: rowX(i) - 90,
                  top: ROW_Y,
                  width: 180,
                  height: 101,
                  border: '2px solid #3a2408',
                }}
              />
              <div
                style={{
                  position: 'absolute',
                  left: rowX(i) - 8,
                  top: ROW_Y - 12,
                  width: 16,
                  height: 16,
                  borderRadius: 8,
                  backgroundColor: AMBER,
                  boxShadow: `0 0 ${8 + 20 * plugged}px ${AMBER}`,
                  opacity: plugged,
                }}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

import {ManagedImg as Img} from '../../../../../rendering/shared/managed-media';
import type {ReactElement} from 'react';
import {interpolate, staticFile, useCurrentFrame, useVideoConfig} from 'remotion';
import {
  type ElementComponentProps,
  narrowParams,
} from '../../../../../rendering/shared/element_contracts';

// Combined codex+minimax insert: one plate, one persistent timeline row,
// captions drawn per beat. References plug in (codex beat), then two images
// lift out with loading videos (minimax beat). No internal boundary.
type Params = {
  __astridAssets?: Record<string, string>;
};

const AMBER = '#ffa02e';
const ROW = ['card0', 'card1', 'card2', 'card3', 'card4'];
const REFS = ['card5', 'card6', 'card7'];
const PULLED = [1, 3];
const SPLIT = 0.44;

const CAPTION_1 =
  'I used Codex image generation to lock in the pixel style and keep our mink mascot consistent in every shot.';
const CAPTION_2 =
  'Then I animated it end to end in Minimax, trying masking workflows until the motion flowed, with smooth continuations between shots.';

const rowX = (i: number): number => -440 + i * 220;
const ROW_Y = 120;

const captionStyle = (show: number): Record<string, string | number> => ({
  position: 'absolute',
  left: '50%',
  top: -450,
  transform: 'translateX(-50%)',
  color: 'white',
  fontSize: 27,
  fontFamily: 'monospace',
  backgroundColor: 'rgba(0,0,0,0.6)',
  padding: '14px 26px',
  opacity: show,
  textAlign: 'center',
  width: 1400,
  lineHeight: 1.5,
  whiteSpace: 'normal',
});

export default function EndMidCombined(
  props: ElementComponentProps,
): ReactElement | null {
  const frame = useCurrentFrame();
  const {durationInFrames} = useVideoConfig();
  const params = narrowParams<Params>(props.params);
  const staged = params.__astridAssets ?? {};
  const url = (key: string): string => {
    const p = staged[key];
    return p ? staticFile(p) : staticFile(`astrid-effects/end-mid-combined/${key}`);
  };

  const D = Math.max(1, durationInFrames);
  const rowOn = interpolate(frame, [0, 0.06 * D], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const refOn = (i: number): number =>
    interpolate(frame, [(0.06 + (i / 3) * 0.1) * D, (0.06 + (i / 3) * 0.1 + 0.06) * D], [0, 1], {
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    });
  const beams = interpolate(frame, [0.16 * D, 0.28 * D], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const lift = interpolate(frame, [0.52 * D, 0.68 * D], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const loading = interpolate(frame, [0.68 * D, 0.86 * D], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const refFade = 1 - interpolate(frame, [0.4 * D, 0.5 * D], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const zoom = interpolate(frame, [0.92 * D, D], [1, 0.95], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const cap1 = 1 - interpolate(frame, [(SPLIT - 0.03) * D, SPLIT * D], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const cap2 = interpolate(frame, [(SPLIT - 0.03) * D, SPLIT * D], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const dots = loading >= 1 ? 3 : Math.floor(frame / (0.06 * D)) % 4;
  const trackOn = interpolate(frame, [0.02 * D, 0.1 * D], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  return (
    <div style={{position: 'absolute', inset: 0, overflow: 'hidden'}}>
      <Img
        src={url('base')}
        style={{position: 'absolute', inset: 0, width: '100%', height: '100%'}}
      />
      <div
        style={{
          position: 'absolute',
          left: 960,
          top: 540,
