        }}
      >
        <div style={captionStyle(cap1)}>{CAPTION_1}</div>
        <div style={captionStyle(cap2)}>{CAPTION_2}</div>
        <div
          style={{
            position: 'absolute',
            left: -410,
            top: -320,
            width: 820,
            height: 200,
            border: '3px solid #3a2408',
            opacity: refOn(0) * refFade,
          }}
        >
          <div
            style={{
              position: 'absolute',
              left: 12,
              top: -34,
              color: AMBER,
              fontSize: 24,
              fontFamily: 'monospace',
              letterSpacing: 6,
              opacity: refOn(0) * refFade,
            }}
          >
            REFERENCE IMAGES
          </div>
        </div>
        {REFS.map((key, i) => {
          const on = refOn(i);
          if (on <= 0) return null;
          const x = -260 + i * 260;
          return (
            <div key={key}>
              <Img
                src={url(key)}
                style={{
                  position: 'absolute',
                  left: x - 110,
                  top: -280,
                  width: 220 * on,
                  height: 124 * on,
                  border: '2px solid #3a2408',
                  opacity: on * refFade,
                }}
              />
              <div
                style={{
                  position: 'absolute',
                  left: x - 2,
                  top: -150,
                  width: 4,
                  height: 250 * beams,
                  backgroundColor: AMBER,
                  boxShadow: `0 0 16px ${AMBER}`,
                  opacity: beams * refFade,
                }}
              />
            </div>
          );
        })}
        <div
          style={{
            position: 'absolute',
            left: -560,
            top: ROW_Y + 120,
            width: 1120 * trackOn,
            height: 5,
            backgroundColor: AMBER,
            boxShadow: `0 0 20px ${AMBER}`,
            opacity: trackOn,
          }}
        />
        {ROW.map((key, i) => {
          const pulled = PULLED.includes(i);
          return (
            <div key={key}>
              <Img
                src={url(key)}
                style={{
                  position: 'absolute',
                  left: rowX(i) - 90,
                  top: ROW_Y,
