                  height: 101,
                  border: '2px solid #3a2408',
                  opacity: rowOn,
                }}
              />
              <div
                style={{
                  position: 'absolute',
                  left: rowX(i) - 8,
                  top: ROW_Y - 12,
                  width: 16,
                  height: 16,
                  borderRadius: 8,
                  backgroundColor: AMBER,
                  boxShadow: `0 0 24px ${AMBER}`,
                  opacity: beams * rowOn,
                }}
              />
              {pulled && lift > 0 && (
                <div>
                  <div
                    style={{
                      position: 'absolute',
                      left: rowX(i) - 1,
                      top: ROW_Y + 101,
                      width: 3,
                      height: 120 * lift,
                      backgroundColor: AMBER,
                      boxShadow: `0 0 12px ${AMBER}`,
                    }}
                  />
                  <Img
                    src={url(key)}
                    style={{
                      position: 'absolute',
                      left: rowX(i) - 110,
