                  />
                  <div
                    style={{
                      position: 'absolute',
                      left: rowX(i) - 130,
                      top: ROW_Y - 270,
                      width: 260,
                      height: 146,
                      border: `3px solid ${AMBER}`,
                      boxShadow: `0 0 30px ${AMBER}`,
                      backgroundColor: '#0a0603',
                      opacity: lift,
                    }}
                  >
                    <Img
                      src={url(key)}
                      style={{
                        position: 'absolute',
                        inset: 0,
                        width: '100%',
                        height: '100%',
                        opacity: 0.85,
                      }}
                    />
                    <div
                      style={{
                        position: 'absolute',
                        left: '50%',
                        top: '50%',
                        transform: 'translate(-50%,-50%)',
                        width: 0,
                        height: 0,
                        borderLeft: '26px solid #ffb14e',
                        borderTop: '16px solid transparent',
                        borderBottom: '16px solid transparent',
                        opacity: loading >= 1 ? 1 : 0.35,
                      }}
                    />
                    {loading < 1 && (
                      <div
                        style={{
                          position: 'absolute',
                          left: 0,
                          right: 0,
                          bottom: 10,
                          textAlign: 'center',
