                  </div>
                  <div
                    style={{
                      position: 'absolute',
                      left: rowX(i) - 1,
                      top: ROW_Y - 124,
                      width: 3,
                      height: 124,
                      backgroundColor: AMBER,
                      boxShadow: `0 0 12px ${AMBER}`,
                      opacity: lift,
                    }}
                  />
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

