                  border: '2px solid #3a2408',
                  opacity: rowOn,
                }}
              />
              {pulled && lift > 0 && (
                <div>
                  <div
                    style={{
                      position: 'absolute',
                      left: rowX(i) - 1,
                      top: y + 101,
                      width: 3,
                      height: 130 * lift,
                      backgroundColor: AMBER,
                      boxShadow: `0 0 12px ${AMBER}`,
                    }}
                  />
                  <Img
                    src={url(key)}
                    style={{
                      position: 'absolute',
                      left: rowX(i) - 110,
                      top: y + 101 + 130 * lift,
                      width: 220,
                      height: 124,
                      border: `3px solid ${AMBER}`,
                      boxShadow: `0 0 26px ${AMBER}`,
                      opacity: lift,
                    }}
                  />
                  <div
                    style={{
                      position: 'absolute',
                      left: rowX(i) - 130,
                      top: y - 250,
                      width: 260 * pulse,
                      height: 146 * pulse,
                      border: `3px solid ${AMBER}`,
                      boxShadow: `0 0 30px ${AMBER}`,
                      backgroundColor: '#0a0603',
                      opacity: lift,
                    }}
                  >
                    <Img
                      src={url(key)}
                      style={{
                        position: 'absolute',
                        inset: 0,
                        width: '100%',
                        height: '100%',
                        opacity: 0.85,
                      }}
                    />
                    <div
                      style={{
                        position: 'absolute',
                        left: '50%',
                        top: '50%',
                        transform: 'translate(-50%,-50%)',
                        width: 0,
                        height: 0,
                        borderLeft: '26px solid #ffb14e',
                        borderTop: '16px solid transparent',
                        borderBottom: '16px solid transparent',
                        opacity: loading >= 1 ? 1 : 0.35,
                      }}
                    />
                    {loading < 1 && (
                      <div
                        style={{
                          position: 'absolute',
                          left: 0,
                          right: 0,
                          bottom: 10,
                          textAlign: 'center',
                          color: '#ffb14e',
                          fontSize: 30,
                          fontFamily: 'monospace',
                        }}
                      >
                        {'●'.repeat(dots) + '○'.repeat(3 - dots)}
                      </div>
                    )}
                  </div>
                  <div
