runtime:
  adapter: remotion

/** Pure renderer timing. No React, media loading, or submitted code execution. */
export type TimelineSegment = {id?: string; start: number; end: number; sourceStart?: number; sourceEnd?: number; speed?: number; label: string; title: string};
export type TimingParams = {
  phaseDurations?: {prep?: number; iteration?: number; anchors?: number; workflow?: number};
  prepSeconds?: number; iterationSeconds?: number; anchorsSeconds?: number; workflowSeconds?: number;
  selectedSegmentId?: string; selectedSegmentIndex?: number; timelineSegments?: TimelineSegment[];
};
export const positive = (v: unknown): number | null => typeof v === 'number' && Number.isFinite(v) && v > 0 ? v : null;
export const nonnegative = (v: unknown): number | null => typeof v === 'number' && Number.isFinite(v) && v >= 0 ? v : null;
const DEFAULT_SEGMENTS: TimelineSegment[] = [
  {id: 'astrid', start: 0, end: 5, label: '00', title: 'ASTRID — through the glasses'},
  {id: 'choice', start: 5, end: 8, sourceStart: 74.9347, sourceEnd: 76.4, speed: 0.4884, label: '01', title: 'Two options'},
  {id: 'blue', start: 8, end: 19, sourceStart: 79.12, sourceEnd: 80.87, label: '02', title: 'Blue pill — manual tools'},
  {id: 'red', start: 19, end: 22, label: '03', title: 'Red pill'},
  {id: 'creature', start: 22, end: 26.9167, label: '04', title: 'Creature reveal — glasses edit'},
  {id: 'reflection', start: 26.9167, end: 43.4927, label: '05', title: 'Into the minkhole — reflection close-up'},
];
export function phaseValues(params: TimingParams, clipSeconds: number): [number, number, number, number] {
  const configured = params.phaseDurations ?? {};
  const values = [positive(params.prepSeconds) ?? positive(configured.prep), positive(params.iterationSeconds) ?? positive(configured.iteration),
    positive(params.anchorsSeconds) ?? positive(configured.anchors), positive(params.workflowSeconds) ?? positive(configured.workflow)];
  return values.every((v): v is number => v !== null) ? values as [number, number, number, number]
    : [0.24, 0.22, 0.2, 0.34].map(w => clipSeconds * w) as [number, number, number, number];
}
export function validSegments(value: unknown): TimelineSegment[] {
  if (!Array.isArray(value)) return DEFAULT_SEGMENTS;
  const result = value.filter((s): s is TimelineSegment => !!s && typeof s === 'object'
    && typeof s.start === 'number' && Number.isFinite(s.start) && typeof s.end === 'number' && Number.isFinite(s.end) && s.end > s.start
    && typeof s.label === 'string' && s.label.length > 0 && typeof s.title === 'string' && s.title.length > 0);
  return result.length ? result : DEFAULT_SEGMENTS;
}
export function selectedSegmentIndex(params: TimingParams, segments: TimelineSegment[]): number {
  const requested = typeof params.selectedSegmentIndex === 'number' && Number.isFinite(params.selectedSegmentIndex) && params.selectedSegmentIndex >= 0 ? params.selectedSegmentIndex : null;
  return typeof params.selectedSegmentId === 'string' ? Math.max(0, segments.findIndex(s => s.id === params.selectedSegmentId))
    : requested === null ? Math.min(segments.length - 1, 2) : Math.min(segments.length - 1, Math.floor(requested));
}
export function endSpanningTiming(clip: {hold?: number; to?: number; at: number}, params: TimingParams, fps: number) {
  const clipSeconds = positive(clip.hold) ?? positive((clip.to ?? 0) - clip.at) ?? 30;
  const seconds = phaseValues(params, clipSeconds);
  let cumulative = 0;
  const frames = seconds.map(s => Math.round((cumulative += s) * fps));
  return {clipSeconds, seconds, frames, effectEndFrame: Math.max(frames[3]!, Math.round(clipSeconds * fps))};
}

import {ManagedImg as Img, ManagedOffthreadVideo as OffthreadVideo} from '../../../../../rendering/shared/managed-media';
import type {ReactElement} from 'react';
import {interpolate, staticFile, useCurrentFrame, useVideoConfig} from 'remotion';
import {
  type ElementComponentProps,
  narrowParams,
} from '../../../../../rendering/shared/element_contracts';

// Ending-carousel insert for the Astrid intro (shot 15). Base plate
// full-screen, then over the middle band: shuffle (one big card cycling
// fast), highlight + place (winner glows and flies to grid slot 0),
// grid fill (rest pop in), timeline (all fly onto an amber track),
// reorder (swap into final order with a lift). Duration-relative.
type Params = {
  __astridAssets?: Record<string, string>;
};

const AMBER = '#ffa02e';

const CARD_KEYS = [
  'card0',
  'card1',
  'card2',
  'card3',
  'card4',
  'card5',
  'card6',
  'card7',
];

const FINAL_ORDER = [3, 0, 5, 1, 6, 2, 7, 4];
const SHUFFLE_LAST = 5;

const gridOf = (i: number): {x: number; y: number} => ({
  x: -450 + (i % 4) * 300,
  y: -110 + Math.floor(i / 4) * 220,
});

export default function EndingCarousel(
  props: ElementComponentProps,
): ReactElement | null {
  const frame = useCurrentFrame();
  const {durationInFrames} = useVideoConfig();
  const params = narrowParams<Params>(props.params);
  const staged = params.__astridAssets ?? {};
  const url = (key: string): string => {
    const p = staged[key];
    return p ? staticFile(p) : staticFile(`astrid-effects/ending-carousel/${key}`);
  };
  const D = Math.max(1, durationInFrames);
  const toLine = interpolate(frame, [0.45 * D, 0.7 * D], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const reorder = interpolate(frame, [0.7 * D, 0.92 * D], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const zoom = interpolate(frame, [0.92 * D, D], [1, 0.94], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const trackOn = interpolate(frame, [0.45 * D, 0.55 * D], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  const orderPosOf = (i: number): number => {
    const to = FINAL_ORDER.indexOf(i);
    return interpolate(reorder, [0, 1], [i, to]);
  };

  // Shuffle: cycle cards 0..5 big in the center, then the winner glows
  // and flies to grid slot 0.
  const showShuffle = frame < 0.3 * D;
  const shuffleIdx = Math.min(
    SHUFFLE_LAST,
    Math.floor(frame / ((0.2 * D) / 6)),
  );
  const place = interpolate(frame, [0.2 * D, 0.3 * D], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const g0 = gridOf(0);
  const shuffleW = 620;
  const shuffleX = interpolate(place, [0, 1], [0, g0.x]);
  const shuffleY = interpolate(place, [0, 1], [0, g0.y]);
  const shuffleSize = interpolate(place, [0, 1], [shuffleW, 280]);

  return (
    <div style={{position: 'absolute', inset: 0, overflow: 'hidden'}}>
      <OffthreadVideo
        src={url('plate')}
        muted
        style={{position: 'absolute', inset: 0, width: '100%', height: '100%'}}
      />
      <div
        style={{
          position: 'absolute',
          left: 960,
          top: 560,
          transform: `translate(-50%, -50%) scale(${zoom})`,
        }}
      >
        <div
          style={{
            position: 'absolute',
            left: -880,
            top: 150,
            width: 1760 * trackOn,
            height: 6,
            backgroundColor: AMBER,
            boxShadow: `0 0 24px ${AMBER}`,
            opacity: trackOn,
          }}
        />
        {showShuffle && (
          <Img
            src={url(CARD_KEYS[shuffleIdx])}
            style={{
              position: 'absolute',
              left: shuffleX - shuffleSize / 2,
              top: shuffleY - (shuffleSize / 420) * 236 / 2,
              height: (shuffleSize / 420) * 236,
              border: place > 0 ? `5px solid ${AMBER}` : '2px solid #3a2408',
              boxShadow: place > 0 ? `0 0 50px ${AMBER}` : 'none',
            }}
          />
        )}
        {CARD_KEYS.map((key, i) => {
          // Winner lands as grid slot 0; the rest pop in staggered.
          const t0 = i === 0 ? 0.28 * D : (0.3 + ((i - 1) / 7) * 0.12) * D;
          const enter = interpolate(frame, [t0, t0 + 0.05 * D], [0, 1], {
            extrapolateLeft: 'clamp',
            extrapolateRight: 'clamp',
          });
          if (enter <= 0) return null;
          const g = gridOf(i);
          const op = orderPosOf(i);
          const tx = -805 + op * 230;
          const ty = 150;
          const liftLine = Math.sin(Math.PI * toLine) * 90;
          const liftRe = Math.sin(Math.PI * reorder) * 70;
          const x = interpolate(toLine, [0, 1], [g.x, tx]);
          const y = interpolate(toLine, [0, 1], [g.y, ty]) - liftLine - liftRe;
          const w = interpolate(toLine, [0, 1], [280, 200]);
          const h = (w / 420) * 236;
          return (
            <Img
              key={key}
              src={url(key)}
              style={{
                position: 'absolute',
                left: x - (w * enter) / 2,
                top: y - (h * enter) / 2,
                width: w * enter,
                height: h * enter,
                border: '2px solid #3a2408',
                opacity: enter,
              }}
            />
          );
        })}
      </div>
    </div>
  );
}

import type {CSSProperties, ReactElement} from 'react';
import {useCallback} from 'react';
import {
  HtmlInCanvas,
  type HtmlInCanvasOnPaint,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from 'remotion';

type EffectParams = {
  content?: string;
  subtitle?: string;
  width?: number;
  height?: number;
  background?: string;
  foreground?: string;
  accent?: string;
  postProcess?: 'none' | 'soft-blur' | 'glow' | 'vignette';
};

const cardShell: CSSProperties = {
  boxSizing: 'border-box',
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'space-between',
  height: '100%',
  width: '100%',
  padding: 40,
  fontFamily: 'Inter, system-ui, sans-serif',
};

const CanvasCard = ({params}: {params: EffectParams}): ReactElement => {
  const accent = params.accent ?? '#7dd3fc';
  return (
    <div
      style={{
        ...cardShell,
        background: params.background ?? 'rgba(15, 23, 42, 0.92)',
        color: params.foreground ?? '#ffffff',
        border: `1px solid ${accent}`,
        boxShadow: `0 24px 80px rgba(0, 0, 0, 0.35), inset 0 1px 0 ${accent}`,
      }}
    >
      <div
        style={{
          fontSize: 54,
          fontWeight: 750,
          lineHeight: 1,
        }}
      >
        {params.content ?? 'HTML in Canvas'}
      </div>
      <div
        style={{
          color: 'rgba(255, 255, 255, 0.78)',
          fontSize: 22,
          lineHeight: 1.3,
        }}
      >
        {params.subtitle ?? 'DOM layout, captured and post-processed as a canvas texture.'}
      </div>
    </div>
  );
};

import {
  type ElementComponentProps,
  narrowParams,
} from '../../../../../rendering/shared/element_contracts';

export default function HtmlCanvasEffect(
  props: ElementComponentProps,
): ReactElement {
  const frame = useCurrentFrame();
  const {width: compositionWidth, height: compositionHeight} = useVideoConfig();
  const params = narrowParams<EffectParams>(props.params);
  const width = params.width ?? Math.min(900, compositionWidth);
  const height = params.height ?? Math.min(520, compositionHeight);
  const opacity = interpolate(frame, [0, 12], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  const onPaint: HtmlInCanvasOnPaint = useCallback(
    ({canvas, element, elementImage}) => {
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        throw new Error('Failed to acquire 2D canvas context');
      }
      ctx.reset();
      const mode = params.postProcess ?? 'glow';
      if (mode === 'soft-blur') {
        ctx.filter = 'blur(1.2px) saturate(1.08)';
      } else if (mode === 'glow') {
        ctx.shadowColor = params.accent ?? '#7dd3fc';
        ctx.shadowBlur = 28;
      }
      const transform = ctx.drawElementImage(elementImage, 0, 0);
      if (mode === 'vignette') {
        const gradient = ctx.createRadialGradient(
          canvas.width / 2,
          canvas.height / 2,
          canvas.width * 0.15,
          canvas.width / 2,
          canvas.height / 2,
          canvas.width * 0.7,
        );
        gradient.addColorStop(0, 'rgba(255, 255, 255, 0)');
        gradient.addColorStop(1, 'rgba(0, 0, 0, 0.42)');
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, canvas.width, canvas.height);
      }
      element.style.transform = transform.toString();
    },
    [params.accent, params.postProcess],
  );

  return (
    <div
      style={{
        alignItems: 'center',
        display: 'flex',
        height: '100%',
        justifyContent: 'center',
        opacity,
        pointerEvents: 'none',
        position: 'relative',
        width: '100%',
      }}
    >
      <div
        style={{
          height,
          position: 'absolute',
          width,
        }}
      >
        <CanvasCard params={params} />
      </div>
      <div
        style={{
          height,
          position: 'relative',
          width,
        }}
      >
        <HtmlInCanvas width={width} height={height} onPaint={onPaint}>
          <CanvasCard params={params} />
        </HtmlInCanvas>
      </div>
    </div>
  );
}

