          </mask>
        </defs>
        <path
          d={noodlePath}
          pathLength={1}
          mask="url(#assetPlatformCutout)"
          fill="none"
          stroke="url(#assetNoodleGradient)"
          strokeWidth="12"
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeDasharray={`${dashArray} ${1 - dashArray}`}
          strokeDashoffset={dashOffset}
          filter="url(#assetSoftGlow)"
          opacity="0.88"
        />
        {seconds > 5.8 && (
          <path
            d={noodlePath}
            pathLength={1}
