      "type": "string",
      "minLength": 1,
      "pattern": "^[^\\u0000]+$"
    },
    "nullable_contained_source_path": {
      "oneOf": [
        {"$ref": "#/$defs/contained_source_path"},
        {"type": "null"}
      ]
    },
    "nonnegative_seconds": {
      "type": "number",
