        "height": {"type": "number", "exclusiveMinimum": 0}
      },
      "additionalProperties": false
    },
    "availability": {
      "type": "object",
      "required": ["available", "unavailable_reason"],
      "properties": {
        "available": {"type": "boolean"},
        "unavailable_reason": {
          "oneOf": [
            {"type": "string", "minLength": 1},
            {"type": "null"}
          ]
        }
      },
      "allOf": [
        {
          "if": {"properties": {"available": {"const": true}}, "required": ["available"]},
          "then": {"properties": {"unavailable_reason": {"type": "null"}}},
          "else": {"properties": {"unavailable_reason": {"type": "string", "minLength": 1}}}
        }
      ],
      "additionalProperties": false
    },
    "optional_entrypoint": {
      "type": "object",
      "required": ["path", "reason"],
      "properties": {
        "path": {"$ref": "#/$defs/nullable_artifact_path"},
        "reason": {
          "oneOf": [
            {"type": "string", "minLength": 1},
            {"type": "null"}
          ]
        }
      },
      "oneOf": [
        {
          "properties": {
            "path": {"$ref": "#/$defs/artifact_path"},
            "reason": {"type": "null"}
          }
        },
        {
          "properties": {
            "path": {"type": "null"},
            "reason": {"type": "string", "minLength": 1}
          }
        }
      ],
      "additionalProperties": false
    },
    "universal_output": {
      "type": "object",
      "required": ["path"],
      "properties": {
        "name": {"type": "string", "minLength": 1},
        "path": {"$ref": "#/$defs/artifact_path"},
        "type": {"type": "string", "enum": ["file", "directory"]},
        "content_hash": {"$ref": "#/$defs/content_hash"},
        "bytes": {"type": "integer", "minimum": 0},
        "sha256": {"$ref": "#/$defs/raw_sha256"},
        "optional": {"type": "boolean"},
        "missing": {"type": "boolean"},
        "label": {"type": "string", "minLength": 1},
        "note": {"type": "string", "minLength": 1},
        "artifact_type": {
          "oneOf": [
            {"type": "string", "minLength": 1},
            {"type": "null"}
          ]
        },
        "entries": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["path", "bytes", "content_hash"],
            "properties": {
              "path": {"$ref": "#/$defs/artifact_path"},
              "bytes": {"type": "integer", "minimum": 0},
              "content_hash": {"$ref": "#/$defs/content_hash"}
            },
            "additionalProperties": false
          }
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {"missing": {"const": true}},
            "required": ["missing"]
          },
          "then": {
            "properties": {"optional": {"const": true}},
            "required": ["optional"]
          },
          "else": {"required": ["type", "content_hash", "bytes"]}
        }
      ],
      "additionalProperties": false
    }
  }
}

