  "$id": "https://astrid.dev/schemas/timeline-visualize/v1/manifest.json",
  "title": "Astrid timeline visualization manifest v1",
  "description": "Universal result manifest plus immutable visualization-run identity and entrypoints.",
  "type": "object",
  "required": [
    "schema_version",
    "kind",
    "inputs",
    "outputs",
    "created",
    "warnings",
    "run_id",
    "run_root",
    "snapshots",
    "compositor",
    "scope",
    "layouts",
    "page_count",
    "reading_order",
    "entrypoints",
    "optional_formats",
    "companions"
  ],
  "properties": {
    "schema_version": {"type": "integer", "const": 1},
    "kind": {"type": "string", "const": "timeline_visualize"},
    "inputs": {
      "type": "object",
      "required": ["source_mode", "resolved_project", "resolved_timelines", "from_view", "focus", "scope", "layout", "formats"],
      "properties": {
        "source_mode": {
          "type": "string",
          "enum": ["kernel", "frozen"],
          "description": "Resolved authority boundary: runtime-owned timeline document or frozen view."
        },
        "resolved_project": {
          "type": "object",
          "required": ["slug"],
          "properties": {
            "slug": {"type": "string", "minLength": 1},
            "id": {"type": "string", "minLength": 1}
          },
          "additionalProperties": false
        },
        "resolved_timelines": {
          "type": "array",
          "items": {"$ref": "_defs.json#/$defs/timeline_identity"},
          "minItems": 1,
          "uniqueItems": true,
          "description": "Exact frozen-v1 identities. Their ULIDs remain uppercase for schema and frozen-pack compatibility. For comparison with public kernel CLI/SDK DTOs, use canonical_timeline_identities."
        },
        "canonical_timeline_identities": {
          "type": "array",
          "items": {"$ref": "_defs.json#/$defs/canonical_timeline_identity"},
          "minItems": 1,
          "uniqueItems": true,
          "description": "Optional additive identity projection whose lowercase ULID spelling matches public kernel timeline create/list/show DTOs. Existing frozen v1 manifests may omit it."
        },
        "from_view": {
          "oneOf": [
            {"type": "string", "minLength": 1},
            {"type": "null"}
          ]
        },
        "focus": {
          "oneOf": [
            {"$ref": "_defs.json#/$defs/focus_ref"},
            {"type": "null"}
          ]
        },
        "scope": {"$ref": "_defs.json#/$defs/scope/properties/kind"},
        "layout": {"type": "string", "enum": ["time-scaled", "linear", "both"]},
        "formats": {
          "type": "array",
          "items": {"type": "string", "enum": ["png", "svg", "md"]},
          "uniqueItems": true
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {"focus": {"not": {"type": "null"}}},
            "required": ["focus"]
          },
          "then": {"properties": {"from_view": {"type": "string", "minLength": 1}}}
        }
      ],
      "additionalProperties": false
    },
    "outputs": {
      "type": "array",
      "items": {"$ref": "_defs.json#/$defs/universal_output"},
      "minItems": 1
    },
    "created": {
      "type": "string",
      "format": "date-time",
      "description": "Operational wall-clock metadata; excluded from SNS identity."
    },
    "warnings": {
      "type": "array",
      "items": {"type": "string"}
    },
    "run_id": {"$ref": "_defs.json#/$defs/ulid"},
    "run_root": {"type": "string", "minLength": 1},
    "snapshots": {"$ref": "_defs.json#/$defs/snapshot_set"},
    "compositor": {
      "type": "object",
      "required": ["package", "version", "source_snapshot_path", "registry_default_fingerprint"],
      "properties": {
        "package": {"type": "string", "minLength": 1},
        "version": {"type": "string", "minLength": 1},
        "source_snapshot_path": {"type": "string", "minLength": 1},
        "registry_default_fingerprint": {"$ref": "_defs.json#/$defs/raw_sha256"}
      },
      "additionalProperties": false
    },
    "scope": {"$ref": "_defs.json#/$defs/scope"},
    "layouts": {
      "type": "array",
      "items": {"$ref": "_defs.json#/$defs/layout_kind"},
      "minItems": 1,
      "uniqueItems": true
    },
    "page_count": {"type": "integer", "minimum": 0},
    "reading_order": {
      "type": "array",
      "items": {"$ref": "_defs.json#/$defs/page_id"},
      "uniqueItems": true
    },
    "entrypoints": {
      "type": "object",
      "required": [
        "manifest",
        "ground_truth",
        "view_map",
        "action_index",
        "asset_index",
        "transcript_index",
        "diagnostics",
        "reading_guide",
        "structure",
        "primary_image"
      ],
      "properties": {
        "manifest": {"$ref": "_defs.json#/$defs/artifact_path"},
        "ground_truth": {"$ref": "_defs.json#/$defs/artifact_path"},
        "view_map": {"$ref": "_defs.json#/$defs/artifact_path"},
        "action_index": {"$ref": "_defs.json#/$defs/artifact_path"},
        "asset_index": {"$ref": "_defs.json#/$defs/artifact_path"},
        "transcript_index": {"$ref": "_defs.json#/$defs/artifact_path"},
        "diagnostics": {"$ref": "_defs.json#/$defs/artifact_path"},
        "reading_guide": {"$ref": "_defs.json#/$defs/artifact_path"},
        "structure": {"$ref": "_defs.json#/$defs/nullable_artifact_path"},
        "primary_image": {"$ref": "_defs.json#/$defs/nullable_artifact_path"}
      },
      "additionalProperties": false
    },
    "optional_formats": {
      "type": "object",
      "required": ["png", "svg", "structure"],
      "properties": {
        "png": {"$ref": "_defs.json#/$defs/optional_entrypoint"},
        "svg": {"$ref": "_defs.json#/$defs/optional_entrypoint"},
        "structure": {"$ref": "_defs.json#/$defs/optional_entrypoint"}
      },
      "additionalProperties": false
    },
    "companions": {
      "type": "object",
      "required": ["reading_guide", "structure"],
      "properties": {
        "reading_guide": {
          "type": "object",
          "required": ["path", "content_kind", "schema"],
          "properties": {
            "path": {"$ref": "_defs.json#/$defs/artifact_path"},
            "content_kind": {"type": "string", "const": "prose"},
            "schema": {"type": "null"}
          },
          "additionalProperties": false
        },
        "structure": {
          "type": "object",
          "required": ["path", "reason", "content_kind", "breadcrumb", "suggested_next_actions"],
          "properties": {
            "path": {"$ref": "_defs.json#/$defs/nullable_artifact_path"},
            "reason": {
              "oneOf": [
                {"type": "string", "minLength": 1},
                {"type": "null"}
              ]
            },
            "content_kind": {"type": "string", "const": "factual_markdown"},
            "breadcrumb": {
              "type": "array",
              "items": {"$ref": "_defs.json#/$defs/focus_ref"}
            },
            "suggested_next_actions": {
              "type": "array",
              "items": {
                "type": "object",
                "required": ["object_ref", "action"],
                "properties": {
                  "object_ref": {"$ref": "_defs.json#/$defs/qualified_ref"},
                  "action": {"type": "string", "minLength": 1}
                },
                "additionalProperties": false
              }
            }
          },
          "allOf": [
            {
              "if": {"properties": {"path": {"type": "null"}}, "required": ["path"]},
              "then": {"properties": {"reason": {"type": "string", "minLength": 1}}},
              "else": {"properties": {"reason": {"type": "null"}}}
            }
          ],
          "additionalProperties": false
        }
      },
      "additionalProperties": false
    }
  },
  "additionalProperties": false,
  "x-bundle-constraints": [
    "snapshots are ordered by timeline display ordinal and byte-identical across every artifact",
    "page_count equals view-map.json pages length",
    "reading_order equals view-map.json reading_order",
    "companion and entrypoint paths resolve inside run_root"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://astrid.dev/schemas/timeline-visualize/v1/metric-definitions.json",
  "title": "Astrid timeline visualization metric definitions v1",
  "description": "Versioned machine artifact defining every metric name ground-truth.json stores a value for: id, name, definition, formula/derivation (the duration.py/model.py function it mirrors), unit, and scope.",
  "type": "object",
  "required": [
    "schema_version",
    "kind",
    "compositor_version",
    "metrics"
  ],
  "properties": {
    "schema_version": {"type": "integer", "const": 1},
    "kind": {"type": "string", "const": "timeline_visualize_metric_definitions"},
    "compositor_version": {"type": "string", "minLength": 1},
    "metrics": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "type": "object",
        "required": ["id", "name", "definition", "formula", "derivation", "unit", "scope"],
        "properties": {
          "id": {
            "type": "string",
            "minLength": 1,
            "pattern": "^[a-z0-9_]+$"
          },
          "name": {"type": "string", "minLength": 1},
          "definition": {"type": "string", "minLength": 1},
          "formula": {"type": "string", "minLength": 1},
          "derivation": {"type": "string", "minLength": 1},
          "unit": {
            "type": "string",
            "enum": ["frames", "seconds", "frames_per_second"]
          },
          "scope": {
            "type": "string",
            "enum": ["per-timeline", "per-scope"]
          }
        },
        "additionalProperties": false
      }
    }
  },
  "additionalProperties": false,
  "x-bundle-constraints": [
    "metric ids are unique and referenceable from ground-truth values",
    "every metric carries a formula and the duration.py/model.py function it derives from",
    "unit and scope come from the closed enums so machines can compare across packs"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://astrid.dev/schemas/timeline-visualize/v1/transcript-index.json",
  "title": "Astrid timeline visualization transcript index v1",
  "description": "Empty arrays are valid in milestone one; milestone two populates the declared TS/SP records without changing v1 shape.",
  "type": "object",
  "required": ["schema_version", "snapshots", "sources", "speech_occurrences"],
  "properties": {
    "schema_version": {"type": "integer", "const": 1},
    "snapshots": {"$ref": "_defs.json#/$defs/snapshot_set"},
    "sources": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "object",
        "required": [
