  Object.freeze({ id: 'maple-acceptance-position-2', track: 'V1', at: 2, from: 55, to: 75, rate: 1 }),
  Object.freeze({ id: 'maple-acceptance-position-22', track: 'V1', at: 22, from: 20, to: 30, rate: 2 }),
]);
