            "type": "object",
            "properties": {
              "accepted": {"type": "integer"},
              "target": {"type": "integer"},
              "shortfall": {"type": "integer"}
            }
          }
        },
        "filter_pass_rates": {
          "type": "object",
          "additionalProperties": {
            "type": "object",
            "properties": {
              "stage_id": {"type": "string"},
              "pass_rate": {"type": "number", "minimum": 0, "maximum": 1}
            }
          }
        },
        "total_duration_s": {"type": "number", "minimum": 0},
        "estimated_cost_usd": {"type": "number", "minimum": 0}
      }
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://astrid.builtin-training/schemas/review-decision.schema.json",
  "title": "ReviewDecision",
  "description": "A submitted review decision for one item. Distinct from transient /save diff payloads. This is the final decision shape written on /submit.",
  "type": "object",
  "required": ["item_id", "decision", "reviewed_at"],
  "additionalProperties": false,
  "properties": {
    "item_id": {
      "type": "string",
      "description": "The ReviewItem.item_id this decision applies to."
    },
    "decision": {
      "type": "string",
      "enum": ["accept", "reject", "pending"],
      "description": "Accept, reject, or leave pending."
    },
    "reject_reason": {
      "description": "Reason for rejection. Null if accepted or pending.",
      "oneOf": [
        {"type": "null"},
        {
          "type": "string",
          "enum": ["watermark", "wrong_scene", "wrong_character", "bad_motion", "low_quality", "wrong_content", "rights_concern", "other"]
        }
      ]
    },
    "edited_caption": {
      "description": "User-edited caption text. Null if unchanged.",
      "oneOf": [
        {"type": "null"},
        {"type": "string"}
      ]
    },
    "reviewed_at": {
      "type": "string",
      "format": "date-time",
      "description": "ISO 8601 timestamp when this item was reviewed."
    },
    "reviewer_id": {
      "type": "string",
      "description": "Identifier for the reviewer. Optional."
    },
    "state_version": {
      "type": "integer",
      "minimum": 0,
      "description": "The run-state version at the time this decision was made. Used for stale-save detection."
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://astrid.builtin-training/schemas/review-item.schema.json",
  "title": "ReviewItem",
  "description": "A candidate item with full metadata, served to the human review UI. Extends CandidateItem with caption, filter results, and paired-media placeholders.",
  "type": "object",
  "required": [
    "item_id",
    "source_type",
    "source_id",
    "source_url",
    "content_hash",
    "acquired_at",
    "media_type",
    "media_path"
  ],
  "additionalProperties": false,
  "properties": {
    "item_id": {
      "type": "string",
      "description": "Unique identifier for this review item. Typically '{video_id}-s{scene_index:02d}'."
    },
    "source_type": {
      "type": "string",
      "enum": ["youtube", "local_folder", "stock_api", "generated", "image", "audio", "paired"]
    },
    "source_id": {
      "type": "string",
      "description": "Stable external identifier for the source."
    },
    "source_url": {
      "type": "string",
      "description": "URL or file:// URI."
    },
    "source_metadata": {
      "type": "object",
      "additionalProperties": true
    },
    "rights": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "license": {"type": "string"},
        "attribution": {"type": "string"},
        "restrictions": {"type": "array", "items": {"type": "string"}},
        "rights_status": {"type": "string", "enum": ["verified", "unknown", "needs_review", "restricted"]}
      }
    },
    "content_hash": {
      "type": "string",
      "pattern": "^[a-f0-9]{64}$"
    },
    "acquired_at": {
      "type": "string",
      "format": "date-time"
    },
    "downloaded_at": {
      "type": "string",
      "format": "date-time"
    },
    "derived_from": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "source_id": {"type": "string"},
        "source_type": {"type": "string"},
        "transformation": {"type": "string"}
      }
    },
    "media_path": {
      "type": "string",
      "description": "Local filesystem path to the media file."
    },
    "media_type": {
      "type": "string",
      "enum": ["video", "image", "audio", "paired"],
      "description": "Concrete media type."
    },
    "duration_s": {
      "type": "number",
      "minimum": 0
    },
    "clip_start_s": {
      "type": "number",
      "minimum": 0
    },
    "clip_end_s": {
      "type": "number",
      "minimum": 0
    },
    "scene_index": {
      "type": "integer",
      "minimum": 0
    },
    "bucket": {
      "type": "string",
      "description": "Bucket this item is assigned to."
    },
    "caption": {
      "type": "object",
      "description": "Caption produced by the caption provider.",
      "additionalProperties": false,
      "properties": {
        "text": {"type": "string", "description": "The caption string."},
        "schema_version": {"type": "integer"},
        "confidence": {"type": "number", "minimum": 0, "maximum": 1},
        "model": {"type": "string"},
        "raw_response": {"type": "object", "additionalProperties": true}
      }
    },
    "caption_file": {
      "type": "string",
      "description": "Path to the caption sidecar JSON file."
    },
    "caption_validation": {
      "type": "object",
      "description": "Validation metadata for the accepted caption sidecar and final caption text.",
      "additionalProperties": false,
      "required": ["valid", "failures"],
      "properties": {
        "valid": {"type": "boolean"},
        "schema_path": {"type": "string"},
        "validated_at": {"type": "string", "format": "date-time"},
        "failures": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["code", "message"],
            "additionalProperties": false,
            "properties": {
              "code": {"type": "string"},
              "message": {"type": "string"},
              "path": {"type": "string"}
            }
          }
        }
      }
    },
    "filter_results": {
      "type": "object",
      "description": "Results from filter stages applied to this item.",
      "additionalProperties": {
        "type": "object",
        "properties": {
          "passed": {"type": "boolean"},
          "reason": {"type": "string"},
          "score": {"type": "number"}
        }
      }
    },
    "judge_result": {
      "type": "object",
      "description": "Raw judge/semantic-filter output for this item.",
      "additionalProperties": true
    },
    "pair_id": {
      "type": "string",
      "description": "Placeholder for future paired-media workflows. Identifies a related pair."
    },
    "pair_role": {
      "type": "string",
      "enum": ["target", "reference", "distractor"],
      "description": "Placeholder for future paired-media workflows. Role within a pair."
    },
    "review_status": {
      "type": "string",
      "enum": ["pending", "accepted", "rejected"],
      "default": "pending",
      "description": "Current review status."
    },
    "review_sampled": {
      "type": "object",
      "description": "Deterministic review sampling metadata. Unsampled items remain present and pending unless explicitly reviewed.",
      "additionalProperties": false,
      "required": ["sampled", "mode", "sample_count"],
      "properties": {
        "sampled": {"type": "boolean"},
        "mode": {"type": "string", "enum": ["all", "random_sample", "top_n"]},
        "sample_count": {"type": "integer", "minimum": 0},
        "rank": {"type": "integer", "minimum": 1}
      }
    },
    "review_decision": {
      "$ref": "review-decision.schema.json",
      "description": "The review decision for this item, if decided."
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://astrid.builtin-training/schemas/run-state.schema.json",
  "title": "RunState",
  "description": "Canonical run state for training.dataset_build. Includes ownership/version fields for stale-save detection.",
  "type": "object",
  "required": ["run_id", "writer_id", "state_version", "created_at", "updated_at", "status"],
  "additionalProperties": false,
  "properties": {
    "run_id": {
      "type": "string",
      "description": "UUID or content-hash identifier for this run."
    },
    "writer_id": {
      "type": "string",
      "description": "Owner/agent identifier. Used to detect cross-agent state conflicts."
    },
    "state_version": {
      "type": "integer",
      "minimum": 0,
      "description": "Monotonically increasing version. Incremented on every state write. Clients include base_state_version in save payloads for stale-save detection."
    },
    "writer_epoch": {
      "type": "string",
      "description": "Optional epoch or timestamp for cross-agent coordination. Allows agents to detect if another writer has taken ownership."
    },
    "created_at": {
      "type": "string",
      "format": "date-time",
      "description": "ISO 8601 timestamp when this run was created."
    },
    "updated_at": {
      "type": "string",
      "format": "date-time",
      "description": "ISO 8601 timestamp when this state was last modified."
    },
    "status": {
      "type": "string",
      "enum": ["initializing", "acquiring", "filtering", "preview_ready", "captioning", "reviewing", "finalized", "failed"],
      "description": "Current phase of the dataset build pipeline."
    },
    "config_hash": {
      "type": "string",
      "description": "SHA-256 of the config used for this run. Allows detection of config changes between resumes."
    },
    "schema_version_source": {
      "type": "string",
      "description": "Package-local parser provenance for configs that omitted schema_version.",
      "enum": ["deprecated_inferred_v1"]
    },
    "buckets": {
      "type": "object",
      "description": "Per-bucket state. Keyed by bucket name.",
      "additionalProperties": {
        "type": "object",
        "required": ["target_count", "accepted", "rejected", "pending"],
        "additionalProperties": false,
        "properties": {
          "target_count": {"type": "integer", "minimum": 0},
          "accepted": {"type": "integer", "minimum": 0},
          "rejected": {"type": "integer", "minimum": 0},
          "pending": {"type": "integer", "minimum": 0},
          "item_ids": {
            "type": "array",
            "items": {"type": "string"},
            "description": "Item IDs assigned to this bucket."
          }
        }
      }
    },
    "processed_source_ids": {
      "type": "array",
      "items": {"type": "string"},
      "description": "Source IDs that have been fully processed (acquired + extracted). Used for resume to avoid re-downloading."
    },
    "acquisition_results": {
      "type": "array",
      "description": "Per-round source acquisition metadata for quality reporting.",
      "items": {
        "type": "object",
        "additionalProperties": true,
        "properties": {
          "provider": {"type": "string"},
          "round_index": {"type": "integer", "minimum": 0},
          "limit_hint": {"type": ["integer", "null"]},
          "considered": {"type": "integer", "minimum": 0},
          "yielded": {"type": "integer", "minimum": 0},
          "skipped_processed": {"type": "integer", "minimum": 0},
          "skipped_excluded": {"type": "integer", "minimum": 0},
          "skipped_duplicate_media": {"type": "integer", "minimum": 0},
          "no_new_candidates": {"type": "boolean"},
          "reason": {"type": "string"}
        }
      }
    },
    "review_decisions": {
      "type": "object",
      "description": "Review decisions keyed by item_id. Only items with an explicit accept/reject decision appear here.",
      "additionalProperties": {
        "$ref": "review-decision.schema.json"
      }
    },
    "filter_stats": {
      "type": "object",
      "description": "Aggregated filter statistics across all stages.",
      "additionalProperties": {
        "$ref": "filter-stats.schema.json"
      }
    },
    "caption_validation_failures": {
      "type": "array",
      "description": "Caption validation failures collected before manifest export.",
      "items": {
        "type": "object",
        "required": ["item_id", "code", "message"],
        "additionalProperties": false,
        "properties": {
          "item_id": {"type": "string"},
          "code": {"type": "string"},
          "message": {"type": "string"},
          "path": {"type": "string"}
        }
      }
    },
    "quality_report": {
      "type": "string",
      "description": "Path to quality_report.json when generated for this run."
    },
    "top_up_rounds": {
      "type": "integer",
      "minimum": 0,
      "default": 0,
      "description": "Number of top-up rounds executed so far."
    },
    "submitted": {
      "type": "boolean",
      "default": false,
      "description": "Whether the final review /submit has been received."
    },
    "completed_at": {
      "type": "string",
      "format": "date-time",
      "description": "ISO 8601 timestamp when the run was completed or finalized."
    },
    "error": {
      "type": "object",
      "description": "Error information if status is 'failed'.",
      "properties": {
        "message": {"type": "string"},
        "stage": {"type": "string"},
        "timestamp": {"type": "string", "format": "date-time"}
      }
    }
  }
}

files.astrid/packs/training/actions/training_r:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://astrid.builtin-training/schemas/training-run-config.schema.json",
  "title": "Training Run Config",
  "description": "Configuration for training.training_run. Schema version 1, ai-toolkit-ltx trainer, RunPod compute backend.",
  "type": "object",
  "required": ["schema_version", "trainer_id", "manifest_path", "compute", "base_model", "lora_config", "output"],
  "additionalProperties": false,
  "properties": {
    "schema_version": {
      "type": "integer",
      "const": 1
    },
    "trainer_id": {
      "type": "string",
      "enum": ["ai-toolkit-ltx"],
      "description": "Trainer adapter id."
    },
    "manifest_path": {
      "type": "string",
      "description": "Path to the canonical or ai-toolkit adapter manifest."
    },
    "vocabulary_path": {
      "type": "string",
      "description": "Path to vocabulary YAML for caption templates."
    },
    "compute": {
      "type": "object",
      "required": ["backend", "max_gpu_hours", "max_runpod_spend_usd"],
      "additionalProperties": false,
      "properties": {
        "backend": {
          "type": "string",
          "const": "runpod"
        },
        "gpu_type": {
          "type": "string",
          "default": "NVIDIA RTX 6000 Ada Generation",
          "description": "GPU type to provision."
        },
        "container_disk_gb": {
          "type": "integer",
          "minimum": 10,
          "default": 200
        },
        "max_runtime_seconds": {
          "type": "integer",
          "minimum": 0,
          "default": 43200,
          "description": "Maximum pod runtime in seconds (12h default)."
        },
        "max_gpu_hours": {
          "type": "number",
          "minimum": 0,
          "description": "Hard cap on GPU hours for this run."
        },
        "max_runpod_spend_usd": {
          "type": "number",
          "minimum": 0,
          "description": "Hard cap on estimated RunPod spend for this run."
        },
        "require_spend_confirmation": {
          "type": "boolean",
          "default": true,
          "description": "Headless runs must pre-confirm spend via config or CLI state."
        },
        "storage_name": {
          "type": "string",
          "description": "RunPod network storage volume name."
        },
        "storage_required": {
          "type": "boolean",
          "default": false,
          "description": "When true, training config validation requires storage_name and the RunPod backend passes --require-storage so the executor verifies the volume exists before provisioning."
        },
        "name_prefix": {
          "type": "string",
          "description": "RunPod pod name prefix."
        },
        "datacenter_id": {
          "type": "string",
          "description": "Optional RunPod datacenter id."
        },
        "image": {
          "type": "string",
          "default": "ostris/aitoolkit:latest",
          "description": "Docker image for the training pod."
        },
        "ports": {
          "type": "string",
          "default": "8675/http,22/tcp",
          "description": "Port mapping string for RunPod."
        },
        "upload_mode": {
          "type": "string",
          "default": "sftp_walk",
          "description": "Remote staging upload mode passed to the RunPod remote execution backend."
        },
        "excludes": {
          "description": "Files or directories excluded while staging local inputs to the pod.",
          "oneOf": [
            {
              "type": "string"
            },
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          ]
        },
        "ssh_key": {
          "type": "string",
          "description": "Optional SSH private key path used for artifact pulls."
        },
        "stage_timeout_seconds": {
          "type": "integer",
          "minimum": 1,
          "description": "Timeout for staging inputs on the remote backend."
        },
        "training_timeout_seconds": {
          "type": "integer",
          "minimum": 1,
          "description": "Timeout for the remote training command."
        },
        "review_timeout_seconds": {
          "type": "integer",
          "minimum": 1,
          "description": "Timeout for remote sample generation and review artifact pulls."
        }
      }
    },
    "secrets": {
      "type": "object",
      "description": "Secret requirements declared as environment variable names. Values are read from the process environment during live preflight and are never stored in config state.",
      "required": ["required_env"],
      "additionalProperties": false,
      "properties": {
        "required_env": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          },
          "uniqueItems": true,
          "default": []
        }
      }
    },
    "base_model": {
      "type": "string",
      "description": "Base model identifier for training.",
      "default": "Lightricks/LTX-2.3/ltx-2.3-22b-dev.safetensors"
    },
    "lora_config": {
      "type": "object",
      "description": "LoRA-specific hyperparameters.",
      "additionalProperties": false,
      "properties": {
        "lora_id": {
          "type": "string",
          "description": "Identifier for this LoRA (used in output paths)."
        },
        "trigger_word": {
          "type": "string",
          "description": "Training trigger word or phrase to inject into captions and prompts."
        },
        "prompt_text": {
          "type": "string",
          "description": "Generic prompt text used by review and sample generation."
        },
        "rank": {
          "type": "integer",
          "minimum": 1,
          "default": 16
        },
        "alpha": {
          "type": "number",
          "minimum": 0,
          "default": 16
        },
        "steps": {
          "type": "integer",
          "minimum": 1,
          "default": 2000
        },
        "learning_rate": {
          "type": "number",
          "minimum": 0,
          "default": 0.0001
        },
        "seed": {
          "type": "integer",
          "default": 42
        },
        "width": {
          "type": "integer",
          "minimum": 1,
          "description": "Sample and training frame width."
        },
        "height": {
          "type": "integer",
          "minimum": 1,
          "description": "Sample and training frame height."
        },
        "num_frames": {
          "type": "integer",
          "minimum": 1,
          "description": "Frames per training/sample clip."
        },
        "fps": {
          "type": "integer",
          "minimum": 1,
          "description": "Frames per second for training/sample clips."
        },
        "batch_size": {
          "type": "integer",
          "minimum": 1,
          "description": "Trainer batch size."
        },
        "gradient_accumulation_steps": {
          "type": "integer",
          "minimum": 1,
          "description": "Gradient accumulation steps."
        },
        "save_every": {
          "type": "integer",
          "minimum": 1,
          "description": "Checkpoint save interval in training steps."
        },
        "sample_every": {
          "type": "integer",
          "minimum": 1,
          "description": "Sample generation interval in training steps."
        }
      }
    },
    "checkpoint": {
      "type": "object",
      "description": "Checkpoint review configuration.",
      "additionalProperties": false,
      "properties": {
        "enabled": {"type": "boolean", "default": true},
        "sample_prompts": {
          "type": "array",
          "items": {"type": "string"},
          "description": "Prompts used to generate sample outputs at each checkpoint."
        },
        "review_labels": {
          "type": "array",
          "items": {"type": "string"},
          "description": "Labels shown during checkpoint review."
        }
      }
    },
    "output": {
      "type": "object",
      "required": ["run_dir"],
      "additionalProperties": false,
      "properties": {
        "run_dir": {
          "type": "string",
          "description": "Output directory for this training run."
        },
        "remote_root": {
          "type": "string",
          "description": "Remote workspace root used while staging training inputs."
        },
        "remote_output_dir": {
          "type": "string",
          "description": "Remote directory where ai-toolkit writes checkpoints and samples."
        }
      }
    },
    "extensions": {
      "type": "object",
      "description": "Reserved extension object.",
      "additionalProperties": true
    }
  }
}

