schema_version: 3
id: understanding
name: Astrid Understanding
version: 1.0.0
status: active
domain: media
stability: stable
support: core
visibility: visible
permissions:
  - id: subprocess
    reason: Runs audio, visual, video, and scene-understanding actions in isolated subprocesses.
  - id: project_files
    reason: Reads audio, video, image, scene, and triage files and writes declared analysis artifacts.
  - id: network
    reason: Sends media to the declared OpenAI and Gemini understanding APIs when a live action is requested.
  - id: environment
    reason: Reads OPENAI_API_KEY or GEMINI_API_KEY and an optional explicitly supplied environment file.
description: LLM-based audio, image, and video understanding — caption, query, and structured extraction over media.
keywords:
  - understanding
  - caption
  - vision
  - audio
  - video
  - transcribe-scene
  - llm
  - structured-output
capabilities:
  - understand_media
  - understand_audio
  - understand_image
  - understand_video
  - describe_scene
agent:
  purpose: Choose this pack to inspect or describe media content — caption images/scenes, query audio or synchronized audio+video windows, or extract schema-constrained structured fields from a clip via an LLM.
  do_not_use_for: Do not use to edit, cut, or render video (use video_editing) or to generate new media (use generation; use vibecomfy only for raw ComfyUI workflow graphs).
  normal_entrypoints:
    - understanding.understand
    - understanding.audio_understand
    - understanding.visual_understand
    - understanding.video_understand
    - understanding.scene_describe
documentation:
  kind: skill
  path: docs/SKILL.md
actions:
  audio_understand:
    name: Audio Understand
    version: "1.0"
    short_description: Inspect audio clips or sampled windows with an audio-understanding LLM.
    description: Query an OpenAI audio-native model against source audio or extracted video-audio windows, preserving audition-reel, provenance, and result-manifest behavior.
    keywords: [audio, understand, llm, analyze, transcript, describe]
    invocation:
      kind: command
      command:
        argv: ["{python_exec}", -m, astrid.packs.understanding.actions.audio_understand.run, --out-dir, "{out}", --out, "{out}/analysis.json"]
        input_args:
          - {input: query, flag: --query, optional: true}
          - {input: audio, flag: --audio, optional: true, repeatable: true}
          - {input: video, flag: --video, optional: true}
          - {input: at, flag: --at, optional: true, repeatable: true}
          - {input: start, flag: --start, optional: true}
          - {input: end, flag: --end, optional: true}
          - {input: window_sec, flag: --window-sec, optional: true}
          - {input: chunk_sec, flag: --chunk-sec, optional: true}
          - {input: max_chunks, flag: --max-chunks, optional: true}
          - {input: max_clip_sec, flag: --max-clip-sec, optional: true}
          - {input: audition_reel, flag: --audition-reel, optional: true}
          - {input: reel_gap_sec, flag: --reel-gap-sec, optional: true}
          - {input: sample_rate, flag: --sample-rate, optional: true}
          - {input: mode, flag: --mode, optional: true}
          - {input: model, flag: --model, optional: true}
          - {input: compare_model, flag: --compare-model, optional: true, repeatable: true}
