files.remotion/node_modules/@banodoco/timeline:
#!/usr/bin/env -S npx --yes tsx
/**
 * Sprint 5 — generate `src/registry.generated.ts`.
 *
 * Discovery (directory-as-plugin pattern, mirrors tools/effects_catalog.py:139-155):
 *
 *   1. Reigh-side install: walk `node_modules/@banodoco/timeline-theme-*`
 *      (one or more theme packages installed as `file:` deps). For each
 *      package, read `theme.json` then enumerate
 *      `<pkg>/src/effects/<clipType>/component.tsx`.
 *
 *   2. Banodoco-side in-tree: walk `<workspace-root>/themes/<id>/effects/`.
 *      Used when the package is consumed from inside the banodoco-workspace
 *      directly — the build-time theme content lives here, not under
 *      node_modules. Detected when the workspace marker file
 *      (`<workspace-root>/themes/`) is present.
 *
 * The emitted file maps clipType → component import path. Reigh's
 * TimelineRenderer.tsx looks up clipType via this registry; the Banodoco
 * composition uses its own `effects.generated.ts` (codegenned by
 * gen_effect_registry.py) for its in-bundle rendering.
 *
 * Drift gate: pass `--check` to assert the regenerated file matches what's
 * on disk. Used by `scripts/ci-timeline-composition.sh`.
 */

import {readdirSync, readFileSync, statSync, writeFileSync, existsSync} from "node:fs";
import {dirname, join, relative, resolve} from "node:path";
import {fileURLToPath} from "node:url";

const __dirname_ = dirname(fileURLToPath(import.meta.url));
// scripts/ → package root one level up.
const PKG_DIR = resolve(__dirname_, "..");
const SRC_DIR = join(PKG_DIR, "typescript", "src");
const OUTPUT = join(SRC_DIR, "registry.generated.ts");

// Resolve workspace root by walking up from the package directory until
// we find a `themes/` directory (banodoco-workspace marker). If we don't
// find one we're being consumed from inside Reigh's node_modules — fall
// back to package-local discovery only.
function findWorkspaceRoot(start: string): string | null {
  let dir = start;
  for (let i = 0; i < 6; i += 1) {
    if (existsSync(join(dir, "themes")) && existsSync(join(dir, "tools"))) {
      return dir;
    }
    const parent = dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return null;
}

// Find any `node_modules/@banodoco/timeline-theme-*` packages from PKG_DIR
// upward. When run inside banodoco-workspace this returns the linked
// timeline-theme-2rp; when run inside reigh-app's install it returns each
// installed theme package.
function findInstalledThemePackages(start: string): string[] {
  const found: string[] = [];
  let dir = start;
  for (let i = 0; i < 8; i += 1) {
    const ns = join(dir, "node_modules", "@banodoco");
    if (existsSync(ns)) {
      try {
        for (const entry of readdirSync(ns)) {
          if (!entry.startsWith("timeline-theme-")) continue;
          const pkgPath = join(ns, entry);
          if (statSync(pkgPath).isDirectory()) {
            found.push(pkgPath);
          }
        }
      } catch {
        // ignore
      }
    }
    const parent = dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return found;
}

type RegistryEntry = {
  clipType: string;
  themeId: string;
  componentName: string;
  importSpecifier: string;
  // For provenance/debug
  source: string;
};

function componentName(clipType: string, themeId: string): string {
  const camel = clipType
    .split("-")
    .map((p) => p.charAt(0).toUpperCase() + p.slice(1))
    .join("");
  const themeCamel = themeId
    .replace(/[^a-z0-9]/gi, "_")
    .split("_")
    .filter(Boolean)
    .map((p) => p.charAt(0).toUpperCase() + p.slice(1))
    .join("");
  // Identifiers cannot start with a digit (theme ids like "2rp" do).
  // Prefix with `Theme_` to keep names valid JS identifiers.
  const safeTheme = /^[A-Za-z_]/.test(themeCamel) ? themeCamel : `Theme${themeCamel}`;
  return `${safeTheme}_${camel}`;
}

function scanPackageEffects(pkgDir: string): {themeId: string; effects: string[]} | null {
  const themeJsonPath = join(pkgDir, "theme.json");
  if (!existsSync(themeJsonPath)) return null;
  let themeJson: {id?: string};
  try {
    themeJson = JSON.parse(readFileSync(themeJsonPath, "utf8"));
  } catch {
    return null;
  }
  const themeId = themeJson.id;
  if (typeof themeId !== "string" || !themeId) return null;
  const effectsDir = join(pkgDir, "src", "effects");
  if (!existsSync(effectsDir)) return {themeId, effects: []};
  const effects: string[] = [];
  for (const entry of readdirSync(effectsDir)) {
    const componentPath = join(effectsDir, entry, "component.tsx");
    if (existsSync(componentPath)) effects.push(entry);
  }
  return {themeId, effects: effects.sort()};
}

function scanInTreeThemes(workspaceRoot: string): Array<{themeId: string; effects: string[]; root: string}> {
  const themesDir = join(workspaceRoot, "themes");
  if (!existsSync(themesDir)) return [];
  const out: Array<{themeId: string; effects: string[]; root: string}> = [];
  for (const entry of readdirSync(themesDir)) {
    const themeRoot = join(themesDir, entry);
    if (!statSync(themeRoot).isDirectory()) continue;
    const themeJsonPath = join(themeRoot, "theme.json");
    if (!existsSync(themeJsonPath)) continue;
    let themeJson: {id?: string};
    try {
      themeJson = JSON.parse(readFileSync(themeJsonPath, "utf8"));
    } catch {
      continue;
    }
    const themeId = themeJson.id ?? entry;
    const effectsDir = join(themeRoot, "effects");
    const effects: string[] = [];
    if (existsSync(effectsDir)) {
      for (const child of readdirSync(effectsDir)) {
        const cmp = join(effectsDir, child, "component.tsx");
        if (existsSync(cmp)) effects.push(child);
      }
    }
    out.push({themeId, effects: effects.sort(), root: themeRoot});
  }
  return out.sort((a, b) => a.themeId.localeCompare(b.themeId));
}

function buildEntries(): RegistryEntry[] {
  const entries: RegistryEntry[] = [];
  const installed = findInstalledThemePackages(PKG_DIR);
  for (const pkgDir of installed) {
    const scanned = scanPackageEffects(pkgDir);
    if (!scanned) continue;
    // Import from package name. Read the package.json `name`.
    let pkgName = "";
    try {
      const pj = JSON.parse(readFileSync(join(pkgDir, "package.json"), "utf8"));
      pkgName = pj.name ?? "";
    } catch {
      continue;
    }
    if (!pkgName) continue;
    for (const clipType of scanned.effects) {
      entries.push({
        clipType,
        themeId: scanned.themeId,
        componentName: componentName(clipType, scanned.themeId),
        importSpecifier: `${pkgName}/src/effects/${clipType}/component`,
        source: `installed:${pkgName}`,
      });
    }
  }
  // In-tree themes (banodoco-workspace consumption). These are NOT emitted
  // as registry entries when an installed package already covers the same
  // clipType — the installed package wins (mirrors theme-overrides logic in
  // effects_catalog.py:147-152).
  const seen = new Set(entries.map((e) => `${e.themeId}:${e.clipType}`));
  const wsRoot = findWorkspaceRoot(PKG_DIR);
  if (wsRoot) {
    const inTree = scanInTreeThemes(wsRoot);
    for (const t of inTree) {
      for (const clipType of t.effects) {
        const key = `${t.themeId}:${clipType}`;
        if (seen.has(key)) continue;
        const rel = relative(SRC_DIR, join(t.root, "effects", clipType, "component"));
        const importSpec = rel.startsWith(".") ? rel : `./${rel}`;
        entries.push({
          clipType,
          themeId: t.themeId,
          componentName: componentName(clipType, t.themeId),
          importSpecifier: importSpec,
          source: `in-tree:themes/${t.themeId}`,
        });
        seen.add(key);
      }
    }
  }
  // Stable sort: clipType then themeId.
  return entries.sort((a, b) => {
    if (a.clipType !== b.clipType) return a.clipType.localeCompare(b.clipType);
    return a.themeId.localeCompare(b.themeId);
  });
}

function dedupeByClipType(entries: RegistryEntry[]): RegistryEntry[] {
  // First-write-wins per clipType: if multiple themes claim the same
  // clipType, the first-encountered (alphabetic by theme) becomes the
  // registry entry. Reigh and Banodoco accept that the first installed
  // theme owns ambiguous clipTypes; downstream we surface the others as
  // aliases. Sprint 5 v1: just take the first.
  const seen = new Set<string>();
  return entries.filter((e) => {
    if (seen.has(e.clipType)) return false;
    seen.add(e.clipType);
    return true;
  });
}

function render(entries: RegistryEntry[]): string {
  const deduped = dedupeByClipType(entries);
  const imports = deduped.map(
    (e) => `import ${e.componentName} from '${e.importSpecifier}';`,
  );
  const tableEntries = deduped.map(
    (e) =>
      `  '${e.clipType}': {component: ${e.componentName}, themeId: '${e.themeId}', source: '${e.source}'},`,
  );
  const ids = deduped.map((e) => `'${e.clipType}'`).join(", ");
  const lines = [
    "// DO NOT EDIT — generated by packages/timeline-composition/scripts/gen-registry.ts.",
    "// Discovery walks node_modules/@banodoco/timeline-theme-* (Reigh-side) and",
    "// themes/<id>/effects/ (Banodoco-side). Drift gate: scripts/ci-timeline-composition.sh",
    "// runs gen-registry --check pre-test.",
    "",
    // Use `unknown` for the component type so we don't impose a specific",
    // EffectProps shape — theme components are typed against their own",
    // params, and the dispatch in TimelineRenderer / TimelineComposition",
    // narrows at the call site.",
    "/* eslint-disable @typescript-eslint/no-explicit-any */",
    ...imports,
    "",
    "export type ThemePackageRegistryEntry = {",
    "  component: any;",
    "  themeId: string;",
    "  source: string;",
    "};",
    "",
    `export const THEME_PACKAGE_CLIP_TYPES = [${ids}] as const;`,
    "export type ThemePackageClipType = typeof THEME_PACKAGE_CLIP_TYPES[number];",
    "",
    "export const THEME_PACKAGE_REGISTRY: Record<ThemePackageClipType, ThemePackageRegistryEntry> = {",
    ...tableEntries,
    "};",
    "",
  ];
  return lines.join("\n");
}

function main(): void {
  const checkOnly = process.argv.includes("--check");
  const entries = buildEntries();
  const next = render(entries);
  if (checkOnly) {
    const cur = existsSync(OUTPUT) ? readFileSync(OUTPUT, "utf8") : "";
    if (cur === next) {
      console.log("registry.generated.ts up-to-date");
      process.exit(0);
    }
    console.error("registry.generated.ts is stale. Run `npm run gen-registry`.");
    process.exit(1);
  }
  writeFileSync(OUTPUT, next, "utf8");
  console.log(`Wrote ${relative(PKG_DIR, OUTPUT)} (${entries.length} entr${entries.length === 1 ? "y" : "ies"} pre-dedupe).`);
}

main();

import type {FC} from 'react';
import {Audio, staticFile} from 'remotion';
import type {AssetRegistryEntry, TimelineClip, TrackDefinition} from './types';
import {
  getClipDurationInFrames,
  getSanitizedPlaybackRate,
  getSanitizedVolume,
} from './lib/duration';
import {computeMediaTrim} from './lib/trim';

type AudioTrackProps = {
  clip: TimelineClip;
  track: TrackDefinition;
  assetEntry?: AssetRegistryEntry;
  fps: number;
};

const toRenderableFileUrl = (file: string | undefined): string | null => {
  if (typeof file !== 'string' || file.trim().length === 0) {
    return null;
  }

  if (file.startsWith('http://') || file.startsWith('https://')) {
    return file;
  }

  return staticFile(file);
};

const toFiniteSeconds = (value: unknown): number => {
  if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) {
    return 0;
  }
  return value;
};

export const AudioTrack: FC<AudioTrackProps> = ({clip, track, assetEntry, fps}) => {
  const fileUrl = toRenderableFileUrl(assetEntry?.file);
  if (!fileUrl) {
    return null;
  }

  const baseVolume = track.muted
    ? 0
    : getSanitizedVolume(track.volume ?? 1) * getSanitizedVolume(clip.volume ?? 1);

  const params = (clip.params ?? {}) as Record<string, unknown>;
  const fadeInFrames = Math.round(toFiniteSeconds(params.fadeIn) * fps);
  const fadeOutFrames = Math.round(toFiniteSeconds(params.fadeOut) * fps);
  const durationFrames = getClipDurationInFrames(clip, fps);

  const volumeProp: number | ((frame: number) => number) =
    fadeInFrames > 0 || fadeOutFrames > 0
      ? (frame: number) => {
          let multiplier = 1;
          if (fadeInFrames > 0 && frame < fadeInFrames) {
            multiplier *= Math.max(0, frame / fadeInFrames);
          }
          if (fadeOutFrames > 0) {
            const fadeStart = durationFrames - fadeOutFrames;
            if (frame > fadeStart) {
              multiplier *= Math.max(
                0,
                (durationFrames - frame) / fadeOutFrames,
              );
            }
          }
          return baseVolume * multiplier;
        }
      : baseVolume;

  return (
    <Audio
      src={fileUrl}
      {...computeMediaTrim(clip, fps)}
      playbackRate={getSanitizedPlaybackRate(clip.speed)}
      volume={volumeProp}
    />
  );
};

// Sprint 5: physically moved here from tools/remotion/src/ThemeContext.tsx.
// The theme-api re-export now points at this in-package module.

import {createContext, useContext} from 'react';
import type {ReactNode} from 'react';

export type Theme = {
  id: string;
  visual: {
    color: {
      fg: string;
      bg: string;
      accent: string;
    };
    type: {
      families: {
        heading: string;
        body: string;
        mono?: string;
      };
      size: {
        base: number;
        small: number;
        large: number;
      };
      weight: {
        normal: number;
        bold: number;
      };
      lineHeight: number;
    };
    motion: {
      fadeMs: number;
    };
    canvas: {
      width: number;
      height: number;
      fps: number;
    };
  };
};

export type RuntimeTheme = Theme & {
  color: Theme['visual']['color'];
  type: Theme['visual']['type'];
  motion: Theme['visual']['motion'];
};

export const DEFAULT_THEME: Theme = {
  id: 'banodoco-default',
  visual: {
    color: {
      fg: '#ffffff',
      bg: '#000000',
      accent: '#ffffff',
    },
    type: {
      families: {
        heading: 'Georgia, serif',
        body: 'Georgia, serif',
      },
      size: {
        base: 64,
        small: 36,
        large: 96,
      },
      weight: {
        normal: 400,
        bold: 700,
      },
      lineHeight: 1.1,
    },
    motion: {
      fadeMs: 250,
    },
    canvas: {
      width: 1920,
      height: 1080,
      fps: 30,
    },
  },
};

const toRuntimeTheme = (theme: Theme): RuntimeTheme => {
  return {
    ...theme,
    color: theme.visual.color,
    type: theme.visual.type,
    motion: theme.visual.motion,
  };
};

const DEFAULT_RUNTIME_THEME = toRuntimeTheme(DEFAULT_THEME);
const ThemeContext = createContext<RuntimeTheme>(DEFAULT_RUNTIME_THEME);

export const ThemeProvider = ({
  children,
  value,
}: {
  children: ReactNode;
  value?: Theme;
}): ReactNode => {
  return <ThemeContext.Provider value={value === undefined ? DEFAULT_RUNTIME_THEME : toRuntimeTheme(value)}>{children}</ThemeContext.Provider>;
};

export const useTheme = (): RuntimeTheme => {
  return useContext(ThemeContext);
};

// Sprint 5: physically moved + renamed from
// tools/remotion/src/HypeComposition.tsx → TimelineComposition.tsx.
//
// Composition id rename: `HypeComposition` → `TimelineComposition`.
// Banodoco's CLI render path passes the new id; the in-tree shell at
// tools/remotion/src/Root.tsx imports this composition from the package.

import type {ReactElement} from 'react';
import {AbsoluteFill, Sequence, useVideoConfig} from 'remotion';
import {AudioTrack} from './AudioTrack';
import {CLIP_TYPE_ALIASES, EFFECT_REGISTRY, type EffectId} from './effects.generated';
import {DEFAULT_THEME, ThemeProvider, useTheme} from './ThemeContext';
import {VisualClip} from './VisualClip';
import {resolveParams} from './lib/effect-params';
import {getClipDurationInFrames} from './lib/duration';
import {getAudioTracks, getVisualTracks} from './lib/tracks';
import {
  CrossFadeLayer,
  TransitionSeries,
  resolveTransitionReference,
} from './lib/transitions';
import type {
  AssetRegistryEntry,
  HypeCompositionProps,
  TimelineClip,
  TimelineCompositionProps,
  TrackDefinition,
} from './types';

const sortClipsByAt = (clips: TimelineClip[]): TimelineClip[] => {
  return [...clips].sort((left, right) => left.at - right.at);
};

const hasPositionOverride = (clip: TimelineClip): boolean => {
  return (
    clip.x !== undefined
    || clip.y !== undefined
    || clip.width !== undefined
    || clip.height !== undefined
    || clip.cropTop !== undefined
    || clip.cropBottom !== undefined
    || clip.cropLeft !== undefined
    || clip.cropRight !== undefined
  );
};

const getAssetEntry = (
  clip: TimelineClip,
  assets: TimelineCompositionProps['assets'],
): AssetRegistryEntry | undefined => {
  return clip.asset ? assets.assets[clip.asset] : undefined;
};

const renderVisualClipContent = (
  track: TrackDefinition,
  clip: TimelineClip,
  assets: TimelineCompositionProps['assets'],
  fps: number,
  theme: ReturnType<typeof useTheme>,
): ReactElement | null => {
  if (clip.clipType === 'effect-layer') {
    return null;
  }

  // Sprint 5 EFFECT_REGISTRY dispatch (the migration target cited at
  // tools/remotion/src/HypeComposition.tsx:58-64). Same shape; the
  // registry now lives inside the package.
  const effectId = (
    clip.clipType && clip.clipType in EFFECT_REGISTRY
      ? clip.clipType as EffectId
      : clip.clipType ? CLIP_TYPE_ALIASES[clip.clipType] : undefined
  );
  if (effectId) {
    const EffectComponent = EFFECT_REGISTRY[effectId];
    const assetEntry = getAssetEntry(clip, assets);
    return (
      <EffectComponent
        clip={clip}
        params={resolveParams(clip)}
        theme={theme}
        fps={fps}
        assetEntry={assetEntry}
      />
    );
  }

  const assetEntry = getAssetEntry(clip, assets);
  const baseVisual = (
    <VisualClip clip={clip} track={track} assetEntry={assetEntry} fps={fps} />
  );

  if (hasPositionOverride(clip)) {
    return baseVisual;
  }

  if ((track.scale ?? 1) !== 1) {
    return (
      <AbsoluteFill
        style={{
          transform: `scale(${track.scale})`,
          transformOrigin: 'center center',
          overflow: 'hidden',
          isolation: 'isolate',
        }}
      >
        {baseVisual}
      </AbsoluteFill>
    );
  }

  return baseVisual;
};

const renderVisualSequence = (
  track: TrackDefinition,
  clip: TimelineClip,
  assets: TimelineCompositionProps['assets'],
  fps: number,
  theme: ReturnType<typeof useTheme>,
): ReactElement | null => {
  const content = renderVisualClipContent(track, clip, assets, fps, theme);
  if (!content) {
    return null;
  }
  return (
    <Sequence
      key={clip.id}
      from={Math.round(clip.at * fps)}
      durationInFrames={getClipDurationInFrames(clip, fps)}
    >
      {content}
    </Sequence>
  );
};

const renderTransitionGroup = (
  track: TrackDefinition,
  fromClip: TimelineClip,
  toClip: TimelineClip,
  assets: TimelineCompositionProps['assets'],
  fps: number,
  theme: ReturnType<typeof useTheme>,
): ReactElement | null => {
  const transition = resolveTransitionReference(fromClip.transition as never, theme, fps);
  if (!transition) {
    return null;
  }
  const fromDuration = getClipDurationInFrames(fromClip, fps);
  const toDuration = getClipDurationInFrames(toClip, fps);
  if (transition.durationFrames <= 0 || transition.durationFrames > fromDuration || transition.durationFrames > toDuration) {
    return null;
  }

  const fromContent = renderVisualClipContent(track, fromClip, assets, fps, theme);
  const toContent = renderVisualClipContent(track, toClip, assets, fps, theme);
  if (!fromContent || !toContent) {
    return null;
  }

  const groupFrom = Math.round(fromClip.at * fps);
  const toOffset = Math.max(0, fromDuration - transition.durationFrames);
  const groupDuration = toOffset + toDuration;
  return (
    <Sequence
      key={`${fromClip.id}-${toClip.id}-transition`}
      from={groupFrom}
      durationInFrames={groupDuration}
    >
      <TransitionSeries>
        <Sequence from={0} durationInFrames={fromDuration}>
          <CrossFadeLayer
            role="from"
            durationFrames={fromDuration}
            transitionDurationFrames={transition.durationFrames}
          >
            {fromContent}
          </CrossFadeLayer>
        </Sequence>
        <Sequence from={toOffset} durationInFrames={toDuration}>
          <CrossFadeLayer
            role="to"
            durationFrames={toDuration}
            transitionDurationFrames={transition.durationFrames}
          >
            {toContent}
          </CrossFadeLayer>
        </Sequence>
      </TransitionSeries>
    </Sequence>
  );
};

const clipsCanTransition = (fromClip: TimelineClip, toClip: TimelineClip, fps: number): boolean => {
  if (!fromClip.transition || fromClip.clipType === 'effect-layer' || toClip.clipType === 'effect-layer') {
    return false;
  }
  const fromStart = Math.round(fromClip.at * fps);
  const fromEnd = fromStart + getClipDurationInFrames(fromClip, fps);
  const toStart = Math.round(toClip.at * fps);
  return toStart >= fromStart && toStart <= fromEnd;
};

const renderVisualTrack = (
  track: TrackDefinition,
  clips: TimelineClip[],
  assets: TimelineCompositionProps['assets'],
  fps: number,
  theme: ReturnType<typeof useTheme>,
): ReactElement | null => {
  const sortedClips = sortClipsByAt(clips);
  if (sortedClips.length === 0) {
    return null;
  }

  const rendered: Array<ReactElement | null> = [];
  for (let index = 0; index < sortedClips.length; index += 1) {
    const clip = sortedClips[index];
    const nextClip = sortedClips[index + 1];
    if (nextClip && clipsCanTransition(clip, nextClip, fps)) {
      const group = renderTransitionGroup(track, clip, nextClip, assets, fps, theme);
      if (group) {
        rendered.push(group);
        index += 1;
        continue;
      }
    }
    rendered.push(renderVisualSequence(track, clip, assets, fps, theme));
  }

  return (
    <AbsoluteFill
      key={track.id}
      style={{
        opacity: track.opacity ?? 1,
        mixBlendMode: track.blendMode && track.blendMode !== 'normal' ? track.blendMode : undefined,
      }}
    >
      {rendered}
    </AbsoluteFill>
  );
};

const renderAudioTrack = (
  track: TrackDefinition,
  clips: TimelineClip[],
  assets: TimelineCompositionProps['assets'],
  fps: number,
): ReactElement[] => {
  return sortClipsByAt(clips).map((clip) => {
    const assetEntry = getAssetEntry(clip, assets);
    return (
      <Sequence
        key={clip.id}
        from={Math.round(clip.at * fps)}
        durationInFrames={getClipDurationInFrames(clip, fps)}
      >
        <AudioTrack clip={clip} track={track} assetEntry={assetEntry} fps={fps} />
      </Sequence>
    );
  });
};

export const TimelineComposition = (props: TimelineCompositionProps): ReactElement => {
  const {timeline, assets} = props;
  const {fps, width, height} = useVideoConfig();
  const visualTracks = [...getVisualTracks(timeline)].reverse();
  const audioTracks = getAudioTracks(timeline);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: props.theme?.visual.color.bg ?? 'black',
        width,
        height,
        overflow: 'hidden',
      }}
    >
      <ThemeProvider value={props.theme ?? DEFAULT_THEME}>
        <TimelineCompositionBody
          timeline={timeline}
          assets={assets}
          visualTracks={visualTracks}
          audioTracks={audioTracks}
          fps={fps}
        />
      </ThemeProvider>
    </AbsoluteFill>
  );
};

// Backwards-compatibility alias for callers that haven't migrated off the
// HypeComposition name yet. The exported component identity is the same.
export const HypeComposition = TimelineComposition;
export type {HypeCompositionProps, TimelineCompositionProps};

const TimelineCompositionBody = ({
  timeline,
  assets,
  visualTracks,
  audioTracks,
  fps,
}: {
  timeline: TimelineCompositionProps['timeline'];
  assets: TimelineCompositionProps['assets'];
  visualTracks: TrackDefinition[];
  audioTracks: TrackDefinition[];
  fps: number;
}): ReactElement => {
  const theme = useTheme();
  return (
    <>
      <AbsoluteFill style={{position: 'relative', overflow: 'hidden'}}>
        {visualTracks.map((track) => {
          const clips = timeline.clips.filter((clip) => clip.track === track.id);
          return renderVisualTrack(track, clips, assets, fps, theme);
        })}
      </AbsoluteFill>
      {audioTracks.map((track) => {
        const clips = timeline.clips.filter((clip) => clip.track === track.id);
        return renderAudioTrack(track, clips, assets, fps);
      })}
    </>
  );
};

import type {CSSProperties, FC} from 'react';
import {Img, staticFile, useVideoConfig} from 'remotion';
import {Video} from '@remotion/media';
import type {AssetRegistryEntry, TimelineClip, TrackDefinition} from './types';
import {
  getSanitizedPlaybackRate,
  getSanitizedVolume,
} from './lib/duration';
import {
  computeViewportMediaLayout,
  getIntrinsicMediaSize,
  normalizeRenderCropValues,
} from './lib/render-bounds';
import {useFadeOpacity} from './lib/fade';
import {computeMediaTrim} from './lib/trim';

type VisualClipProps = {
  clip: TimelineClip;
  track: TrackDefinition;
  assetEntry?: AssetRegistryEntry;
  fps: number;
};

const toRenderableFileUrl = (file: string | undefined): string | null => {
  if (typeof file !== 'string' || file.trim().length === 0) {
    return null;
  }

  if (file.startsWith('http://') || file.startsWith('https://')) {
    return file;
  }

  return staticFile(file);
};

export const VisualClip: FC<VisualClipProps> = ({clip, track, assetEntry, fps}) => {
  const {width: compositionWidth, height: compositionHeight} = useVideoConfig();
  const fileUrl = toRenderableFileUrl(assetEntry?.file);
  if (!fileUrl || !assetEntry) {
    return null;
  }

  const hasPositionOverride = (
    clip.x !== undefined
    || clip.y !== undefined
    || clip.width !== undefined
    || clip.height !== undefined
    || clip.cropTop !== undefined
    || clip.cropBottom !== undefined
    || clip.cropLeft !== undefined
    || clip.cropRight !== undefined
  );
  const useViewportLayout = (track.fit ?? 'contain') === 'manual' || hasPositionOverride;
  const effectiveVolume = track.muted
    ? 0
    : getSanitizedVolume(track.volume ?? 1) * getSanitizedVolume(clip.volume ?? 1);
  const opacity = useFadeOpacity(clip, fps) * (clip.opacity ?? 1);
  const mixBlendMode = track.blendMode && track.blendMode !== 'normal' ? track.blendMode : undefined;
  const isImage = assetEntry.type?.startsWith('image');

  if (!useViewportLayout) {
    const sharedStyle: CSSProperties = {
      width: '100%',
      height: '100%',
      objectFit: track.fit === 'cover' ? 'cover' : 'contain',
      opacity,
      mixBlendMode,
    };

    if (isImage) {
      return <Img src={fileUrl} style={sharedStyle} crossOrigin="anonymous" />;
    }

    return (
      <Video
        src={fileUrl}
        {...computeMediaTrim(clip, fps)}
        playbackRate={getSanitizedPlaybackRate(clip.speed)}
        volume={effectiveVolume}
        muted={effectiveVolume <= 0}
        style={sharedStyle}
      />
    );
  }

  const fullBounds = {
    x: clip.x ?? 0,
    y: clip.y ?? 0,
    width: clip.width ?? compositionWidth,
    height: clip.height ?? compositionHeight,
  };
  const cropValues = normalizeRenderCropValues({
    cropTop: clip.cropTop,
    cropBottom: clip.cropBottom,
    cropLeft: clip.cropLeft,
    cropRight: clip.cropRight,
  });
  const intrinsicSize = getIntrinsicMediaSize(assetEntry.resolution);
  const viewportLayout = computeViewportMediaLayout({
    fullBounds,
    cropValues,
    compositionWidth,
    compositionHeight,
    intrinsicWidth: intrinsicSize.width,
    intrinsicHeight: intrinsicSize.height,
  });

  if (!viewportLayout) {
    return null;
  }

  const outerStyle: CSSProperties = {
    position: 'absolute',
    left: viewportLayout.renderBounds.x,
    top: viewportLayout.renderBounds.y,
    width: viewportLayout.renderBounds.width,
    height: viewportLayout.renderBounds.height,
    overflow: 'hidden',
    opacity,
  };
  const innerStyle: CSSProperties = {
    position: 'absolute',
    left: viewportLayout.mediaBounds.x,
    top: viewportLayout.mediaBounds.y,
    width: viewportLayout.mediaBounds.width,
