import type {ReactNode} from 'react';
import {
  ANIMATION_DEFAULTS,
  ANIMATION_META,
  ANIMATION_REGISTRY,
} from '../animations.generated';
import type {
  AnimationComponent,
  AnimationPhase,
  AnimationReference,
  AnimationReferenceList,
  AnimationMeta,
  HookAnimationComponent,
  HookAnimationResult,
  WrapperAnimationComponent,
} from '../effects-types';
import type {RuntimeTheme} from '../ThemeContext';
import type {TimelineClip} from '../types';

export type NormalizedAnimationReference = {
  id: string;
  durationFrames?: number;
  easing?: string;
  params: Record<string, unknown>;
};

export type ResolvedAnimation = NormalizedAnimationReference & {
  component: AnimationComponent;
  kind: 'wrapper' | 'hook';
  phase: AnimationPhase;
  durationFrames: number;
};

export type ComposeAnimationsInput = {
  clip: TimelineClip;
  refs: AnimationReferenceList | undefined;
  phase: AnimationPhase;
  content: ReactNode;
  text?: string;
  theme: RuntimeTheme;
  fps: number;
  elapsedFrames: number;
};

const isObjectReference = (value: unknown): value is Exclude<AnimationReference, string> => {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
};

const animationRegistry = ANIMATION_REGISTRY as Record<string, AnimationComponent | undefined>;
const animationDefaults = ANIMATION_DEFAULTS as Record<string, Record<string, unknown> | undefined>;
const animationMeta = ANIMATION_META as Record<string, AnimationMeta | undefined>;

const hasAnimationId = (id: string): boolean => Object.prototype.hasOwnProperty.call(animationRegistry, id);

export const normalizeAnimationReferences = (
  refs: AnimationReferenceList | undefined,
): NormalizedAnimationReference[] => {
  if (refs === undefined) {
    return [];
  }
  const refList = Array.isArray(refs) ? refs : [refs];
  return refList.map((ref) => {
    if (typeof ref === 'string') {
      if (!hasAnimationId(ref)) {
        throw new Error(`Unknown animation id '${ref}'`);
      }
      return {id: ref, params: {}};
    }
    if (!isObjectReference(ref) || typeof ref.id !== 'string' || ref.id.length === 0) {
      throw new Error('Animation reference objects must include a non-empty string id');
    }
    if (!hasAnimationId(ref.id)) {
      throw new Error(`Unknown animation id '${ref.id}'`);
    }
    return {
      id: ref.id,
      durationFrames: ref.durationFrames,
      easing: typeof ref.easing === 'string' ? ref.easing : undefined,
      params: ref.params && typeof ref.params === 'object' ? {...ref.params} : {},
    };
  });
};

export const resolveAnimationReferences = (
  refs: AnimationReferenceList | undefined,
  phase: AnimationPhase,
): ResolvedAnimation[] => {
  return normalizeAnimationReferences(refs).map((ref) => {
    const meta = animationMeta[ref.id];
    if (!meta) {
      throw new Error(`Unknown animation id '${ref.id}'`);
    }
    const metaPhase = meta.phase ?? 'any';
    const phaseMatches = metaPhase === 'any'
      || metaPhase === phase
      || (Array.isArray(metaPhase) && metaPhase.includes(phase));
    if (!phaseMatches) {
      throw new Error(`Animation '${ref.id}' is phase '${meta.phase}', not '${phase}'`);
    }

    const defaults = animationDefaults[ref.id] ?? {};
    const defaultDuration = typeof defaults.durationFrames === 'number'
      ? defaults.durationFrames
      : meta.defaultDurationFrames;
    const durationFrames = ref.durationFrames ?? defaultDuration;
    if (typeof durationFrames !== 'number' || !Number.isFinite(durationFrames) || durationFrames < 0) {
      throw new Error(`Animation '${ref.id}' must resolve to a non-negative durationFrames value`);
    }

    return {
      ...ref,
      params: {...defaults, ...ref.params},
      component: animationRegistry[ref.id] as AnimationComponent,
      kind: meta.kind,
      phase,
      durationFrames,
    };
  });
};

const isHookResultObject = (value: unknown): value is HookAnimationResult => {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
};

export const composeAnimations = ({
  clip,
  refs,
  phase,
  content,
  text,
  theme,
  fps,
  elapsedFrames,
}: ComposeAnimationsInput): ReactNode => {
  const resolved = resolveAnimationReferences(refs, phase);
  const hookAnimations = resolved.filter((animation) => animation.kind === 'hook');
  const wrapperAnimations = resolved.filter((animation) => animation.kind === 'wrapper');

  let nextContent = content;
  let nextText = text;
  let nextParams: Record<string, unknown> = {};

  for (const animation of hookAnimations) {
    const HookComponent = animation.component as HookAnimationComponent<Record<string, unknown>>;
    const result = HookComponent({
      clip,
      params: animation.params,
      theme,
      fps,
      phase,
      durationFrames: animation.durationFrames,
      elapsedFrames,
      animationId: animation.id,
      content: nextContent,
      text: nextText,
    });
    if (isHookResultObject(result)) {
      nextContent = result.content ?? nextContent;
      nextText = result.text ?? nextText;
      nextParams = {...nextParams, ...(result.params ?? {})};
    } else {
      nextContent = result;
    }
  }

  return wrapperAnimations.reduceRight((children, animation) => {
    const WrapperComponent = animation.component as WrapperAnimationComponent<Record<string, unknown>>;
    return (
      <WrapperComponent
        clip={clip}
        params={{...animation.params, ...nextParams}}
        theme={theme}
        fps={fps}
        phase={phase}
        durationFrames={animation.durationFrames}
        elapsedFrames={elapsedFrames}
        animationId={animation.id}
      >
        {children}
      </WrapperComponent>
    );
  }, nextContent);
};

import type {TimelineClip, TimelineConfig} from '../types';

export const secondsToFrames = (seconds: number, fps: number): number => {
  return Math.round(seconds * fps);
};

export const getClipSourceDuration = (clip: TimelineClip): number => {
  if (typeof clip.hold === 'number') {
    return clip.hold;
  }

  return (clip.to ?? 0) - (clip.from ?? 0);
};

export const getClipTimelineDuration = (clip: TimelineClip): number => {
  const speed = clip.speed ?? 1;
  return getClipSourceDuration(clip) / speed;
};

export const getSanitizedPlaybackRate = (speed: TimelineClip['speed']): number => {
  return typeof speed === 'number' && Number.isFinite(speed) && speed > 0 ? speed : 1;
};

export const getSanitizedVolume = (volume: number | undefined, fallback = 1): number => {
  return typeof volume === 'number' && Number.isFinite(volume)
    ? Math.max(0, volume)
    : fallback;
};

export const getClipDurationInFrames = (clip: TimelineClip, fps: number): number => {
  return Math.max(1, secondsToFrames(getClipTimelineDuration(clip), fps));
};

export const getTimelineDurationInFrames = (timeline: TimelineConfig, fps: number): number => {
  return Math.max(
    1,
    ...timeline.clips.map((clip) => {
      return secondsToFrames(clip.at, fps) + getClipDurationInFrames(clip, fps);
    }),
  );
};

import type {TimelineClip} from '../types';

export const resolveParams = (clip: TimelineClip): unknown => {
  if (clip.clipType === 'text') {
    return clip.text;
  }
  return clip.params;
};

import {interpolate, useCurrentFrame} from 'remotion';
import type {TimelineClip} from '../types';
import {getClipDurationInFrames, secondsToFrames} from './duration';

const getEffectValue = (
  effects: TimelineClip['effects'],
  name: 'fade_in' | 'fade_out',
): number | null => {
  if (!effects) {
    return null;
  }

  if (!Array.isArray(effects)) {
    const effectsObj = effects as Record<string, unknown>;
    return typeof effectsObj[name] === 'number' ? (effectsObj[name] as number) : null;
  }

  for (const effect of effects as Array<Record<string, unknown>>) {
    if (typeof effect[name] === 'number') {
      return (effect[name] as number) ?? null;
    }
  }

  return null;
};

export const useFadeOpacity = (clip: TimelineClip, fps: number): number => {
  const frame = useCurrentFrame();
  const durationInFrames = getClipDurationInFrames(clip, fps);
  let opacity = 1;

  const fadeInSeconds = getEffectValue(clip.effects, 'fade_in');
  if (typeof fadeInSeconds === 'number' && Number.isFinite(fadeInSeconds) && fadeInSeconds > 0) {
    const fadeInFrames = secondsToFrames(fadeInSeconds, fps);
    opacity *= interpolate(frame, [0, fadeInFrames], [0, 1], {
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    });
  }

  const fadeOutSeconds = getEffectValue(clip.effects, 'fade_out');
  if (typeof fadeOutSeconds === 'number' && Number.isFinite(fadeOutSeconds) && fadeOutSeconds > 0) {
    const fadeOutFrames = secondsToFrames(fadeOutSeconds, fps);
    opacity *= interpolate(frame, [durationInFrames - fadeOutFrames, durationInFrames], [1, 0], {
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    });
  }

  return opacity;
};

export type RenderBounds = {
  x: number;
  y: number;
  width: number;
  height: number;
};

export type RenderCropValues = {
  cropTop: number;
  cropBottom: number;
  cropLeft: number;
  cropRight: number;
};

export type ViewportMediaLayout = {
  fullBounds: RenderBounds;
  visibleBounds: RenderBounds;
  renderBounds: RenderBounds;
  mediaBounds: RenderBounds;
  cropValues: RenderCropValues;
};

export type IntrinsicMediaSize = {
  width?: number;
  height?: number;
};

const clamp = (value: number, min: number, max: number): number => Math.min(max, Math.max(min, value));

export const normalizeRenderCropValues = (cropValues?: Partial<RenderCropValues>): RenderCropValues => {
  let cropTop = clamp(cropValues?.cropTop ?? 0, 0, 1);
  let cropBottom = clamp(cropValues?.cropBottom ?? 0, 0, 1);
  let cropLeft = clamp(cropValues?.cropLeft ?? 0, 0, 1);
  let cropRight = clamp(cropValues?.cropRight ?? 0, 0, 1);

  const horizontalTotal = cropLeft + cropRight;
  if (horizontalTotal > 0.99) {
    const scale = 0.99 / horizontalTotal;
    cropLeft *= scale;
    cropRight *= scale;
  }

  const verticalTotal = cropTop + cropBottom;
  if (verticalTotal > 0.99) {
    const scale = 0.99 / verticalTotal;
    cropTop *= scale;
    cropBottom *= scale;
  }

  return {cropTop, cropBottom, cropLeft, cropRight};
};

export const getVisibleBoundsFromCrop = (
  fullBounds: RenderBounds,
  cropValues?: Partial<RenderCropValues>,
): RenderBounds => {
  const normalizedCrop = normalizeRenderCropValues(cropValues);
  const visibleWidthFactor = Math.max(0.01, 1 - normalizedCrop.cropLeft - normalizedCrop.cropRight);
  const visibleHeightFactor = Math.max(0.01, 1 - normalizedCrop.cropTop - normalizedCrop.cropBottom);

  return {
    x: fullBounds.x + fullBounds.width * normalizedCrop.cropLeft,
    y: fullBounds.y + fullBounds.height * normalizedCrop.cropTop,
    width: fullBounds.width * visibleWidthFactor,
    height: fullBounds.height * visibleHeightFactor,
  };
};

export const getIntrinsicMediaSize = (resolution?: string | null): IntrinsicMediaSize => {
  if (!resolution) {
    return {};
  }

  const [widthText, heightText] = resolution.toLowerCase().split('x');
  const width = Number(widthText);
  const height = Number(heightText);
  return Number.isFinite(width) && width > 0 && Number.isFinite(height) && height > 0
    ? {width, height}
    : {};
};

export const computeRenderBounds = (
  bounds: RenderBounds,
  compositionWidth: number,
  compositionHeight: number,
): RenderBounds => {
  const right = Math.min(bounds.x + bounds.width, compositionWidth);
  const bottom = Math.min(bounds.y + bounds.height, compositionHeight);
  const x = Math.max(0, bounds.x);
  const y = Math.max(0, bounds.y);

  return {
    x,
    y,
    width: Math.max(0, right - x),
    height: Math.max(0, bottom - y),
  };
};

export const hasRenderableBounds = (bounds: RenderBounds): boolean => {
  return bounds.width > 0 && bounds.height > 0;
};

export const computeViewportMediaLayout = ({
  fullBounds,
  cropValues,
  compositionWidth,
  compositionHeight,
  intrinsicWidth,
  intrinsicHeight,
}: {
  fullBounds: RenderBounds;
  cropValues?: Partial<RenderCropValues>;
  compositionWidth: number;
  compositionHeight: number;
  intrinsicWidth?: number;
  intrinsicHeight?: number;
}): ViewportMediaLayout | null => {
  const normalizedCrop = normalizeRenderCropValues(cropValues);
  const visibleBounds = getVisibleBoundsFromCrop(fullBounds, normalizedCrop);
  const renderBounds = computeRenderBounds(visibleBounds, compositionWidth, compositionHeight);

  if (!hasRenderableBounds(renderBounds)) {
    return null;
  }

  const safeIntrinsicWidth = intrinsicWidth && intrinsicWidth > 0 ? intrinsicWidth : fullBounds.width;
  const safeIntrinsicHeight = intrinsicHeight && intrinsicHeight > 0 ? intrinsicHeight : fullBounds.height;
  const coverScale = Math.max(
    fullBounds.width / Math.max(1, safeIntrinsicWidth),
    fullBounds.height / Math.max(1, safeIntrinsicHeight),
  );
  const mediaWidth = safeIntrinsicWidth * coverScale;
  const mediaHeight = safeIntrinsicHeight * coverScale;
  const mediaOffsetX = (fullBounds.width - mediaWidth) / 2;
  const mediaOffsetY = (fullBounds.height - mediaHeight) / 2;
  const viewportOffsetX = renderBounds.x - fullBounds.x;
  const viewportOffsetY = renderBounds.y - fullBounds.y;

  return {
    fullBounds,
    visibleBounds,
    renderBounds,
    mediaBounds: {
      x: mediaOffsetX - viewportOffsetX,
      y: mediaOffsetY - viewportOffsetY,
      width: mediaWidth,
      height: mediaHeight,
    },
    cropValues: normalizedCrop,
  };
};

